import { Book } from "@/lib/types";

export const job: Book = {
  id: "job",
  name: "Hiob",
  shortName: "Hi",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Es war ein Mann im Lande Uz*, sein Name war Hiob*. Und dieser Mann war rechtschaffen und redlich* und gottesfürchtig und mied das Böse*.", heading: "Gerechtigkeit des Hiob, sein Wohlstand und seine Sorge um die Gottesfurcht seiner Kinder", footnotes: ["℘ 1Mo 10,23; Jer 25,20; Kla 4,21", "℘ Hes 14,14.20; Jak 5,11", "o. lauter und aufrichtig\n℘ 1Mo 6,9", "℘ Spr 14,16; 16,17; 1Thes 5,22"] },
      { number: 2, text: "Ihm wurden sieben Söhne* und drei Töchter geboren*.", footnotes: ["℘ Ps 127,3", "℘ Kap. 42,12.13"] },
      { number: 3, text: "Und sein Besitz bestand aus siebentausend Schafen und dreitausend Kamelen und fünfhundert Gespannen Rinder und fünfhundert Eselinnen, und <seine> Dienerschaft war sehr zahlreich*, so dass dieser Mann größer war als alle Söhne des Ostens*.", footnotes: ["℘ 1Mo 24,35", "℘ Ri 6,3"] },
      { number: 4, text: "Nun pflegten seine Söhne hinzugehen und Gastmahl zu halten — der Reihe nach im Haus eines jeden*. <Dazu> sandten sie hin und luden ihre drei Schwestern ein, mit ihnen zu essen und zu trinken.", footnotes: ["w. im Haus eines jeden an seinem Tag"] },
      { number: 5, text: "Und es geschah, wenn die Tage des Gastmahls reihum gegangen waren, da sandte Hiob hin* und heiligte sie*: Früh am Morgen stand er auf und opferte Brandopfer nach ihrer aller Zahl. Denn Hiob sagte <sich>: Vielleicht haben meine Söhne gesündigt und in ihrem Herzen Gott geflucht*. So machte es Hiob all die Tage <nach den Gastmählern>.", footnotes: ["d. h. er ließ sie holen", "℘ 1Sam 16,5", "w. gesegnet. — Der Ausdruck ist eine verhüllende Rede, die das Gegenteil des Gemeinten formuliert, um ein anstößiges Wort zu vermeiden."] },
      { number: 6, text: "Und es geschah eines Tages, da kamen die Söhne Gottes*, um sich vor dem HERRN einzufinden. Und auch der Satan* kam in ihrer Mitte*.", heading: "Satans Vorsprache bei Gott — Hiobs Bewährung nach Verlust von Vieh, Knechten, Söhnen und Töchtern", footnotes: ["℘ 1Mo 6,2", "o. der Widersacher; vgl. Anm. zu 1Sam 29,4\n℘ 1Chr 21,1; Offb 12,9.10", "℘ 1Kö 22,19"] },
      { number: 7, text: "Und der HERR sprach zum Satan: Woher kommst du? Und der Satan antwortete dem HERRN und sagte: Vom Durchstreifen der Erde und vom Umherwandern auf ihr*.", footnotes: ["℘ Sach 1,11"] },
      { number: 8, text: "Und der HERR sprach zum Satan: Hast du achtgehabt auf meinen Knecht Hiob? Denn es gibt keinen wie ihn auf Erden — ein Mann, so rechtschaffen und redlich*, der Gott fürchtet und das Böse meidet*!", footnotes: ["o. lauter und aufrichtig", "℘ Kap. 2,1-3; Lk 1,6"] },
      { number: 9, text: "Und der Satan* antwortete dem HERRN und sagte: Ist Hiob <etwa> umsonst* so gottesfürchtig*?", footnotes: ["o. der Widersacher; vgl. Anm. zu 1Sam 29,4", "o. ohne Gegenleistung", "℘ Offb 12,10"] },
      { number: 10, text: "Hast du selbst nicht ihn und sein Haus und alles, was er hat, rings umhegt? Das Werk seiner Hände hast du gesegnet, und sein Besitz hat sich im Land ausgebreitet*.", footnotes: ["℘ 5Mo 7,13; Ps 5,13"] },
      { number: 11, text: "Strecke jedoch nur einmal deine Hand aus und taste alles an, was er hat, ob er dir nicht ins Angesicht flucht*!", footnotes: ["w. ob er dich nicht ins Angesicht segnet; vgl. Anm. zu V. 5\n℘ Kap. 2,3; Jes 8,21; Lk 22,31; 1Petr 5,8"] },
      { number: 12, text: "Da sprach der HERR zum Satan: Siehe, alles, was er hat, ist in deiner Hand. Nur gegen ihn <selbst> strecke deine Hand nicht aus! Und der Satan* ging vom Angesicht des HERRN fort*.", footnotes: ["o. der Widersacher; vgl. Anm. zu 1Sam 29,4", "℘ Kap. 2,5.6; 1Kö 22,22"] },
      { number: 13, text: "Und es geschah eines Tages, als seine Söhne und seine Töchter im Haus ihres erstgeborenen Bruders aßen und Wein tranken," },
      { number: 14, text: "da kam ein Bote zu Hiob und sagte: Die Rinder waren gerade beim Pflügen, und die Eselinnen weideten neben ihnen," },
      { number: 15, text: "da fielen Sabäer* ein und nahmen sie weg und die Knechte erschlugen sie mit der Schärfe des Schwertes. Ich aber bin entkommen, nur ich allein, um es dir zu berichten.", footnotes: ["℘ Kap. 6,19; 1Mo 10,7; Jes 45,14; Joe 4,8"] },
      { number: 16, text: "Noch redete der, da kam ein anderer und sagte: Feuer Gottes fiel vom Himmel*, brannte unter den Schafen und den Knechten und verzehrte sie. Ich aber bin entkommen, nur ich allein, um es dir zu berichten.", footnotes: ["℘ 2Kö 1,10.12"] },
      { number: 17, text: "Noch redete der, da kam ein anderer und sagte: <Die> Chaldäer hatten drei Abteilungen aufgestellt und sind über die Kamele hergefallen und haben sie weggenommen, und die Knechte haben sie mit der Schärfe des Schwertes erschlagen. Ich aber bin entkommen, nur ich allein, um es dir zu berichten." },
      { number: 18, text: "Während der <noch> redete, da kam ein anderer und sagte: Deine Söhne und deine Töchter aßen und tranken Wein im Haus ihres erstgeborenen Bruders." },
      { number: 19, text: "Und siehe, ein starker Wind kam von jenseits der Wüste her und stieß an die vier Ecken des Hauses. Da fiel es auf die jungen Leute, und sie starben. Ich aber bin entkommen, nur ich allein, um es dir zu berichten. —" },
      { number: 20, text: "Da stand Hiob auf und zerriss sein Obergewand* und schor sein Haupt*; und er fiel auf die Erde* und betete an*.", footnotes: ["℘ Kap. 2,12; 1Mo 37,29.34", "℘ Jer 7,29", "℘ Jos 7,6", "w. und warf sich nieder\n℘ 2Mo 4,31; 2Sam 12,20"] },
      { number: 21, text: "Und er sagte: Nackt bin ich aus meiner Mutter Leib gekommen, und nackt kehre ich dahin zurück*. Der HERR hat gegeben, und der HERR hat genommen*, der Name des HERRN sei gepriesen*!", footnotes: ["℘ Pred 5,14; 1Tim 6,7", "℘ Kap. 9,12; 1Sam 2,7; Rt 1,21", "℘ Neh 9,5; Ps 34,2; Eph 5,20"] },
      { number: 22, text: "Bei alldem sündigte Hiob nicht* und legte Gott nichts Anstößiges zur Last*.", footnotes: ["℘ Kap. 2,10", "℘ Pred 8,14; Mal 3,15; Jak 5,11"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und es geschah eines Tages, da kamen die Söhne Gottes*, um sich vor dem HERRN einzufinden. Und auch der Satan* kam in ihrer Mitte, um sich vor dem HERRN einzufinden.", heading: "Satans erneute Vorsprache bei Gott — Hiobs Bewährung nach Verlust der Gesundheit", footnotes: ["℘ Kap. 38,7", "o. der Widersacher; vgl. Anm. zu 1Sam 29,4"] },
      { number: 2, text: "Und der HERR sprach zum Satan: Von woher kommst du? Und der Satan* antwortete dem HERRN und sagte: Vom Durchstreifen der Erde und vom Umherwandern auf ihr.", footnotes: ["o. der Widersacher; vgl. Anm. zu 1Sam 29,4"] },
      { number: 3, text: "Und der HERR sprach zum Satan: Hast du Acht gehabt auf meinen Knecht Hiob? Denn es gibt keinen wie ihn auf Erden — ein Mann, so rechtschaffen und redlich*, der Gott fürchtet und das Böse meidet*! Und noch hält er fest an seiner Rechtschaffenheit*. Und dabei hattest du mich gegen ihn aufgereizt*, ihn ohne Grund zu verschlingen.", footnotes: ["o. so lauter und aufrichtig", "℘ Kap. 1,6-8", "o. Lauterkeit\n℘ Ps 26,1", "℘ Kap. 1,11"] },
      { number: 4, text: "Da antwortete der Satan* dem HERRN und sagte: Haut für Haut! Alles, was der Mensch hat, gibt er für sein Leben*.", footnotes: ["o. der Widersacher; vgl. Anm. zu 1Sam 29,4", "o. seine Seele\n℘ 1Mo 47,19; Jos 9,24; 1Kö 20,31; Spr 13,8; Jer 41,8"] },
      { number: 5, text: "Strecke jedoch nur einmal deine Hand aus und taste sein Gebein und sein Fleisch an, ob er dir nicht ins Angesicht flucht*!", footnotes: ["w. ob er dich nicht ins Angesicht segnet; d. i. ein verhüllender Ausdruck; vgl. Anm. zu Kap. 1,5"] },
      { number: 6, text: "Da sprach der HERR zum Satan: Siehe, er ist in deiner Hand*. Nur schone sein Leben*!", footnotes: ["℘ 2Kor 12,7", "o. seine Seele\n℘ Kap. 1,11.12"] },
      { number: 7, text: "Und der Satan* ging vom Angesicht des HERRN fort* und schlug Hiob mit bösen Geschwüren, von seiner Fußsohle bis zu seinem Scheitel*.", footnotes: ["o. der Widersacher; vgl. Anm. zu 1Sam 29,4", "℘ Kap. 1,11.12", "℘ 5Mo 28,35"] },
      { number: 8, text: "Und er nahm eine Tonscherbe, um sich damit zu schaben, während er mitten in der Asche saß*.", footnotes: ["℘ Est 4,3"] },
      { number: 9, text: "Da sagte seine Frau zu ihm: Hältst du noch fest an deiner Vollkommenheit? Fluche* Gott* und stirb!", footnotes: ["w. Segne; d. i. ein verhüllender Ausdruck; vgl. Anm. zu Kap. 1,5", "℘ 2Kö 6,33"] },
      { number: 10, text: "Er aber sagte zu ihr: Wie eine der Törinnen* redet, so redest auch du. Das Gute nehmen wir von Gott an, da sollten wir das Böse nicht auch annehmen*? Bei alldem sündigte Hiob nicht mit seinen Lippen*.", footnotes: ["o. Gottlosen, o. Gottleugner; vgl. Ps 14,1; 53,2", "℘ Pred 7,14; Kla 3,37.38", "℘ Kap. 1,22; Ps 39,10"] },
      { number: 11, text: "Es hatten nun die drei Freunde Hiobs von all diesem Unglück gehört, das über ihn gekommen war. Da kamen sie, jeder aus seinem Ort: Elifas von Teman* und Bildad von Schuach* und Zofar von Naama*. Und sie verabredeten sich miteinander hinzugehen, um ihm ihre Teilnahme zu bekunden und ihn zu trösten*.", heading: "Besuch der Freunde bei Hiob", footnotes: ["℘ Kap. 4,1; 42,7; 1Mo 36,34", "℘ Kap. 8,1; 1Mo 25,2", "℘ Kap. 11,1; 42,9; Jos 15,41", "℘ Kap. 42,11; 1Mo 37,35; Joh 11,19"] },
      { number: 12, text: "Als sie aber von fern ihre Augen erhoben, erkannten sie ihn nicht <mehr>. Da erhoben sie ihre Stimme und weinten*, und sie zerrissen ein jeder sein Obergewand* und streuten Staub himmelwärts auf ihre Häupter*.", footnotes: ["℘ Röm 12,15", "℘ Kap. 1,20", "℘ Esr 9,3; Neh 9,1; Hes 27,30"] },
      { number: 13, text: "Und sie saßen bei ihm auf der Erde sieben Tage und sieben Nächte lang*. Und keiner redete ein Wort zu ihm*, denn sie sahen, dass der Schmerz sehr groß war*.", footnotes: ["℘ Hes 3,15", "℘ Kla 2,10", "℘ 1Mo 50,10"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Danach öffnete Hiob seinen Mund und verfluchte seinen Tag*.", heading: "Hiobs verzweifelte Klage", footnotes: ["℘ Jer 20,14"] },
      { number: 2, text: "Und Hiob begann und sagte*:", footnotes: ["℘ Kap. 6,1; 9,1; 12,1; 16,1; 19,1; 21,1; 23,1; 26,1; 40,3; 42,1"] },
      { number: 3, text: "Vergehen* soll der Tag, an dem ich geboren wurde, und die Nacht, die sprach: Ein Junge* wurde empfangen!", footnotes: ["o. Verloren gehen; o. Umkommen", "w. Ein Mann; o. Ein männlicher Nachkomme"] },
      { number: 4, text: "Dieser Tag sei Finsternis! Gott in der Höhe soll nicht nach ihm fragen, und kein Licht soll über ihm glänzen!" },
      { number: 5, text: "Dunkel und Finsternis* sollen ihn für sich fordern, Regenwolken sollen sich über ihm lagern, Verfinsterungen des Tages ihn erschrecken*!", footnotes: ["℘ Kap. 10,21.22; 28,3; 34,22", "T.; Mas. T.: sie sollen ihn erschrecken wie Bitterkeiten des Tages"] },
      { number: 6, text: "Diese Nacht — Dunkelheit ergreife sie! Sie freue sich nicht unter den Tagen des Jahres*, in die Zahl der Monate komme sie nicht!", footnotes: ["Andere üs. mit einigen alten Üs.: Sie reihe sich nicht ein unter die Tage des Jahres"] },
      { number: 7, text: "Siehe, diese Nacht sei unfruchtbar, kein Jubel soll in sie hineinkommen!" },
      { number: 8, text: "Es sollen sie die verwünschen, die den Tag verfluchen, die fähig* sind, den Leviatan* zu reizen!", footnotes: ["o. fertig; o. bereit", "d. i. ein Meeresungeheuer; nach anderen das Krokodil\n℘ Kap. 40,25"] },
      { number: 9, text: "Verfinstert seien die Sterne ihrer Dämmerung; sie hoffe auf Licht, und da sei keines; und sie schaue nicht die Wimpern* der Morgenröte*!", footnotes: ["o. Strahlen", "℘ Kap. 41,10"] },
      { number: 10, text: "Denn sie hat die Pforte meines Mutterschoßes nicht verschlossen und Unheil nicht vor meinen Augen verborgen." },
      { number: 11, text: "Warum starb ich nicht von Mutterleib an*, verschied ich nicht, als ich aus dem Schoß hervorkam*?", footnotes: ["LXX und Vulg.: im Mutterleib", "℘ Kap. 10,18; Pred 6,3; Jer 15,10; 20,17"] },
      { number: 12, text: "Weshalb kamen Knie mir entgegen und wozu Brüste, dass ich sog?" },
      { number: 13, text: "Denn dann läge ich <jetzt> da und wäre still. Ich schliefe* — dann hätte ich Ruhe —", footnotes: ["℘ Kap. 14,12"] },
      { number: 14, text: "mit Königen und Ratgebern der Erde*, die sich Trümmerstätten* erbauten*,", footnotes: ["℘ Jes 14,18", "Die Bedeutung des Wortes ist unklar; gemeint sind wahrscheinlich ehemals prächtige, dann aber verfallene Grabmäler.", "℘ Jes 22,16"] },
      { number: 15, text: "oder mit Obersten, die Gold hatten, die ihre Häuser mit Silber füllten*.", footnotes: ["℘ Ps 49,18"] },
      { number: 16, text: "Oder wie eine verscharrte Fehlgeburt wäre ich nicht da, wie Kinder, die das Licht nie erblickt haben*.", footnotes: ["℘ Kap. 10,19; Ps 58,9; Pred 4,3"] },
      { number: 17, text: "Dort lassen die Gottlosen ab vom Toben, und dort ruhen die, deren Kraft erschöpft ist*.", footnotes: ["℘ Pred 9,6.10"] },
      { number: 18, text: "Sorglos sind <dort> die Gefangenen allesamt, sie hören nicht mehr die Stimme des Treibers." },
      { number: 19, text: "Klein und Groß sind dort gleich*, und der Knecht ist frei von seinem Herrn.", footnotes: ["w. <Ob> klein oder groß — dort ist er <nur einer>\n℘ Kap. 21,26"] },
      { number: 20, text: "Warum gibt er dem Mühseligen Licht und Leben den Verbitterten*", footnotes: ["w. denen, die bitterer Seele sind"] },
      { number: 21, text: "— <denen>, die auf den Tod warten, und er ist nicht da, und die nach ihm graben mehr als nach verborgenen Schätzen*,", footnotes: ["℘ Kap. 6,8.9; 7,15; 11,20; Pred 4,2; Offb 9,6"] },
      { number: 22, text: "die sich bis zum Jubel freuen würden, Wonne hätten, wenn sie das Grab fänden* —,", footnotes: ["℘ Kap. 6,8.9; 7,15; 11,20; Pred 4,2; Offb 9,6"] },
      { number: 23, text: "dem Mann, dem sein Weg verborgen ist und den Gott von allen Seiten eingeschlossen hat*?", footnotes: ["℘ Kap. 13,27.28; 19,8; Ps 88,9"] },
      { number: 24, text: "Denn <noch> vor meinem Brot kommt mein Seufzen, und wie Wasser ergießt sich mein Schreien*.", footnotes: ["℘ 1Sam 7,6"] },
      { number: 25, text: "Denn ich fürchtete einen Schrecken, und er traf mich, und wovor mir bangte, das kam über mich." },
      { number: 26, text: "Ich hatte <noch> keine Ruhe und hatte <noch> keinen Frieden, und ich konnte <noch> nicht ausruhen — da kam ein Toben." },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und Elifas von Teman* antwortete und sagte:", heading: "Erste Rede des Elifas: Kein Leiden ohne Schuld — Kein Schuldloser vor Gott", footnotes: ["℘ Kap. 2,11; 15,1; 22,1; Jer 49,7"] },
      { number: 2, text: "Wenn man ein Wort an dich versucht, wird es dich ermüden*? Aber Worte zurückhalten, wer könnte das*?", footnotes: ["o. verstimmen", "℘ Kap. 32,18-20"] },
      { number: 3, text: "Siehe, du hast viele zurechtgebracht, und ermattete Hände hast du gestärkt*.", footnotes: ["℘ Kap. 16,5"] },
      { number: 4, text: "Den Stürzenden richteten deine Worte auf, und wankende Knie hast du stark gemacht*.", footnotes: ["℘ Spr 25,11; Jes 50,4; Hebr 12,12"] },
      { number: 5, text: "Doch nun kommt es an dich, und es ermüdet* dich; es trifft dich, und du bist bestürzt*.", footnotes: ["o. verstimmt", "℘ Ps 30,8; Spr 24,10"] },
      { number: 6, text: "Ist nicht deine <Gottes>furcht deine Zuversicht*, die Vollkommenheit deiner Wege deine Hoffnung*?", footnotes: ["℘ Jes 33,6", "so mit anderer Wortfolge; Mas. T.: Ist nicht deine <Gottes>furcht deine Zuversicht, deine Hoffnung und die Vollkommenheit deiner Wege\n℘ 2Kö 20,3; Ps 26,1"] },
      { number: 7, text: "Bedenke doch: Wer ist <je> als Unschuldiger umgekommen, und wo sind Rechtschaffene vertilgt worden*?", footnotes: ["℘ Ps 37,25"] },
      { number: 8, text: "So wie ich es gesehen habe: Die Unheil pflügen und Mühsal säen, die ernten es*.", footnotes: ["℘ Ps 7,16.17; Spr 22,8; Hos 10,13; Gal 6,7.8"] },
      { number: 9, text: "Vom Odem Gottes kommen sie um, und vom Hauch seiner Nase vergehen sie*.", footnotes: ["℘ Kap. 15,30; 2Mo 15,8; 2Thes 2,8"] },
      { number: 10, text: "Das Brüllen des Löwen und die Stimme des Junglöwen <sind verstummt>, und die Zähne der jungen Löwen sind ausgebrochen*.", footnotes: ["℘ Ps 58,7"] },
      { number: 11, text: "Der Löwe kommt um aus Mangel an Beute, und die Jungen der Löwin werden zerstreut*.", footnotes: ["℘ Ps 34,11"] },
      { number: 12, text: "Ein Wort stahl sich zu mir, und mein Ohr vernahm ein Geflüster davon." },
      { number: 13, text: "In beunruhigenden Gedanken<, wie sie> aus Visionen in der Nacht <entstehen>, wenn tiefer Schlaf auf Menschen fällt*,", footnotes: ["℘ Kap. 33,14.15; 1Mo 15,12; 20,3; 4Mo 12,6"] },
      { number: 14, text: "kam Schrecken und Zittern über mich, und durchschauerte alle meine Gebeine." },
      { number: 15, text: "Und ein Hauch fuhr an meinem Gesicht vorbei, das Haar an meinem Leib sträubte sich." },
      { number: 16, text: "Da stand jemand*, und ich erkannte sein Aussehen nicht, eine Gestalt war vor meinen Augen, ein leises Wehen und eine Stimme hörte ich:", footnotes: ["w. er"] },
      { number: 17, text: "Sollte ein Mensch gerechter sein als Gott* oder ein Mann reiner als sein Schöpfer?", footnotes: ["℘ Röm 3,4"] },
      { number: 18, text: "Siehe, <selbst> seinen Knechten vertraut er nicht, und seinen Engeln legt er Irrtum zur Last*;", footnotes: ["℘ Kap. 15,15; 25,4.5"] },
      { number: 19, text: "wie viel mehr denen, die in Lehmhäusern wohnen <und> deren Grund im Staub ist*! Wie Motten werden sie zertreten.", footnotes: ["℘ Kap. 10,9; 25,6; 2Kor 5,1"] },
      { number: 20, text: "Vom Morgen bis zum Abend werden sie zerschmettert*. Ohne einen Namen* kommen sie um auf ewig.", footnotes: ["℘ Ps 90,5.6", "T.; d. h. ohne männliche Nachkommen und somit ohne bleibendes Andenken; Mas. T.: ohne dass man <die Aufmerksamkeit> darauf richtet"] },
      { number: 21, text: "Nicht wahr? Wird ihr Zeltstrick an ihnen losgerissen, so sterben sie, und <zwar> nicht in Weisheit*.", footnotes: ["℘ Kap. 32,9; 36,12"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Ruf doch, ob da einer ist, der dir antwortet! Und an wen von den Heiligen willst du dich wenden*?", heading: "Warnung vor Unmut — Empfehlung von Demut und Beugung vor Gott", footnotes: ["℘ Kap. 17,3"] },
      { number: 2, text: "Denn den Toren bringt der Gram um, und den Einfältigen tötet der Eifer*.", footnotes: ["o. die Erbitterung\n℘ Spr 19,19"] },
      { number: 3, text: "Ich, ich sah einen Narren Wurzel schlagen, und sogleich verwünschte ich seine Wohnung*.", footnotes: ["Andere üs. mit LXX und der syr. Üs.: und plötzlich verfiel (verfaulte) seine Wohnstätte"] },
      { number: 4, text: "Fern vom Heil bleiben seine Kinder*, und sie werden im Tor zertreten, und kein Retter ist da.", footnotes: ["℘ Ps 109,10"] },
      { number: 5, text: "Seine Ernte verzehrt der Hungrige, und selbst aus den Dornhecken* holt er sie weg; und nach ihrem Vermögen schnappen Durstige*.", footnotes: ["Wortbedeutung unklar", "so in Anlehnung an LXX und die syr. Üs.; Mas. T.: und er schnappt . . . ihr Vermögen. Dazwischen steht ein unübersetzbares Wort."] },
      { number: 6, text: "Denn nicht kommt aus dem Staub Unheil hervor, und aus der Erde sprosst nicht Mühsal;" },
      { number: 7, text: "sondern der Mensch ist zur Mühsal geboren*, wie die Funken nach oben fliegen*.", footnotes: ["℘ Kap. 14,1; 1Mo 3,17; Pred 2,23", "w. und die Söhne des Feuers fliegen nach oben\n℘ Ps 90,10"] },
      { number: 8, text: "Ich jedoch würde Gott suchen und meine Sache vor Gott darlegen*,", footnotes: ["℘ Kap. 8,5; 11,13; Jer 11,20; Phil 4,6"] },
      { number: 9, text: "der Großes und Unerforschliches tut, Wunder bis zur Unzahl*,", footnotes: ["℘ Kap. 9,10; Ps 40,6; 72,18"] },
      { number: 10, text: "der Regen gibt auf die Fläche der Erde und Wasser sendet auf die Fläche des Feldes*,", footnotes: ["℘ Kap. 36,27; 37,6; Ps 65,11; 147,8; Jer 14,22; Hebr 6,7"] },
      { number: 11, text: "um Niedrige in die Höhe zu bringen*; und Trauernde gewinnen hohes Glück*.", footnotes: ["LXX: der Niedrige in die Höhe bringt", "℘ Kap. 8,7; Lk 1,52"] },
      { number: 12, text: "Er vereitelt die Anschläge der Klugen, und ihre Hände wirken keinen Erfolg*.", footnotes: ["℘ 1Sam 23,13; 2Sam 17,14; 2Kö 6,9; Neh 4,9; Spr 22,12"] },
      { number: 13, text: "Er fängt die Weisen in ihrer Klugheit*, und der Rat der Hinterlistigen überstürzt sich*.", footnotes: ["℘ Jer 8,9; 9,22; 1Kor 3,19", "℘ Ps 9,17; Jes 19,3; 44,25; Jer 49,7"] },
      { number: 14, text: "Am Tag stoßen sie auf Finsternis, und am Mittag tasten sie umher wie in der Nacht*.", footnotes: ["℘ Kap. 12,25; 2Mo 10,22; 5Mo 28,29; Spr 4,19; Jes 59,10"] },
      { number: 15, text: "Und er rettet vor dem Schwert, vor ihrem Mund und vor der Hand des Starken den Armen*.", footnotes: ["℘ Ps 35,10"] },
      { number: 16, text: "So wird dem Geringen Hoffnung, und die Schlechtigkeit schließt ihren Mund*.", footnotes: ["℘ Ps 107,42"] },
      { number: 17, text: "Siehe, glücklich ist der Mensch, den Gott zurechtweist*! So verwirf <denn> nicht die Züchtigung des Allmächtigen*!", footnotes: ["℘ Ps 94,12; Hebr 12,11", "℘ 5Mo 8,5; Spr 3,11; Hebr 12,5; Offb 3,19"] },
      { number: 18, text: "Denn er bereitet Schmerz und verbindet, er zerschlägt, und seine Hände heilen*.", footnotes: ["℘ 5Mo 32,39; Ps 147,3; Jer 30,17; Hos 6,1"] },
      { number: 19, text: "In sechs Nöten wird er dich retten, und in sieben* wird dich nichts Böses antasten*.", footnotes: ["℘ Spr 6,16", "℘ Ps 34,20; 66,12; 91,15; Jes 43,2; Dan 3,25-27; 6,17"] },
      { number: 20, text: "In Hungersnot kauft er dich los vom Tod und im Krieg von der Gewalt* des Schwertes*.", footnotes: ["w. aus den Händen", "℘ Ps 33,19; 118,18; Jer 39,18"] },
      { number: 21, text: "Vor der Geißel* der Zunge wirst du geborgen sein*, und du wirst dich nicht fürchten vor der Verwüstung, wenn sie kommt.", footnotes: ["so mit einer hebr. Handschr., LXX, Vulg. und der syr. Üs.; Mas. T.: In der Peitsche", "℘ Ps 31,21"] },
      { number: 22, text: "Über Verwüstung und Hunger wirst du lachen, und vor dem <Raub>wild der Erde wirst du dich nicht fürchten." },
      { number: 23, text: "Denn dein Bund wird mit den Steinen des Feldes sein, und das <Raub>wild des Feldes wird Frieden mit dir haben*.", footnotes: ["w. wird zum Frieden mit dir gebracht sein\n℘ Jes 11,8; Hes 34,25"] },
      { number: 24, text: "Und du wirst erkennen, dass dein Zelt in Frieden ist. Und schaust du nach deiner Wohnung, so wirst du nichts vermissen*.", footnotes: ["℘ Ps 112,3"] },
      { number: 25, text: "Und du wirst erkennen, dass deine Nachkommen zahlreich sein werden und deine Sprösslinge wie das Kraut der Erde*.", footnotes: ["℘ 1Mo 13,16"] },
      { number: 26, text: "Du wirst in Rüstigkeit ins Grab kommen*, wie die Garben eingebracht werden zu ihrer Zeit.", footnotes: ["℘ Kap. 42,17; 5Mo 34,7; Jes 65,20"] },
      { number: 27, text: "Siehe, dies haben wir erforscht, so ist es. Höre es doch, und merke du es dir*!", footnotes: ["Andere üs. mit alten Üs.: Wir hörten es. Du aber merke es dir"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Und Hiob antwortete und sagte*:", heading: "Hiobs Antwort: Rechtfertigung seines Klagens mit der Schwere seines Leidens — Wunsch nach schnellem Tod — Klage über die Härte der Freunde", footnotes: ["℘ Kap. 3,2"] },
      { number: 2, text: "Würde man meinen Kummer doch wiegen, abwiegen und mein Verderben gleichzeitig auf die Waage legen!" },
      { number: 3, text: "Denn nun ist es* schwerer als der Sand der Meere; darum sind meine Worte unbesonnen.", footnotes: ["o. Denn dann wäre es"] },
      { number: 4, text: "Denn die Pfeile des Allmächtigen sind in mir*, mein Geist trinkt ihr Gift; die Schrecken Gottes greifen mich an*.", footnotes: ["℘ Ps 38,3; Spr 14,10", "w. stellen sich <in Schlachtordnung> gegen mich auf\n℘ Kap. 7,20; 16,9.12-14; 19,12.21; 30,15; Kla 3,3.12.13"] },
      { number: 5, text: "Schreit ein Wildesel* beim frischen Gras*, oder brüllt ein Stier bei seinem Futter?", footnotes: ["o. Zebra", "℘ Kap. 39,8"] },
      { number: 6, text: "Wird Fades ohne Salz gegessen? Oder ist Geschmack in dem Schleim um den Dotter*?", footnotes: ["o. im Eibischschleim. — Der Schleim der Eibischstaude war als Medikament gebräuchlich."] },
      { number: 7, text: "Meine Seele weigert sich, es anzurühren, sie ekelt sich vor der Krankheit meines Brotes*.", footnotes: ["d. h. vor meinem ungesunden Brot; so mit T.; Mas. T.: anzurühren diese <Dinge> wie Krankheit meines Brotes"] },
      { number: 8, text: "Dass sich doch meine Bitte erfüllte und Gott mein Verlangen gewährte!" },
      { number: 9, text: "Dass Gott sich dazu entschlösse, mich zu zertreten, dass er seine Hand abzöge und mich vernichtete*!", footnotes: ["w. abschnitte\n℘ Kap. 3,21.22; 10,1; 1Kö 19,4"] },
      { number: 10, text: "So wäre noch mein Trost, und ich würde jubeln in schonungsloser Qual, dass ich die Worte des Heiligen nicht verleugnet* habe.", footnotes: ["w. versteckt, o. verhohlen"] },
      { number: 11, text: "Was ist meine Kraft, dass ich warten*, und was ist mein Ende, dass ich mich gedulden sollte*?", footnotes: ["d. h. Habe ich noch Kraft auszuhalten?", "o. was ist mein Ziel, für das ich durchhalten soll\n℘ Kap. 17,13.15"] },
      { number: 12, text: "Ist <denn> meine Kraft die Kraft von Steinen, oder ist mein Fleisch aus Bronze?" },
      { number: 13, text: "Ist es nicht so, dass keine <eigene> Hilfe in mir ist und <jedes> Gelingen aus mir vertrieben ist*?", footnotes: ["℘ Kap. 16,7"] },
      { number: 14, text: "Wer seinem Freund die Treue versagt*, der verlässt* die Furcht des Allmächtigen.", footnotes: ["℘ Kap. 19,21", "so in Anlehnung an LXX, Vulg., die syr. und aram. Üs. Mas. T. ist nicht sicher übersetzbar. Traditionell wird üs.: Dem Verzagten <gebührt> Treue von seinem Freund, sonst verlässt er, o. auch wenn er verlässt"] },
      { number: 15, text: "Meine Brüder haben treulos gehandelt* wie ein Wildbach, wie das Bett der Wildbäche, die vergehen*.", footnotes: ["℘ Kap. 13,4; 19,13.14; Spr 25,19", "o. überfließen\n℘ Jer 15,18; 38,22"] },
      { number: 16, text: "Sie sind trübe von Eis, der Schnee verläuft sich in sie." },
      { number: 17, text: "Zur Zeit, wenn sie wasserarm werden, versiegen sie. Wenn es heiß wird, sind sie von ihrer Stelle weggetrocknet." },
      { number: 18, text: "Es werden Karawanen abgelenkt von ihrem Weg, ziehen hinauf in die Öde und kommen um*.", footnotes: ["Andere üs.: Es verlieren sich die Pfade ihres Verlaufs, sie ziehen hinauf in die Öde und versickern"] },
      { number: 19, text: "Die Karawanen von Tema* hielten Ausschau, die Handelszüge von Saba* hofften auf sie.", footnotes: ["℘ 1Mo 25,15; Jes 21,14; Jer 25,23", "℘ Kap. 1,15; 1Kö 10,1"] },
      { number: 20, text: "Sie wurden beschämt, weil sie <auf sie> vertraut hatten*, sie kamen hin und wurden zuschanden*.", footnotes: ["so mit alten Üs.; Mas. T.: weil er vertraut hatte", "℘ Kap. 13,4; 19,13.14; Spr 25,19"] },
      { number: 21, text: "So seid ihr* jetzt für mich* geworden. Ihr seht Schreckliches und fürchtet euch*.", footnotes: ["T.; Mas. T.: Denn ihr seid", "so mit einer hebr. Handschr., LXX und der syr. Üs.; Mas. T.: nicht anstatt für mich", "℘ Kap. 19,19"] },
      { number: 22, text: "Habe ich etwa gesagt: Gebt mir und macht mir ein Geschenk von eurem Vermögen" },
      { number: 23, text: "und befreit mich aus der Hand des Bedrängers und erlöst mich aus der Hand der Gewalttätigen*?", footnotes: ["℘ Ps 49,8"] },
      { number: 24, text: "Belehrt mich, so will ich schweigen! Und macht mir klar, worin ich geirrt habe!*", footnotes: ["℘ Kap. 13,23"] },
      { number: 25, text: "Wie könnten aufrichtige Worte kränkend sein!* Aber was weist die Zurechtweisung von euch <schon> zurecht?", footnotes: ["℘ Kap. 16,5; Spr 15,23"] },
      { number: 26, text: "Gedenkt ihr, Worte zurechtzuweisen? Für den Wind sind ja die Reden eines Verzweifelnden!" },
      { number: 27, text: "Sogar eine Waise würdet ihr verlosen*, und um euren Freund würdet ihr feilschen.", footnotes: ["℘ 2Mo 22,21"] },
      { number: 28, text: "Und nun, entschließt euch! Wendet euch zu mir! Ich werde euch doch nicht ins Angesicht lügen*.", footnotes: ["℘ Kap. 27,4"] },
      { number: 29, text: "Kehrt doch um, damit kein Unrecht geschieht! Ja, kehrt um, noch bin ich hier im Recht*!", footnotes: ["w. noch ist meine Gerechtigkeit darin"] },
      { number: 30, text: "Ist etwa Unrecht auf meiner Zunge*? Oder sollte mein Gaumen Verderben nicht spüren?*", footnotes: ["℘ Kap. 11,4", "℘ Kap. 12,11; 34,3"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Hat der Mensch nicht einen harten Dienst* auf Erden, und sind seine Tage nicht wie die Tage eines Tagelöhners*?", heading: "Klage über das menschliche Dasein, über sein Los und über Gottes Unbarmherzigkeit — Bitte an Gott um Schonung", footnotes: ["w. einen Kriegsdienst", "℘ Kap. 14,6; Jes 16,14; Mt 6,34"] },
      { number: 2, text: "Wie ein Knecht, der sich nach Schatten sehnt*, und wie ein Tagelöhner, der auf seinen Lohn wartet,", footnotes: ["℘ Jon 4,6"] },
      { number: 3, text: "so habe ich gehaltlose Monate* erhalten, und Nächte voll Unheil wurden mir zugeteilt*.", footnotes: ["o. Monate der Täuschung", "℘ Ps 6,7"] },
      { number: 4, text: "Wenn ich mich niederlegte, so sagte ich: *Wann kann ich aufstehen? — Und der Abend zieht sich hin, und ich bin gesättigt mit Unrast bis zur Morgendämmerung*.", footnotes: ["Die Üs. dieses Satzes ist nicht ganz sicher. Viele folgen der LXX und üs.: Wann ist es Tag<, dass ich aufstehen kann>? Wenn ich aber aufgestanden bin<, spreche ich>: Wann ist es Abend? Und ich bin voll Schmerzen vom Abend bis frühmorgens", "Die Üs. dieses Satzes ist nicht ganz sicher. Viele folgen der LXX und üs.: Wann ist es Tag<, dass ich aufstehen kann>? Wenn ich aber aufgestanden bin<, spreche ich>: Wann ist es Abend? Und ich bin voll Schmerzen vom Abend bis frühmorgens\n℘ 5Mo 28,67"] },
      { number: 5, text: "Mein Fleisch ist bekleidet mit Maden und Schorf*, meine Haut <ist kaum> verharscht und eitert* <schon wieder>*.", footnotes: ["w. Staubschorf", "w. zerfließt, o. zergeht", "℘ Kap. 13,28; 17,7; 19,20; Ps 38,6"] },
      { number: 6, text: "Meine Tage gleiten schneller dahin als ein Weberschiffchen* und schwinden ohne Hoffnung*.", footnotes: ["℘ Kap. 9,25.26; 17,1.11; Jes 38,12", "℘ Kap. 14,19"] },
      { number: 7, text: "Bedenke, dass mein Leben ein Hauch ist*! Mein Auge wird kein Glück mehr sehen.", footnotes: ["℘ Kap. 10,20; Ps 39,6"] },
      { number: 8, text: "Das Auge dessen, der mich sehen will, wird mich nicht <mehr> gewahren. <Richtest du> deine Augen auf mich, so bin ich nicht <mehr>*.", footnotes: ["℘ Kap. 14,10; 20,8.9"] },
      { number: 9, text: "Die Wolke schwindet und vergeht*; so steigt, wer in den Scheol hinabfährt, nicht wieder herauf*.", footnotes: ["℘ Jak 4,14", "℘ Kap. 10,21; 14,12; 16,22; Jes 26,14"] },
      { number: 10, text: "Zu seinem Haus kehrt er nicht mehr zurück*, und seine Stätte weiß nichts mehr von ihm*.", footnotes: ["℘ 2Sam 12,23", "℘ Kap. 8,18; Ps 103,16"] },
      { number: 11, text: "So will auch ich meinen Mund nicht zurückhalten, will reden in der Bedrängnis meines Geistes, will klagen in der Verbitterung meiner Seele*.", footnotes: ["℘ Kap. 10,1; 13,13; 23,2; 36,21; 1Sam 1,10"] },
      { number: 12, text: "Bin ich das Meer oder ein Seeungeheuer, dass du eine Wache gegen mich aufstellst?" },
      { number: 13, text: "Wenn ich sagte: Mein Bett soll mich trösten, mein Lager wird meinen Kummer* tragen helfen! —", footnotes: ["o. Anliegen (das mich beschäftigt, plagt)"] },
      { number: 14, text: "so entmutigst du mich mit Träumen, und durch Visionen schreckst du mich auf*,", footnotes: ["℘ Dan 4,2"] },
      { number: 15, text: "so dass meine Seele Erstickung vorzieht, den Tod <lieber hat> als meine Gebeine*.", footnotes: ["mit Veränderung eines Buchstabens: meine Schmerzen; vgl. Kap. 9,28\n℘ Kap. 3,21.22"] },
      { number: 16, text: "Ich mag nicht mehr* — nicht ewig will ich leben! Lass ab von mir! Meine Tage sind nur noch ein Hauch*.", footnotes: ["w. Ich verwerfe o. lehne ab\n℘ Kap. 9,21; 10,1; Pred 2,17; Jon 4,3.8", "℘ Kap. 10,20; Ps 39,6"] },
      { number: 17, text: "Was ist der Mensch, dass du ihn groß achtest* und dass du dein Herz auf ihn richtest*", footnotes: ["o. dass du ihn groß werden lässt; d. h., dass er davor bewahrt wird, schon als Kind zu sterben", "℘ Kap. 14,3; Ps 8,5"] },
      { number: 18, text: "und ihn alle Morgen heimsuchst*, ihn alle Augenblicke prüfst?", footnotes: ["℘ Ps 73,14"] },
      { number: 19, text: "Wie lange <noch> willst du nicht von mir wegblicken, nicht <einmal so lange> von mir ablassen, bis ich meinen Speichel heruntergeschluckt habe*?", footnotes: ["℘ Kap. 9,18; 10,20; 14,6"] },
      { number: 20, text: "Habe ich gesündigt? Was tat ich dir an, du Wächter der Menschen*? Warum hast du mich dir zur Zielscheibe gesetzt*, und <warum> werde ich mir zur Last*?", footnotes: ["Andere üs. mit der syr. Üs.: du Schöpfer der Menschen\n℘ Kap. 10,2.6; 35,6", "℘ Kap. 6,4", "w. und werde ich auf mir zur Last; einige hebr. Handschr. und LXX: und werde ich auf dir zur Last"] },
      { number: 21, text: "Warum vergibst du <mir> nicht mein Verbrechen und lässt meine Schuld <nicht> vorübergehen*? Denn nun werde ich mich in den Staub legen*, und suchst du nach mir, so bin ich nicht mehr*.", footnotes: ["℘ Kap. 10,14", "℘ Kap. 10,9", "℘ Kap. 14,10; 20,8.9"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Und Bildad von Schuach antwortete und sagte*:", heading: "Erste Rede des Bildad: Gottes Gerechtigkeit in Strafe und Güte — Untergang der Gottlosen — Segen durch Buße", footnotes: ["℘ Kap. 2,11; 18,1; 25,1"] },
      { number: 2, text: "Wie lange willst du noch so <etwas> künden, und <wie lange> sollen die Worte deines Mundes heftiger Wind sein*?", footnotes: ["℘ Kap. 15,2; 16,3"] },
      { number: 3, text: "Wird Gott <etwa> das Recht beugen, oder wird der Allmächtige die Gerechtigkeit beugen*?", footnotes: ["℘ Kap. 19,6; 34,5.10-12; 37,23; 2Chr 19,7; Ps 92,16; Röm 9,14"] },
      { number: 4, text: "Haben deine Söhne gegen ihn gesündigt, so lieferte er sie ihrer Übertretung aus*.", footnotes: ["w. so entließ er sie in die Hand ihrer Übertretung\n℘ Hes 18,4.20"] },
      { number: 5, text: "Wenn du Gott eifrig suchst und zum Allmächtigen um Gnade flehst*,", footnotes: ["LXX: Du aber, suche Gott eifrig und flehe zum Allmächtigen um Gnade\n℘ Kap. 5,8"] },
      { number: 6, text: "wenn du lauter und aufrichtig bist, ja, dann wird er deinetwegen aufwachen und die Wohnung deiner Gerechtigkeit wiederherstellen*.", footnotes: ["℘ Kap. 11,14; 22,23; Ps 18,25; Spr 3,33"] },
      { number: 7, text: "Und dein Anfang wird gering <erscheinen>, aber dein Ende wird er sehr groß machen*.", footnotes: ["so mit T.; Mas. T.: aber dein Ende — er wird sehr groß werden\n℘ Kap. 5,11; 42,10.12"] },
      { number: 8, text: "Denn befrage doch die vorige Generation und habe acht* auf das, was ihre Väter erforscht haben*! —", footnotes: ["so mit der syr. Üs.; Mas. T.: befestige, o. gründe", "℘ Kap. 15,18; 5Mo 4,32; 32,7"] },
      { number: 9, text: "Denn wir sind von gestern und erkennen nichts*, denn ein Schatten sind unsere Tage auf der Erde*. —", footnotes: ["℘ Ps 82,5", "℘ Kap. 14,1.2; 1Chr 29,15; Ps 102,12; 144,4"] },
      { number: 10, text: "Werden diese dich nicht belehren, es dir sagen und Worte aus ihrem Herzen hervorbringen?" },
      { number: 11, text: "Schießt Schilfrohr auf, wo kein Sumpf ist? Wächst Riedgras empor ohne Wasser?" },
      { number: 12, text: "Noch treibt es Knospen, noch ist es nicht zum Schneiden reif*, da verdorrt es <schon> vor allem anderen Gras*.", footnotes: ["w. Noch ist es in seiner Knospe, wird es nicht abgerissen", "℘ Jes 19,6"] },
      { number: 13, text: "So sind die Pfade* aller, die Gott vergessen*; und des Ruchlosen Hoffnung geht zugrunde*.", footnotes: ["Andere üs. hier mit LXX: das Ende; vgl. V. 7", "℘ Ps 1,4", "℘ Kap. 11,20; 27,8; Ps 112,10; Spr 10,28.29"] },
      { number: 14, text: "Seine Zuversicht ist ein dünner Faden*, und ein Spinngewebe ist das, worauf er vertraut.", footnotes: ["Die Bedeutung des Wortes ist unsicher."] },
      { number: 15, text: "Er stützt sich auf sein Haus, aber es hält nicht stand; er hält sich daran fest, aber es bleibt nicht stehen*.", footnotes: ["℘ Spr 14,11; Sach 5,4"] },
      { number: 16, text: "Voll Saft steht er in der Sonne, und seine Triebe ranken sich* durch seinen Garten,", footnotes: ["w. sein Trieb dehnt sich aus"] },
      { number: 17, text: "über Steinhaufen schlingen sich seine Wurzeln, zwischen Steinen lebt er*.", footnotes: ["o. klammert er sich fest; so mit LXX; Mas. T.: das Haus der Steine schaut er"] },
      { number: 18, text: "Reißt man ihn aus von seiner Stelle, so verleugnet sie ihn: Ich habe dich nie gesehen*!", footnotes: ["℘ Kap. 7,8.10; Ps 37,36"] },
      { number: 19, text: "Siehe, das ist die Freude seines Weges*; und aus dem Staub sprosst ein anderer hervor*.", footnotes: ["Andere üs. in Anlehnung an LXX: Siehe, so löst sich sein <Lebens>weg auf", "so mit hebr. Handschr. und alten Üs.; Mas. T.: ein anderer — sie sprossen hervor"] },
      { number: 20, text: "Siehe, Gott wird den Rechtschaffenen* nicht verwerfen* und die Übeltäter nicht an die Hand nehmen*.", footnotes: ["o. den Unschuldigen; o. den Lauteren", "℘ Spr 10,9", "℘ Ps 34,17"] },
      { number: 21, text: "Während er deinen Mund mit Lachen füllen wird und deine Lippen mit Jubel*,", footnotes: ["℘ Ps 126,2"] },
      { number: 22, text: "werden die, die dich hassen, mit Schande bekleidet werden*, und das Zelt der Gottlosen wird nicht mehr sein*.", footnotes: ["℘ Ps 6,11", "℘ Spr 14,11; Sach 5,4"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Und Hiob antwortete und sagte*:", heading: "Hiobs Antwort: Unmöglichkeit, bei Gott Recht zu erlangen", footnotes: ["℘ Kap. 3,2"] },
      { number: 2, text: "Wahrlich, ich habe erkannt, dass es so ist. Und wie könnte ein Mensch vor Gott gerecht sein*?", footnotes: ["o. recht haben Gott gegenüber\n℘ Kap. 25,4; Ps 130,3"] },
      { number: 3, text: "Wenn er Lust hat, mit ihm in einen Rechtsstreit zu treten, so könnte er ihm auf tausend nicht eins antworten*.", footnotes: ["℘ Kap. 34,23"] },
      { number: 4, text: "Der weise ist von Herzen* und stark an Kraft* — wer trotzte ihm und blieb unversehrt*? —,", footnotes: ["℘ Röm 16,27", "℘ Kap. 12,13; 37,23; Nah 1,3", "℘ Kap. 41,2; 2Mo 9,17.18; 15,7; 2Chr 13,12; 20,6; Spr 28,14; Jes 45,9"] },
      { number: 5, text: "der Berge versetzt, ohne dass sie es erkennen, indem er sie umstürzt in seinem Zorn*;", footnotes: ["℘ Kap. 40,11; Nah 1,5.6; Hab 3,6"] },
      { number: 6, text: "der aufstört die Erde von ihrer Stätte*, dass ihre Säulen erzittern;", footnotes: ["℘ Ps 114,6; Jes 13,13; Hag 2,6; Hebr 12,26"] },
      { number: 7, text: "der zur Sonne spricht*, und sie geht nicht auf, und die Sterne versiegelt er;", footnotes: ["℘ Jos 10,13; Am 4,13"] },
      { number: 8, text: "der den Himmel ausspannt*, er allein, und schreitet auf den Wogen* des Meeres*;", footnotes: ["℘ Kap. 26,7; 1Chr 16,26; Ps 104,2", "o. auf den <Wellen>bergen", "℘ Mt 14,25"] },
      { number: 9, text: "der den Großen Bären gemacht hat, den Orion und das Siebengestirn* und die Kammern des Südens*;", footnotes: ["℘ Kap. 38,31.32; Am 5,8", "d. h. den südlichen Sternenhimmel"] },
      { number: 10, text: "der so große Dinge tut, dass sie nicht zu erforschen, und Wundertaten, dass sie nicht zu zählen sind*.", footnotes: ["℘ Kap. 5,9; 37,5"] },
      { number: 11, text: "Siehe, er geht an mir vorüber, und ich sehe ihn nicht*; und er zieht vorbei, und ich bemerke ihn nicht.", footnotes: ["so mit alten Üs.; Mas. T.: ich sehe es nicht\n℘ Kap. 23,8.9; 35,14"] },
      { number: 12, text: "Siehe, er rafft dahin, und wer will ihm wehren*? Wer kann zu ihm sagen: Was tust du*?", footnotes: ["℘ Kap. 1,21; 11,10; 23,13", "℘ Kap. 33,13; 2Sam 16,10; Jes 45,9; Dan 4,32"] },
      { number: 13, text: "Gott wendet seinen Zorn nicht ab*, unter ihn beugten sich die Helfer Rahabs*.", footnotes: ["℘ Jes 5,25", "d. i. ein urzeitliches Meeresungeheuer; hier als Bild gottfeindlicher Mächte; vgl. Kap. 26,12\n℘ Kap. 26,12"] },
      { number: 14, text: "Wie viel weniger könnte ich ihm antworten, meine Worte ihm gegenüber wählen!" },
      { number: 15, text: "Ihm könnte ich, <auch> wenn ich im Recht* wäre, nicht antworten — zu meinem Richter würde ich um Gnade flehen.", footnotes: ["o. gerecht"] },
      { number: 16, text: "Wenn ich riefe und er mir antwortete, nicht würde ich glauben, dass er auf meine Stimme hörte." },
      { number: 17, text: "Er, der nach mir greift im Unwetter* und meine Wunden grundlos vermehrt*,", footnotes: ["℘ Kap. 10,8", "℘ Kap. 33,10"] },
      { number: 18, text: "er erlaubt mir nicht, Atem zu holen*, sondern sättigt mich mit Bitterkeiten*.", footnotes: ["℘ Kap. 7,19", "℘ Kap. 27,2; Rt 1,20; Kla 3,15"] },
      { number: 19, text: "Wenn es auf Kraft des Starken ankommt<, so sagt er>: Siehe hier*! — und wenn auf Recht: Wer will mich vorladen*?", footnotes: ["℘ Ps 62,12", "℘ V. 32.33; Röm 3,4"] },
      { number: 20, text: "Wenn ich auch im Recht* wäre, mein Mund würde mich verurteilen*; wäre ich <auch> rechtschaffen*, er würde mich schuldig sprechen*.", footnotes: ["o. gerecht", "℘ Kap. 15,6", "o. unschuldig; o. lauter", "℘ V. 29-31; Kap. 10,15; 14,17"] },
      { number: 21, text: "Rechtschaffen* bin ich! Ich kümmere mich nicht um meine Seele*, ich verachte mein Leben*,", footnotes: ["o. unschuldig; o. lauter", "o. Ich erkenne nicht meine Seele", "℘ Kap. 7,15.16"] },
      { number: 22, text: "es ist eins!* Darum sage ich: Den Rechtschaffenen* wie den Gottlosen vernichtet er*.", footnotes: ["o. nur eines gilt:", "o. Den Unschuldigen; o. Den Lauteren", "℘ Kap. 34,9; Pred 9,2; Hes 21,9"] },
      { number: 23, text: "Wenn die Geißel plötzlich tötet, so spottet er über die Verzweiflung Unschuldiger." },
      { number: 24, text: "Die Erde ist in die Hand des Gottlosen gegeben*, das Angesicht ihrer Richter verhüllt er. Wenn er es nicht ist, wer sonst*?", footnotes: ["℘ Pred 4,1", "o. Fürwahr denn, was für einer ist er"] },
      { number: 25, text: "Und meine Tage sind schneller dahingeeilt als ein Läufer, sie sind entflohen, haben nichts Gutes gesehen*.", footnotes: ["℘ Kap. 7,6.7; 14,1"] },
      { number: 26, text: "Sie sind vorübergezogen wie Rohrschiffe*, wie ein Adler, der auf Beute herabstößt*.", footnotes: ["Aus Schilfrohr wurden die leichtesten und schnellsten Schiffe gebaut.", "℘ Hab 1,8"] },
      { number: 27, text: "Wenn ich denke: Ich will meinen Kummer* vergessen, will ein anderes Gesicht machen* und fröhlich blicken,", footnotes: ["o. mein Anliegen", "w. will mein <betrübtes> Gesicht verlassen"] },
      { number: 28, text: "so bangt mir vor allen meinen Schmerzen*. Ich habe erkannt, dass du mich nicht ungestraft lässt*.", footnotes: ["℘ Kap. 21,6", "℘ V. 20; Kap. 33,10"] },
      { number: 29, text: "Ich muss ja schuldig sein*! Wozu soll ich mich denn für nichts abmühen*?", footnotes: ["℘ V. 20; Kap. 33,10", "℘ Ps 73,13"] },
      { number: 30, text: "Wenn ich mich <auch> mit Schneewasser* wüsche und meine Hände mit Lauge reinigte*,", footnotes: ["so mit der Leseform des Mas. T.; mit der Schreibform: mit Schnee", "℘ Ps 51,9"] },
      { number: 31, text: "dann würdest du mich in die Grube* tauchen, dass sich meine eigenen Kleider vor mir ekelten*.", footnotes: ["LXX: in den Schmutz", "℘ Kap. 14,17; Jer 2,22"] },
      { number: 32, text: "Denn er ist nicht ein Mann wie ich, dass ich ihm antworten, dass wir zusammen vor Gericht gehen könnten*.", footnotes: ["℘ V. 14.15.19; Pred 6,10"] },
      { number: 33, text: "Es gibt zwischen uns keinen Schiedsmann*, dass er seine Hand auf uns beide legen könnte*.", footnotes: ["Andere üs. mit vielen hebr. Handschr., LXX und der syr. Üs.: Gäbe es doch zwischen uns einen Schiedsmann", "℘ Kap. 33,23.24; 1Sam 2,25"] },
      { number: 34, text: "Er nehme seine Rute von mir weg*, und sein Schrecken ängstige mich nicht mehr*,", footnotes: ["℘ Ps 39,11", "℘ Kap. 13,20-22; 33,7"] },
      { number: 35, text: "so will ich reden und ihn nicht fürchten, denn so <steht es jetzt> bei mir nicht*.", footnotes: ["Andere üs. mit T.: denn nicht recht <verfährt> er mit mir"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Es ekelt mich* vor meinem Leben*. Ich will meinen Kummer* von mir lassen, will reden in der Bitterkeit meiner Seele*.", heading: "Klage über Gottes Verhalten in der schweren Heimsuchung", footnotes: ["w. Es ekelt meine Seele", "℘ Kap. 6,8.9; 7,16", "o. mein Anliegen", "℘ Kap. 7,11"] },
      { number: 2, text: "Ich sage zu Gott: Verdamme mich nicht*! Lass mich wissen, warum du mich vor Gericht ziehst*!", footnotes: ["℘ Ps 27,7.9", "℘ Kap. 7,20; 13,23; 21,4; 33,13"] },
      { number: 3, text: "Ist das gut für dich*, dass du Unterdrückung übst, dass du die Arbeit deiner Hände verwirfst* und <dein Licht> über dem Rat der Gottlosen leuchten lässt?", footnotes: ["o. Nützt es dir", "℘ Ps 138,8"] },
      { number: 4, text: "Hast du Menschenaugen*, oder siehst du, wie ein Mensch sieht*?", footnotes: ["w. Augen des Fleisches", "℘ 1Sam 16,7"] },
      { number: 5, text: "Sind deine Tage wie die Tage eines Menschen oder deine Jahre wie die Tage eines Mannes*,", footnotes: ["℘ Ps 102,28"] },
      { number: 6, text: "dass du nach meiner Schuld suchst und nach meiner Sünde forschst*,", footnotes: ["℘ Kap. 7,20; 13,23; 21,4; 33,13"] },
      { number: 7, text: "obwohl du weißt, dass ich nicht schuldig bin*, und niemand da ist, der aus deiner Hand retten kann*?", footnotes: ["℘ Kap. 11,4; 23,10-12", "℘ 5Mo 32,39; Ps 50,22; Jes 43,13; Hos 5,14"] },
      { number: 8, text: "Deine Hände haben mich ganz gebildet und gestaltet um und um*, und <nun> verschlingst du mich*!*", footnotes: ["℘ Ps 119,73; 139,15", "o. in Anlehnung an LXX und syr. Üs.: Deine Hände haben mich gebildet und gemacht, und danach wendest du dich um und verschlingst mich", "℘ Kap. 9,17"] },
      { number: 9, text: "Bedenke doch, dass du mich wie Ton gestaltet hast!* Und <jetzt> willst du mich zum Staub zurückkehren lassen!*", footnotes: ["℘ Kap. 33,6; Jes 45,9; 64,7", "℘ Kap. 4,19; 7,21; 34,15; 1Mo 3,19; Ps 103,14"] },
      { number: 10, text: "Hast du mich nicht hingegossen wie Milch und wie Käse mich gerinnen lassen?" },
      { number: 11, text: "Mit Haut und Fleisch hast du mich bekleidet und mit Knochen und Sehnen mich durchflochten*.", footnotes: ["℘ Ps 139,13.14"] },
      { number: 12, text: "Leben und Gnade hast du mir gewährt*, und deine Obhut bewahrte meinen Geist.", footnotes: ["o. an mir bewirkt"] },
      { number: 13, text: "Doch dies verbargst du in deinem Herzen, ich habe erkannt, dass du dies im Sinn hattest*:*", footnotes: ["w. dass dieses bei dir <war>", "℘ Kap. 23,13.14"] },
      { number: 14, text: "Wenn ich sündigte, so würdest du mich beobachten* und mich nicht von meiner Schuld freisprechen*.", footnotes: ["℘ Kap. 14,16; 34,22; Ps 90,8; Jer 16,17", "℘ Kap. 7,21"] },
      { number: 15, text: "Wenn ich schuldig wäre — wehe mir!* Und wäre ich im Recht, dürfte ich mein Haupt <doch> nicht erheben*, gesättigt mit Schande* und getränkt mit Elend*.", footnotes: ["℘ Jes 3,11", "℘ Kap. 9,20", "℘ Ps 44,16", "T.; Mas. T.: gesättigt mit Schande und siehe mein Elend"] },
      { number: 16, text: "Und richtete es sich auf, wie ein Löwe würdest du mich jagen* und dich wieder als wunderbar an mir erweisen*.", footnotes: ["℘ Jes 38,13; Jer 5,6; Kla 3,10; Hos 5,14", "d. h. so handeln, dass ich es nicht verstehen kann"] },
      { number: 17, text: "Du würdest neue Zeugen gegen mich aufstellen* und deinen Zorn über mich vergrößern. Ein ständig sich ablösendes Heer <kämpft> gegen mich*.", footnotes: ["w. deine Zeugen gegen mich erneuern", "w. Ablösungen und ein Heer gegen mich. — LXX: Heerscharen hast du gegen mich geführt\n℘ Kap. 13,24"] },
      { number: 18, text: "Warum hast du mich aus dem Mutterleib hervorgezogen?* Wäre ich doch umgekommen, so hätte mich kein Auge gesehen!", footnotes: ["℘ Kap. 3,11"] },
      { number: 19, text: "Als wenn ich nie gewesen, so wäre ich <dann>; vom Mutterschoß wäre ich zu Grabe geleitet worden!*", footnotes: ["℘ Kap. 3,16"] },
      { number: 20, text: "Sind meine Tage nicht <nur noch> wenige?* Er lasse <doch> ab, wende sich von mir*, dass ich ein wenig fröhlich werde,", footnotes: ["℘ Kap. 7,16", "℘ Kap. 7,19"] },
      { number: 21, text: "ehe ich hingehe — und nicht wiederkomme* — in das Land der Finsternis und des Todesschattens*,", footnotes: ["℘ Kap. 7,9; Ps 39,14; 49,20", "℘ Pred 11,8"] },
      { number: 22, text: "in das Land, schwarz wie die Dunkelheit, <das Land> der Finsternis — <da ist> keine Ordnung —, und <selbst> das Hellwerden ist <dort> wie Dunkelheit!*", footnotes: ["℘ Kap. 3,5; 17,13; Ps 88,13; Pred 9,10"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Und Zofar von Naama antwortete und sagte*:", heading: "Erste Rede des Zofar: Widerspruch gegen Hiob — Mahnung zur rechten Schau und zur Demütigung vor dem allwissenden Gott", footnotes: ["℘ Kap. 2,11; 20,1"] },
      { number: 2, text: "Soll der Wortschwall nicht beantwortet werden*, oder soll ein Schwätzer* recht behalten?*", footnotes: ["w. Soll die Menge der Worte nicht beantwortet werden. — Andere üs. in Anlehnung an LXX, Vulg. und die aram. Üs.: Sollte dem Wortgewaltigen nicht geantwortet werden", "w. ein Mann der Lippen", "℘ Spr 10,19; Pred 5,1.6; Jak 1,19"] },
      { number: 3, text: "Soll dein Gerede Männer zum Schweigen bringen*, dass du spotten kannst* und niemand <dich> beschämt?", footnotes: ["o. in Anlehnung an die syr. Üs.: Vor dir allein sollen wohl Männer schweigen", "℘ Kap. 34,7"] },
      { number: 4, text: "Und du sagtest: Meine Lehre ist lauter, und ich war rein in deinen Augen*!", footnotes: ["℘ Kap. 6,30; 10,7"] },
      { number: 5, text: "Aber — möge Gott doch reden und seine Lippen gegen dich auftun*", footnotes: ["℘ Kap. 38,1"] },
      { number: 6, text: "und dir die Geheimnisse der Weisheit mitteilen, dass sie wie Wunder sind für <menschliche> Klugheit*! Und erkenne <doch>, dass Gott dir <viel> von deiner Schuld übersieht*!", footnotes: ["so mit anderer Vokalisierung; Mas. T.: dass <sie> das Doppelte ist für Umsicht", "w. dass Gott dir Vergessen gewährt von deiner Schuld\n℘ Esr 9,13"] },
      { number: 7, text: "Kannst du die Tiefen Gottes erreichen oder die Vollkommenheit des Allmächtigen ergründen*?", footnotes: ["o. bis zur äußersten Grenze des Allmächtigen gelangen\n℘ Kap. 26,14; 27,11; 35,5; 37,23; Röm 11,33"] },
      { number: 8, text: "Himmelhoch <sind sie> — was kannst du tun? — tiefer als der Scheol — was kannst du erkennen*?", footnotes: ["℘ Spr 30,4"] },
      { number: 9, text: "Länger als die Erde ist ihr Maß und breiter als das Meer*.", footnotes: ["℘ Kap. 33,12; 42,3"] },
      { number: 10, text: "Wenn er vorüberzieht und festnimmt und <zum Gericht> versammelt, wer will ihm dann wehren?*", footnotes: ["℘ Kap. 9,12; Jes 14,27"] },
      { number: 11, text: "Denn er erkennt die nichtswürdigen Männer, und er sieht Böses, ohne dass er <darauf> achten muss.*", footnotes: ["o. er sieht Böses, und er sollte es nicht beachten?\n℘ Ps 33,13-15"] },
      { number: 12, text: "Kann ein Hohlkopf Verstand gewinnen und ein Eselhengst* als Mensch geboren werden?", footnotes: ["o. ein Zebrahengst"] },
      { number: 13, text: "Wenn du dein Herz fest ausrichtest und deine Hände zu ihm ausbreitest* —", footnotes: ["℘ Kap. 5,8; 2Mo 9,29; Kla 3,41"] },
      { number: 14, text: "wenn Böses in deiner Hand ist, so entferne es und lass in deinen Zelten kein Unrecht wohnen*! —", footnotes: ["℘ Kap. 8,6; 1Sam 7,3; 2Kö 17,13"] },
      { number: 15, text: "ja, dann wirst du dein Gesicht erheben ohne Makel* und wirst unerschütterlich* sein und dich nicht fürchten*.", footnotes: ["℘ Kap. 22,26; 1Jo 3,21", "w. festgegossen", "℘ Ps 112,7.8"] },
      { number: 16, text: "Denn du wirst die Mühsal vergessen*, wirst <an sie> denken wie an vorbeigeflossenes Wasser*,", footnotes: ["℘ 1Mo 41,51; Jes 65,16", "w. wie Wasser vorbeifloss, wirst du gedenken"] },
      { number: 17, text: "und heller als der Mittag wird <dein> Leben aufgehen*; mag es finster sein — wie der Morgen wird es werden*.", footnotes: ["℘ Ps 37,6; Jes 58,8.10", "℘ Ps 97,11"] },
      { number: 18, text: "Und du wirst Vertrauen fassen, weil es Hoffnung gibt; und du wirst Ausschau halten, in Sicherheit dich niederlegen." },
      { number: 19, text: "Und du liegst da*, und niemand wird dich aufschrecken*, und viele werden deine Gunst suchen*.", footnotes: ["℘ Ps 4,9", "℘ 2Chr 20,30; Hes 34,28", "w. dein Gesicht umschmeicheln"] },
      { number: 20, text: "Aber die Augen der Gottlosen werden versagen. Und <jede> Zuflucht geht ihnen verloren, und ihre Hoffnung ist, die Seele auszuhauchen*.", footnotes: ["℘ Kap. 3,21.22; 8,13"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Und Hiob antwortete und sagte*:", heading: "Hiobs Antwort: Klage über seine Freunde — Schilderung der verkannten Macht und Weisheit Gottes", footnotes: ["℘ Kap. 3,2"] },
      { number: 2, text: "Wirklich, ihr seid <die rechten> Leute, und mit euch wird die Weisheit aussterben!" },
      { number: 3, text: "Auch ich habe Verstand* wie ihr, ich stehe nicht hinter euch zurück*; und wer wüsste dies nicht*?", footnotes: ["w. ein Herz", "w. ich falle nicht gegen euch ab; so auch Kap. 13,2\n℘ Kap. 13,2; 2Kor 11,5", "w. und bei wem ist <so etwas> wie dieses nicht"] },
      { number: 4, text: "Zum Gespött für seine Gefährten wird der, der zu Gott rief* — und der antwortete ihm —, der Gerechte, Rechtschaffene <wird> zum Gespött*!", footnotes: ["so mit LXX und der syr. Üs.; Mas. T.: werde ich, der ich zu Gott rief", "℘ Kap. 16,20; 17,2; 21,3; Ps 22,7.8"] },
      { number: 5, text: "Dem Unglück gebührt Verachtung, meint der Sichere*, *ein Stoß denen, deren Fuß wankt!*", footnotes: ["w. nach der Meinung des Sicheren", "o. <die Verachtung>, sie ist erlaubt <gegenüber> denen, deren Fuß wankt.", "o. <die Verachtung>, sie ist erlaubt <gegenüber> denen, deren Fuß wankt."] },
      { number: 6, text: "Die Zelte der Verwüster haben Ruhe*, und Sicherheit gibt es für die, die Gott reizen, für den, der Gott in seiner Hand führt*.", footnotes: ["℘ Kap. 21,7; Ps 73,3.12; Jer 5,27.28", "d. h. der nur auf die eigene Macht vertraut; vgl. Hab 1,11\n℘ Hab 1,11"] },
      { number: 7, text: "Aber frage doch das Vieh, und es wird es dich lehren, oder die Vögel des Himmels*, und sie werden es dir mitteilen*,", footnotes: ["℘ Mt 6,26", "℘ Spr 30,24"] },
      { number: 8, text: "oder rede zu der Erde, und sie wird es dich lehren*, und die Fische des Meeres werden es dir erzählen!", footnotes: ["Viele vermuten, dass der Mas. T. hier fehlerhaft ist, und üs.: oder <frage> das Getier der Erde, und es wird dich lehren"] },
      { number: 9, text: "Wer erkennt nicht an all diesem, dass die Hand des HERRN dies gemacht hat?*", footnotes: ["℘ 1Mo 1,20-25; Röm 1,19.20"] },
      { number: 10, text: "In seiner Hand ist die Seele alles Lebendigen und der Lebensatem alles menschlichen Fleisches.*", footnotes: ["℘ 4Mo 16,22; Ps 104,30; Jes 57,16; Dan 5,23"] },
      { number: 11, text: "Soll das Ohr nicht die Worte prüfen, <wie> der Gaumen für sich die Speise kostet*?", footnotes: ["℘ Kap. 6,30"] },
      { number: 12, text: "Bei Greisen ist Weisheit und Einsicht bei hohem Alter*.", footnotes: ["w. bei Länge der Tage\n℘ Kap. 15,10; 32,6.7; 1Kö 12,6"] },
      { number: 13, text: "Bei ihm ist Weisheit und Macht*, sein ist Rat und Einsicht*.", footnotes: ["℘ Kap. 9,4; Spr 8,14; Dan 2,20", "℘ Kap. 32,8; Spr 2,6; Jes 31,2"] },
      { number: 14, text: "Siehe, er reißt nieder, und es wird nicht wieder gebaut; er schließt über jemandem zu, und es wird nicht wieder geöffnet*.", footnotes: ["℘ 1Mo 7,16; Pred 7,13; Jes 22,22; Mal 1,4; Offb 3,7"] },
      { number: 15, text: "Siehe, er hemmt das Wasser, und es trocknet aus*; er lässt es los, und es kehrt das Land um.", footnotes: ["℘ 1Mo 8,1; 1Kö 17,7"] },
      { number: 16, text: "Bei ihm ist Kraft und Erfolg*; sein ist, wer irrt und wer irreführt*.", footnotes: ["℘ Kap. 32,8; Spr 2,6; Jes 31,2", "℘ 1Kö 22,22"] },
      { number: 17, text: "Er führt Ratgeber beraubt* weg*, und Richter macht er zu Narren.", footnotes: ["o. ausgezogen; o. barfuß", "℘ 2Sam 17,14; Jes 29,14; 1Kor 1,20"] },
      { number: 18, text: "Fesseln* von Königen löst er auf* und schlingt einen Gurt* um ihre Hüften*.", footnotes: ["so mit der aram. Üs. und Vulg.; Mas. T.: Die Zucht, o. Die Mahnung", "℘ Dan 2,21", "o. einen <leinenen> Hüftschurz", "℘ 2Chr 33,11"] },
      { number: 19, text: "Er führt Priester beraubt weg, und alte <Geschlechter> bringt er zu Fall*.", footnotes: ["o. ständig fließende Ströme lässt er austrocknen\n℘ Kap. 34,20; Ps 76,13; Jes 40,23; Lk 1,52"] },
      { number: 20, text: "Bewährten <Sprechern> entzieht er die Sprache, und Alten nimmt er die Urteilskraft*.", footnotes: ["℘ Kap. 32,9"] },
      { number: 21, text: "Verachtung schüttet er auf Edle*, und den Gürtel der Starken lockert er.", footnotes: ["℘ Ps 107,40; Jes 23,9"] },
      { number: 22, text: "Er enthüllt Geheimnisvolles aus dem Dunkel*, und Finsternis zieht er ans Licht*.", footnotes: ["℘ Dan 2,22; Mt 10,26; 1Kor 4,5", "℘ Kap. 34,22"] },
      { number: 23, text: "Er macht Völker groß und vernichtet sie; er breitet Völker aus, und er leitet sie*.", footnotes: ["Andere üs. mit anderer Vokalisierung: und er richtet sie zugrunde\n℘ Ps 107,38.39"] },
      { number: 24, text: "Den Häuptern des Volkes im Land nimmt er den Mut*, und in wegloser Einöde lässt er sie umherirren*.", footnotes: ["o. den Verstand; w. das Herz\n℘ Ps 76,13; Dan 4,13.30", "℘ Ps 59,12; 107,40"] },
      { number: 25, text: "Sie tappen in der Finsternis, wo kein Licht ist*, und er lässt sie umherirren wie einen Betrunkenen*.", footnotes: ["℘ Kap. 5,14", "℘ Jes 19,14"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Siehe, das alles hat mein Auge gesehen, mein Ohr gehört und sich gemerkt.", heading: "Hiobs Warnung der Freunde vor der Gerechtigkeit Gottes — Vorsichtige Aufforderung an Gott zum Rechtsstreit" },
      { number: 2, text: "Soviel ihr erkannt habt, habe ich auch erkannt, ich stehe nicht hinter euch zurück*.", footnotes: ["℘ Kap. 12,3; 15,9"] },
      { number: 3, text: "Doch ich will zum Allmächtigen reden, und vor Gott will ich mich verteidigen*.", footnotes: ["℘ V. 15; Kap. 23,3.4"] },
      { number: 4, text: "Ihr dagegen seid Lügendichter*, Kurpfuscher, ihr alle!*", footnotes: ["w. Lügenschmierer", "℘ Kap. 6,15; 16,2"] },
      { number: 5, text: "Hieltet ihr euch doch still! Das würde euch zur Weisheit gereichen." },
      { number: 6, text: "Hört doch meine Entgegnung und achtet auf die Streitreden meiner Lippen!" },
      { number: 7, text: "Wollt ihr für Gott Verkehrtes vorbringen und für ihn Falsches vortragen*?", footnotes: ["℘ 2Kö 10,18"] },
      { number: 8, text: "Wollt ihr seine Partei ergreifen*, oder wollt ihr für Gott den Rechtsstreit führen?", footnotes: ["w. Werdet ihr sein Gesicht erheben"] },
      { number: 9, text: "Wird es gut für euch sein, wenn er euch erforscht? Oder wollt ihr ihn täuschen, wie man einen Menschen täuscht*?", footnotes: ["℘ Apg 5,4"] },
      { number: 10, text: "Hart zurechtweisen wird er euch, wenn ihr insgeheim die Person anseht*.", footnotes: ["w. <jemandes> Gesicht erhebt; d. h. eine Person bevorzugt\n℘ 2Chr 19,7"] },
      { number: 11, text: "Wird seine Hoheit euch nicht aufschrecken und sein Schrecken nicht auf euch fallen?" },
      { number: 12, text: "Was ihr vorbringt*, sind Sprüche von Asche, eure Bollwerke* erweisen sich als Bollwerke aus Lehm*.", footnotes: ["o. Eure Merksprüche; w. Eure Erinnerungen", "Wortbedeutung unsicher; vielleicht auch: Schildbuckel", "℘ Kap. 21,34"] },
      { number: 13, text: "Schweigt still vor mir, und ich will reden, was auch über mich ergehen möge*!", footnotes: ["℘ Kap. 7,11"] },
      { number: 14, text: "Warum sollte ich mein Fleisch zwischen meine Zähne nehmen und mein Leben in meine Hand legen?*", footnotes: ["Andere üs. mit LXX: Ich will . . . mein Leben in meine Hand legen!"] },
      { number: 15, text: "Siehe, er wird mich töten, ich will auf ihn warten*, nur will ich meine Wege ihm ins Angesicht rechtfertigen*.", footnotes: ["mit der Schreibform des Mas. T.: ich will nicht warten, o. ich habe nichts zu hoffen", "℘ V. 3"] },
      { number: 16, text: "Schon das wird mir zur Rettung sein, denn kein Ruchloser darf vor sein Angesicht kommen*.", footnotes: ["℘ Mt 7,23"] },
      { number: 17, text: "Hört, hört meine Rede, und meine Darlegung dringe in eure Ohren!*", footnotes: ["℘ Kap. 21,2"] },
      { number: 18, text: "Siehe doch, ich habe den Rechtsfall vorgebracht, ich habe erkannt, dass ich recht behalten werde." },
      { number: 19, text: "Wer ist der, der mit mir den Rechtsstreit führen könnte?* Denn dann wollte ich schweigen und verscheiden.", footnotes: ["℘ Jes 50,8"] },
      { number: 20, text: "Nur zweierlei tue nicht mit mir*, dann werde ich mich nicht vor deinem Angesicht verbergen!", footnotes: ["℘ Kap. 9,34"] },
      { number: 21, text: "Entferne deine Hand von mir, und dein Schrecken soll mich nicht ängstigen!" },
      { number: 22, text: "Dann rufe, und ich will antworten, oder ich will reden, und du erwidere mir!*", footnotes: ["℘ Kap. 14,15; 31,35"] },
      { number: 23, text: "Wie viele Sünden und Vergehen habe ich? Lass mich mein Verbrechen und mein Vergehen wissen!*", footnotes: ["℘ Kap. 6,24; 10,2"] },
      { number: 24, text: "Warum verbirgst du dein Angesicht und hältst mich für deinen Feind?*", footnotes: ["℘ Kap. 10,16.17; 16,9; 19,11.21; 30,21; 33,10; Ps 44,24"] },
      { number: 25, text: "Willst du ein verwehtes Blatt erschrecken und einem dürren Halm nachjagen?" },
      { number: 26, text: "Denn Bitteres verhängst* du über mich, und die Sünden meiner Jugend lässt du mich entgelten*.", footnotes: ["w. schreibst", "℘ 1Kö 17,18; Ps 25,7; Jer 31,19"] },
      { number: 27, text: "Und meine Füße legst du in den Block und beobachtest all meine Pfade*, zeichnest dir die Sohlen* meiner Füße auf*,", footnotes: ["℘ Kap. 14,16", "w. Wurzeln", "℘ Kap. 3,23"] },
      { number: 28, text: "da ich doch wie Moder zerfalle*, wie ein Kleid, das die Motte zerfressen hat*.", footnotes: ["so mit T.; Mas. T.: und er, er zerfällt wie Moder", "℘ Kap. 7,5; Ps 39,12; Jak 5,2"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Der Mensch, von der Frau geboren*, lebt kurze Zeit* und ist mit Unruhe gesättigt*.", heading: "Klage über die Nichtigkeit des Menschenlebens — Vergebliches Hoffen auf Trost nach dem Tod", footnotes: ["℘ Kap. 15,14.15; 25,4.5", "w. ist kurz an Tagen\n℘ Kap. 9,25; Ps 39,6", "℘ Kap. 5,7; 1Mo 47,9; Jer 20,18"] },
      { number: 2, text: "Wie eine Blume kommt er hervor und verwelkt*; und wie der Schatten flieht er* und kann nicht bestehen.", footnotes: ["o. wird abgeschnitten\n℘ Ps 90,6; Jak 1,10", "℘ Kap. 8,9; Ps 39,7"] },
      { number: 3, text: "Doch über einen solchen hast du deine Augen geöffnet*, und mich führst du ins Gericht mit dir*!", footnotes: ["℘ Kap. 7,17-19", "℘ Ps 143,2"] },
      { number: 4, text: "Wie könnte ein Reiner vom Unreinen <kommen>? Nicht ein Einziger!*", footnotes: ["℘ Ps 51,7; Joh 3,6"] },
      { number: 5, text: "Wenn seine <Lebens>tage festgesetzt sind*, die Zahl seiner Monate bei dir <feststeht>, wenn du <ihm> sein Ziel gesetzt hast, dass er es nicht überschreiten kann*,", footnotes: ["℘ Kap. 16,22", "℘ 1Sam 26,10; Pred 3,2; 8,8; Apg 17,26"] },
      { number: 6, text: "so blicke weg von ihm, so dass er Ruhe hat*, damit er wie ein Tagelöhner seinen Tag genießen kann*!", footnotes: ["℘ Kap. 7,16.19", "℘ Kap. 7,1.2"] },
      { number: 7, text: "Denn für den Baum gibt es Hoffnung. Wird er abgehauen, so schlägt er wieder aus*, und seine Triebe bleiben nicht aus.", footnotes: ["℘ Jes 6,13"] },
      { number: 8, text: "Wenn seine Wurzel <auch> in der Erde altert und sein Stumpf im Staub abstirbt —" },
      { number: 9, text: "vom Duft des Wassers sprosst er wieder und treibt Zweige wie ein Pflänzling*.", footnotes: ["℘ Dan 4,12"] },
      { number: 10, text: "Ein Mann aber stirbt und liegt da; und ein Mensch verscheidet*, und wo ist er <dann>?*", footnotes: ["℘ Kap. 7,8; 1Chr 29,15", "℘ Kap. 20,7; Pred 3,20.21"] },
      { number: 11, text: "Das Wasser verrinnt aus dem Meer, und der Fluss trocknet aus und versiegt;" },
      { number: 12, text: "so legt der Mensch sich hin und steht nicht wieder auf*. Bis der Himmel nicht mehr ist*, erwacht er nicht und wird nicht aufgeweckt aus seinem Schlaf*.", footnotes: ["℘ Kap. 7,9", "℘ 2Petr 3,10", "so mit alten Üs.; Mas. T.: erwachen sie nicht und werden nicht aufgeweckt aus ihrem Schlaf\n℘ Kap. 3,13; Pred 11,8"] },
      { number: 13, text: "Dass du mich doch im Scheol verstecktest, mich verbärgest, bis dein Zorn sich abwendete, mir ein Ziel setztest und dann meiner gedächtest!" },
      { number: 14, text: "— Wenn ein Mann stirbt, wird er etwa wieder leben?* — Alle Tage meines Dienstes* wollte ich harren*, bis meine Ablösung käme!", footnotes: ["℘ Kap. 20,7; Pred 3,20.21", "w. meines Kriegsdienstes", "℘ Jes 8,17"] },
      { number: 15, text: "Du würdest rufen, und ich würde dir antworten*, nach dem Werk deiner Hände würdest du dich sehnen.", footnotes: ["℘ Kap. 13,22"] },
      { number: 16, text: "Denn dann würdest du <zwar> meine Schritte zählen*, aber gäbest nicht acht auf meine Sünde*!*", footnotes: ["℘ Kap. 13,27; 31,4; 33,11; 34,21", "℘ Kap. 10,6.14", "Andere üs. mit LXX: Jetzt aber zählst du meine Schritte, gehst an meiner Sünde nicht vorüber."] },
      { number: 17, text: "Mein Verbrechen wäre versiegelt in einem Bündel*, und du würdest meine Schuld zudecken*.", footnotes: ["℘ Hos 13,12", "w. zuschmieren\n℘ Kap. 9,20.30.31"] },
      { number: 18, text: "Und doch, ein Berg stürzt ein, zerfällt, und ein Fels rückt fort von seiner Stelle*.", footnotes: ["℘ Kap. 18,4"] },
      { number: 19, text: "Wasser zerreibt Steine, seine Fluten schwemmen den Staub der Erde hinweg. So machst du die Hoffnung des Menschen zunichte*.", footnotes: ["℘ Kap. 7,6; 17,15; 19,10"] },
      { number: 20, text: "Du überwältigst ihn für immer, und er geht dahin; sein Gesicht entstellst du und schickst ihn fort." },
      { number: 21, text: "Kommen seine Kinder zu Ehren, er weiß es nicht, und werden sie gering, er achtet nicht auf sie*.", footnotes: ["℘ Kap. 21,21; Pred 9,5.6"] },
      { number: 22, text: "Sein Fleisch fühlt nur noch für sich selber Schmerz, und seine Seele trauert nur um sich*.", footnotes: ["w. Nur sein Fleisch an ihm fühlt Schmerz, und seine Seele in ihm trauert"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Und Elifas von Teman antwortete und sagte*:", heading: "Zweite Rede des Elifas: Er rügt Hiob wegen des ungeziemenden Redens gegen Gott — Unheil für den Gottlosen", footnotes: ["℘ Kap. 4,1"] },
      { number: 2, text: "Wird <etwa> ein Weiser windige Erkenntnis zur Antwort geben*, oder wird er sein Inneres mit Ostwind füllen*?", footnotes: ["℘ Spr 16,23", "℘ Kap. 8,2; Pred 5,15; Hos 12,2"] },
      { number: 3, text: "Wird er mit nutzlosen Worten streiten* oder mit Reden, mit denen er nicht hilft?", footnotes: ["o. zurechtweisen"] },
      { number: 4, text: "Ja, du zerstörst die Gottesfurcht und beschneidest die Andacht vor Gott." },
      { number: 5, text: "Denn deine Schuld belehrt deinen Mund*, und du wählst die Sprache der Listigen*.", footnotes: ["℘ Lk 6,45", "℘ Kap. 22,5; 32,2"] },
      { number: 6, text: "Dein Mund verdammt dich und nicht ich; und deine Lippen sagen gegen dich aus*.", footnotes: ["℘ Kap. 9,20; 1Kö 20,40; Mt 12,37; Lk 19,22"] },
      { number: 7, text: "Bist du als Erster der Menschen geboren*, oder bist du vor den Hügeln hervorgebracht worden?", footnotes: ["℘ Kap. 38,4; Ps 90,2; Spr 8,25"] },
      { number: 8, text: "Hörst du im Rat Gottes zu*, und reißt du die Weisheit an dich?", footnotes: ["℘ Röm 11,34"] },
      { number: 9, text: "Was hast du erkannt, das wir nicht erkannt hätten? Was verstehst du, das uns nicht bekannt wäre*?", footnotes: ["w. <Was> verstehst du, und dies ist nicht bei uns\n℘ Kap. 13,2"] },
      { number: 10, text: "Unter uns sind auch Alte, auch Greise*, reicher an Tagen als dein Vater.", footnotes: ["℘ Kap. 12,12"] },
      { number: 11, text: "Sind dir die Tröstungen Gottes zu wenig* oder ein Wort, das sanft mit dir <verfuhr>?", footnotes: ["℘ Ps 77,3"] },
      { number: 12, text: "Was reißt dein Herz dich hin, und was rollen* deine Augen,", footnotes: ["w. zwinkern, o. blinzeln <böse>"] },
      { number: 13, text: "dass du dein Schnauben gegen Gott kehrst und <solche> Reden aus deinem Mund hast hervorgehen lassen*?", footnotes: ["℘ 1Mo 4,5; 2Kö 6,33; Spr 19,3; Kla 3,39; Hes 18,25"] },
      { number: 14, text: "Was ist der Mensch, dass er rein dastehen könnte, und der von einer Frau Geborene, dass er gerecht wäre?*", footnotes: ["℘ Kap. 14,1.4; 1Kö 8,46; Ps 14,2.3; 143,2; Röm 3,10"] },
      { number: 15, text: "Siehe, <selbst> auf seine Heiligen vertraut er nicht*, und der Himmel ist nicht rein in seinen Augen,", footnotes: ["℘ Kap. 4,18"] },
      { number: 16, text: "wie viel weniger der Abscheuliche und Verdorbene, der Mann, der Unrecht trinkt wie Wasser*!", footnotes: ["℘ Kap. 34,7"] },
      { number: 17, text: "Ich will dir verkünden, höre mir zu! Und was ich geschaut habe, will ich erzählen," },
      { number: 18, text: "was die Weisen mitgeteilt und nicht verhehlt haben von ihren Vätern her* —", footnotes: ["Viele üs. mit leicht veränderter Wortabtrennung: was die Weisen mitgeteilt und ihre Väter ihnen nicht verhehlt haben\n℘ Kap. 8,8"] },
      { number: 19, text: "ihnen allein war das Land gegeben, und kein Fremder zog in ihrer Mitte umher* —:", footnotes: ["℘ 5Mo 32,12"] },
      { number: 20, text: "All seine Tage quält sich der Gottlose in Angst*, und eine <kleine> Zahl von Jahren ist dem Gewalttätigen aufbewahrt*.", footnotes: ["℘ 1Mo 4,14", "℘ Ps 55,24"] },
      { number: 21, text: "Der Ton des Schreckens <gellt> in seinen Ohren*, im Frieden kommt der Verwüster über ihn*.", footnotes: ["℘ Kap. 18,11; Spr 28,1", "℘ Est 7,6; Jer 6,26"] },
      { number: 22, text: "Er glaubt nicht daran, aus der Finsternis zurückkehren zu können, und er ist ausersehen* für das Schwert.", footnotes: ["Andere üs. mit T.: aufbewahrt"] },
      { number: 23, text: "Er irrt umher nach Brot — wo <ist es>?* Er hat erkannt, dass sich neben ihm <schon> ein finsterer Tag bereithält*.", footnotes: ["℘ Kap. 18,12; Ps 59,16; Spr 10,3", "℘ Spr 16,4"] },
      { number: 24, text: "Not und Bedrängnis schrecken ihn, sie überwältigen ihn* wie ein König, der zum Sturm bereit ist*.", footnotes: ["w. sie überwältigt ihn", "℘ Kap. 19,11.12"] },
      { number: 25, text: "Denn er hat seine Hand gegen Gott ausgestreckt, und dem Allmächtigen gegenüber hat er sich überheblich gebärdet*.", footnotes: ["℘ Jer 48,26; 50,24"] },
      { number: 26, text: "Mit <hartem> Nacken rannte er gegen ihn an*, mit der Dicke seiner Schildbuckel*.", footnotes: ["℘ Ps 75,6", "℘ 2Mo 5,2"] },
      { number: 27, text: "Denn er hat sein Gesicht bedeckt mit seinem Fett und Speck an der Lende angesetzt*,", footnotes: ["℘ Ps 73,4.7"] },
      { number: 28, text: "und er bewohnte zerstörte Städte, Häuser, in denen man nicht wohnen soll, die zu Steinhaufen bestimmt waren." },
      { number: 29, text: "Er wird nicht reich, und sein Vermögen hat keinen Bestand; und nicht neigt sich zur Erde seine Ähre*.", footnotes: ["Wortbedeutung unbekannt; andere: sein Besitz; LXX: sein Schatten"] },
      { number: 30, text: "Er entweicht der Finsternis nicht*; seine Triebe* dörrt die Flamme aus*, *und er muss weichen beim Hauch seines* Mundes*.", footnotes: ["℘ Kap. 18,5.6", "w. seinen Sprössling", "℘ Kap. 20,26", "Andere üs. mit LXX: und vom Wind verweht wird seine Blüte", "d. h. Gottes", "d. h. Gottes\n℘ Kap. 4,9; Jes 11,4; Hos 6,5; 2Thes 2,8"] },
      { number: 31, text: "Er verlasse sich nicht auf Nichtiges, er wird irregeführt*; denn Nichtiges wird sein Eintausch dafür sein.", footnotes: ["℘ Jer 37,9"] },
      { number: 32, text: "Wenn sein Tag noch nicht da ist, so erfüllt es sich <schon>*; und sein Spross wird nicht grün*.", footnotes: ["Andere üs.: so wird er ihm voll ausgezahlt; vgl. V. 31", "℘ Spr 10,27"] },
      { number: 33, text: "Wie der Weinstock stößt er seine unreifen Trauben ab, und wie der Olivenbaum wirft er seine Blüte ab." },
      { number: 34, text: "Denn die Schar des Ruchlosen ist unfruchtbar, und Feuer frisst die Zelte der Bestechung*.", footnotes: ["℘ Kap. 18,15-19"] },
      { number: 35, text: "Sie sind schwanger mit Mühsal und gebären Unrecht*, und ihr Inneres bereitet Verrat*.", footnotes: ["℘ Ps 7,15; Jes 59,4; Jak 1,14.15", "℘ Mi 2,1-3"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Und Hiob antwortete und sagte*:", heading: "Hiobs Antwort: Leidiger Trost der Freunde — Trotz Schuldlosigkeit Behandlung als Sünder durch Gott und Menschen — Warten auf Gottes Wirken nach dem Tod", footnotes: ["℘ Kap. 3,2"] },
      { number: 2, text: "Ich habe so etwas <nun> viel gehört. Mühsame Tröster* seid ihr alle*!", footnotes: ["w. Tröster der Mühsal o. des Unheils", "℘ Kap. 13,4; 21,34"] },
      { number: 3, text: "Haben die windigen Worte <nun> ein Ende*? Oder was reizt dich, dass du antwortest?", footnotes: ["℘ Kap. 8,2; 27,12"] },
      { number: 4, text: "Auch ich könnte reden wie ihr. Wäret ihr doch an meiner Stelle*! Dann könnte ich mit Worten gegen euch glänzen und meinen Kopf über euch schütteln*.", footnotes: ["w. Wenn doch eure Seelen an der Stelle meiner Seele wären", "o. mit meinem Kopf euch beifällig zunicken\n℘ Ps 22,8"] },
      { number: 5, text: "Ich wollte euch stärken mit meinem Mund, und das Beileid meiner Lippen würde ich nicht zurückhalten*.", footnotes: ["so mit alten Üs.; Mas. T.: würde zurückgehalten werden"] },
      { number: 6, text: "Wenn ich rede, so wird mein Schmerz nicht gehemmt; und unterlasse ich es — was weicht <dann> von mir?" },
      { number: 7, text: "Ja, jetzt hat er* mich müde gemacht*. Du hast meine ganze Umgebung* menschenleer gemacht.", footnotes: ["d. i. Gott", "℘ Kap. 6,13", "w. meine ganze Gemeinde"] },
      { number: 8, text: "Und du hast mich gepackt, das zeugt gegen mich*. Und meine Abmagerung tritt als Zeuge gegen mich auf, mir ins Angesicht sagt sie aus.", footnotes: ["w. zum Zeugen <gegen mich> wurde es"] },
      { number: 9, text: "Sein Zorn zerfleischte <mich> und feindete mich an, er knirschte mit seinen Zähnen gegen mich, als mein Feind schärft er seine Augen gegen mich*.", footnotes: ["℘ Kap. 10,16.17; 13,24"] },
      { number: 10, text: "Ihren Mund haben sie gegen mich aufgesperrt*, mit Schmähung meine Backen geschlagen*; gemeinsam rotten sie sich gegen mich zusammen*.", footnotes: ["℘ Ps 22,14", "℘ Lk 22,63-65", "℘ Ps 56,6"] },
      { number: 11, text: "Gott gibt mich dem Ungerechten* preis, und in die Hände der Gottlosen stürzt er mich.", footnotes: ["so mit den alten Üs. und einer hebr. Handschr.; Mas. T.: dem Buben"] },
      { number: 12, text: "Ich war sorglos, da hat er mich aufgerüttelt, und er packte mich beim Nacken und zerschmetterte mich, und er stellte mich für sich als Zielscheibe auf*.", footnotes: ["℘ Kap. 6,4; Kla 3,3"] },
      { number: 13, text: "Seine Geschosse umfliegen mich. Er spaltet meine Nieren und empfindet kein Mitleid, er schüttet meine Galle* auf die Erde.", footnotes: ["w. Gallenblase"] },
      { number: 14, text: "Bresche auf Bresche reißt er in mich*. Er rennt gegen mich an wie ein Krieger.", footnotes: ["w. Er bricht mich, Bruch über Bruch"] },
      { number: 15, text: "Ich habe Sacktuch über meine Haut genäht und mein Horn in den Staub gesenkt." },
      { number: 16, text: "Mein Gesicht glüht vom Weinen, und auf meinen Wimpern liegt Finsternis*,", footnotes: ["℘ Kap. 17,7"] },
      { number: 17, text: "obwohl keine Gewalttat an meinen Händen <klebt>* und mein Gebet lauter ist*.", footnotes: ["℘ Kap. 31,7; 33,9", "℘ Ps 17,1"] },
      { number: 18, text: "Erde, decke mein Blut nicht zu, und für meinen Klageschrei sei kein Ruheplatz da!" },
      { number: 19, text: "Auch jetzt <noch> — siehe, im Himmel ist mein Zeuge* und mein Fürsprecher* in der Höhe.", footnotes: ["℘ 1Sam 12,5; 1Thes 2,5", "o. mein Zeuge"] },
      { number: 20, text: "Meine Gefährten verspotten mich*. Zu Gott blickt mein Auge mit Tränen auf*,", footnotes: ["w. Meine Gefährten sind meine Verspotter\n℘ Kap. 12,4", "℘ Kap. 23,3; 2Kö 20,3"] },
      { number: 21, text: "dass er Recht schaffe für einen Mann gegen Gott und für einen Menschensohn gegen seine Gefährten." },
      { number: 22, text: "Denn es kommen nur noch wenige Jahre*, und ich werde einen Weg gehen, von dem ich nicht zurückkomme*.", footnotes: ["℘ Kap. 14,5; 17,1", "℘ Kap. 7,9.10"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Mein Geist ist verstört*, meine Tage sind ausgelöscht*, Gräber sind für mich da*.", heading: "Gründe für Gottes Eintreten — Abweisen der Reden der Freunde als töricht in Erwartung des Grabes", footnotes: ["o. Mein Lebensgeist ist vernichtet", "℘ V. 11; Kap. 16,22", "℘ Ps 88,5"] },
      { number: 2, text: "Ist nicht um mich herum Gespött*, und muss nicht mein Auge auf ihrer Widerspenstigkeit* haften*?", footnotes: ["℘ Kap. 12,4", "Andere üs. in Anlehnung an die syr. Üs. und Vulg.: Bitterkeit", "w. bei ihrer Widerspenstigkeit übernachten"] },
      { number: 3, text: "Setze doch <ein Pfand> ein, leiste bei dir selbst Bürgschaft für mich*! Wer sonst wird in meine Hand einschlagen*?", footnotes: ["℘ Jes 38,14", "℘ Kap. 5,1"] },
      { number: 4, text: "Denn ihr Herz hast du der Einsicht verschlossen; darum wirst du sie nicht erhöhen." },
      { number: 5, text: "Den Gefährten erzählt man vom Beuteteilen*, aber die Augen der eigenen Kinder verschmachten.", footnotes: ["o. Zum Beuteteilen lädt man Freunde ein"] },
      { number: 6, text: "Und er hat mich hingestellt zum Spott der Leute*, und zum Anspeien ins Gesicht bin ich <gut>*.", footnotes: ["w. zum Sprichwort (zur Spottrede) der Völker\n℘ Kap. 30,9; Ps 44,15; 69,11.12", "Mit LXX, Vulg. und der syr. Üs. lesen andere: Zum Gespei bin ich vor ihnen geworden\n℘ Mt 26,67"] },
      { number: 7, text: "Und mein Auge ist trübe geworden vor Gram*, und all meine Glieder sind wie ein Schatten*.", footnotes: ["℘ Ps 6,8", "℘ Kap. 7,5; 16,16"] },
      { number: 8, text: "Die Aufrichtigen werden sich darüber entsetzen, und der Schuldlose wird sich über den Ruchlosen aufregen*.", footnotes: ["℘ Ps 37,1; 73,3"] },
      { number: 9, text: "Doch der Gerechte wird an seinem Weg festhalten*, und der, dessen Hände rein sind, wird an Stärke zunehmen*.", footnotes: ["℘ Kap. 27,6; 31,7; 33,9", "℘ 2Sam 3,1; Ps 84,8; Spr 10,25.30"] },
      { number: 10, text: "Aber ihr alle, kommt nur wieder her! Einen Weisen finde ich doch nicht unter euch*.", footnotes: ["℘ Kap. 18,3"] },
      { number: 11, text: "Meine Tage sind vorüber*, zerrissen sind meine Pläne, die Wünsche* meines Herzens*.", footnotes: ["℘ V. 1; Kap. 7,6", "o. Besitztümer", "℘ Spr 16,1"] },
      { number: 12, text: "Die Nacht machen sie zum Tage, das Licht <soll mir> näher <sein> als die Finsternis." },
      { number: 13, text: "Nichts hoffe ich mehr!* Der Scheol ist mein Haus*, in der Finsternis habe ich mein Lager ausgebreitet*.", footnotes: ["w. Wenn ich <noch> hoffe<, dann . . . !> — Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.", "℘ Pred 12,5", "℘ Kap. 10,21.22"] },
      { number: 14, text: "Zum Grab sage ich: Du bist mein Vater! Zur Made: Meine Mutter und meine Schwester!" },
      { number: 15, text: "Wo ist denn nun meine Hoffnung?* Ja, meine Hoffnung, wer wird sie schauen?", footnotes: ["℘ Kap. 6,11; 14,19; Kla 3,18"] },
      { number: 16, text: "Sie fährt mit mir hinab zum Scheol, wenn wir miteinander in den Staub sinken*.", footnotes: ["so in Anlehnung an LXX; Mas. T.: Stücke des Scheol steigen hinab, wenn er zusammen <mit mir> in den Staub sinkt\n℘ Kap. 20,11"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Und Bildad von Schuach antwortete und sagte*:", heading: "Zweite Rede des Bildad: Unwillen über Hiobs anmaßendes Reden — Unvermeidlicher Untergang der Gottlosen", footnotes: ["℘ Kap. 8,1"] },
      { number: 2, text: "Wie lange wollt ihr den Worten Grenzen setzen? Nehmt Einsicht an, und danach wollen wir reden!" },
      { number: 3, text: "Warum werden wir denn für Vieh gehalten, sind dumm* in deinen* Augen*?", footnotes: ["o. unrein", "so mit LXX; Mas. T.: euren", "℘ Kap. 17,10"] },
      { number: 4, text: "Du, der sich selbst zerfleischt in seinem Zorn, soll deinetwegen die Erde verlassen werden, ein Fels von seiner Stelle wegrücken*?", footnotes: ["℘ Kap. 14,18"] },
      { number: 5, text: "Doch das Licht des Gottlosen* wird erlöschen, und die Flamme seines Feuers wird nicht leuchten*.", footnotes: ["so mit Vulg.; Mas. T.: der Gottlosen", "℘ Kap. 20,5; 21,17; Spr 13,9"] },
      { number: 6, text: "Das Licht in seinem Zelt wird finster, und seine Leuchte erlischt über ihm*.", footnotes: ["℘ Kap. 15,29.30; Spr 21,4"] },
      { number: 7, text: "Gehemmt werden seine kräftigen Schritte, und sein eigener Ratschlag wird ihn stürzen*.", footnotes: ["℘ Spr 11,5.6"] },
      { number: 8, text: "Denn durch seine eigenen Füße wird er ins Netz getrieben*, und auf Fallgittern geht er einher.", footnotes: ["℘ Est 7,10; Spr 5,22"] },
      { number: 9, text: "Das Klappnetz wird seine* Ferse festhalten, die Schlinge ihn packen*.", footnotes: ["so mit der syr. Üs. und Vulg.; Mas. T.: eine", "℘ Ps 9,16; Spr 29,6"] },
      { number: 10, text: "Sein Strick ist verborgen in der Erde und die Falle für ihn auf dem Pfad." },
      { number: 11, text: "Ringsum jagen ihn <plötzliche> Schrecken auf, sie hetzen ihn auf Schritt und Tritt*.", footnotes: ["℘ Kap. 15,21; 20,25; 22,10; 27,20; 1Sam 28,5"] },
      { number: 12, text: "Sein Reichtum wird zum Hunger*, und das Verderben steht an seiner Seite bereit.", footnotes: ["w. wird hungrig\n℘ Kap. 15,23.29"] },
      { number: 13, text: "Stücke von seiner Haut wird er fressen, seine Glieder wird er fressen, der Erstgeborene des Todes." },
      { number: 14, text: "Von seinem Zelt, wo er sich sicher fühlte*, wird er fortgerissen, und es treibt ihn zum König der Schrecken.", footnotes: ["w. Von seinem Zelt, dem Gegenstand seines Vertrauens"] },
      { number: 15, text: "Was nicht sein ist, wird in seinem Zelt wohnen*, auf seine Wohnstätte wird Schwefel gestreut werden*.", footnotes: ["Die Üs. ist unsicher.", "℘ Kap. 15,34; 1Mo 19,24"] },
      { number: 16, text: "Von unten werden seine Wurzeln verdorren, und von oben wird sein Gezweig abwelken*.", footnotes: ["℘ Jes 5,24; Am 2,9; Mal 3,19"] },
      { number: 17, text: "Seine <Namens>nennung verschwindet von der Erde, und weit und breit* hat er keinen Namen*.", footnotes: ["w. auf der Fläche draußen", "℘ Ps 9,6; 109,13; Spr 10,7; Jes 14,20; 26,14"] },
      { number: 18, text: "Man stößt ihn aus dem Licht in die Finsternis* und verjagt ihn aus der Welt.", footnotes: ["℘ 1Sam 2,9"] },
      { number: 19, text: "Er wird keinen Spross und keinen Nachkommen haben in seinem Volk*, noch wird ein Entkommener in seinen Schutzorten sein.", footnotes: ["℘ Ps 37,28; Jes 14,22; Jer 22,30"] },
      { number: 20, text: "Über seinen <Gerichts>tag entsetzen sich die Leute im Westen, und die im Osten packt Schauder*.", footnotes: ["so mit LXX und Vulg.; Mas. T.: die im Osten packen den Schauder"] },
      { number: 21, text: "Ja, dies sind die Wohnungen des Übeltäters, und dies ist die Stätte dessen, der Gott nicht erkennt*.", footnotes: ["℘ Kap. 20,29"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Und Hiob antwortete und sagte*:", heading: "Hiobs Antwort: Klage über die Härte der Freunde, über das zu Unrecht zugefügte Leid — Gewissheit über den Erlöser", footnotes: ["℘ Kap. 3,2"] },
      { number: 2, text: "Wie lange wollt ihr meine Seele plagen und mich mit Worten zerschlagen?" },
      { number: 3, text: "Schon zehnmal habt ihr mich beschimpft. Ihr schämt euch nicht, ihr setzt mir hart zu." },
      { number: 4, text: "Und habe ich auch wirklich geirrt, so bleibt <doch> mein Irrtum bei mir*.", footnotes: ["℘ Spr 9,12; Gal 6,5"] },
      { number: 5, text: "Wenn ihr wirklich gegen mich großtun und mir meine Schande vorhalten wollt,*", footnotes: ["Manche fassen die Verse 4 und 5 als ablehnende Frage auf: Ja, sollte ich wirklich geirrt haben? Sollte mein Irrtum bei mir bleiben? 5 Könnt ihr <denn> wirklich gegen mich großtun und mir meine Schande vorhalten?"] },
      { number: 6, text: "so erkennt denn, dass Gott mich irregeführt und sein Fangseil um mich gezogen hat*.", footnotes: ["℘ Kla 1,13"] },
      { number: 7, text: "Siehe, ich schreie: Unrecht! — und werde nicht erhört*. Ich rufe um Hilfe, und da ist kein Recht.", footnotes: ["℘ Kap. 30,20; 34,5; Ps 22,3; Kla 3,8.44; Hab 1,2"] },
      { number: 8, text: "Er hat meinen Weg verschüttet, und ich kann nicht hinüber*; und auf meine Pfade legt er Finsternis*.", footnotes: ["℘ Kap. 3,23; Kla 3,5-9; Hos 2,8", "℘ Jes 59,9.10"] },
      { number: 9, text: "Meine Ehre hat er mir ausgezogen und weggenommen die Krone meines Hauptes*.", footnotes: ["℘ Ps 89,40; Kla 5,16"] },
      { number: 10, text: "Er hat mich abgebrochen ringsum, so dass ich vergehe*, und hat meine Hoffnung ausgerissen wie einen Baum*.", footnotes: ["℘ Ps 102,11.12", "℘ Kap. 14,19"] },
      { number: 11, text: "Und seinen Zorn ließ er gegen mich entbrennen und achtete mich seinen Feinden gleich*.", footnotes: ["℘ Kap. 13,24; Kla 2,5"] },
      { number: 12, text: "Vereint kamen seine Scharen und bahnten ihren Weg gegen mich* und lagerten sich rings um mein Zelt*.", footnotes: ["w. legten ihre Straße gegen mich an, o. schütteten . . . auf\n℘ Kap. 15,24; 30,12", "℘ Kap. 6,4"] },
      { number: 13, text: "Meine Brüder hat er von mir entfernt, und meine Bekannten sind mir ganz entfremdet*.", footnotes: ["℘ Kap. 6,15.20; Ps 69,9"] },
      { number: 14, text: "Meine Verwandten* bleiben aus, und meine Vertrauten haben mich vergessen*.", footnotes: ["o. Nächsten", "℘ Kap. 42,11; Ps 31,12"] },
      { number: 15, text: "Die Schutzbefohlenen meines Hauses und meine Mägde halten mich für einen Fremden; ein Ausländer bin ich in ihren Augen geworden." },
      { number: 16, text: "Meinen Knecht rufe ich, und er antwortet nicht; mit meinem Mund muss ich ihn anflehen." },
      { number: 17, text: "Mein Atem ist meiner Frau widerlich, und stinkend bin ich den Kindern meiner Mutter*.", footnotes: ["w. meines Mutterleibes"] },
      { number: 18, text: "Selbst Buben verachten mich*. Will ich aufstehen, so wenden sie sich von mir ab*.", footnotes: ["℘ Kap. 30,1; 2Kö 2,23", "o. reden sie gegen mich"] },
      { number: 19, text: "Alle meine Vertrauten* verabscheuen mich, und die, die ich liebte, haben sich gegen mich gewendet*.", footnotes: ["w. alle Männer meines vertrauten Umgangs", "℘ Kap. 6,21; Ps 41,10"] },
      { number: 20, text: "Mein Gebein klebt an meiner Haut und an meinem Fleisch*, und an der Haut meiner Zähne bin ich kahl geworden*.", footnotes: ["℘ Kap. 7,5; 33,21; Ps 22,15-18; 102,6; Kla 4,8", "Andere üs.: und nur mit der Haut meiner Zähne bin ich entkommen; d. h. mit knapper Not"] },
      { number: 21, text: "Erbarmt euch über mich, erbarmt euch über mich, ihr meine Freunde!* Denn die Hand Gottes hat mich getroffen*.", footnotes: ["℘ Kap. 6,14", "℘ Rt 1,13.21; Kla 3,3"] },
      { number: 22, text: "Warum jagt ihr mir nach wie Gott* und könnt von meinem Fleisch nicht satt werden?", footnotes: ["℘ Ps 69,27"] },
      { number: 23, text: "Dass doch meine Worte aufgeschrieben würden! Dass sie in ein Buch <kämen> und aufgezeichnet würden," },
      { number: 24, text: "mit eisernem Griffel und Blei in den Felsen gehauen würden auf ewig*!", footnotes: ["℘ Jer 17,1"] },
      { number: 25, text: "Doch ich weiß: Mein Erlöser* lebt*; und als der Letzte wird er über dem Staub* stehen*.", footnotes: ["o. Anwalt; o. Fürsprecher", "℘ Jes 41,14; 54,5; 59,20; Jer 50,34; Eph 1,7", "d. h. über der vergänglichen Welt", "o. sich erheben; o. auftreten\n℘ Offb 1,17.18"] },
      { number: 26, text: "Und nachdem man meine Haut so zerschunden hat, werde ich doch aus meinem Fleisch Gott schauen." },
      { number: 27, text: "Ja, ich werde ihn für mich sehen, und meine Augen werden <ihn> sehen*, aber nicht als Fremden. Meine Nieren verschmachten in meinem Innern*.", footnotes: ["℘ Kap. 33,26; Ps 17,15; Jes 33,17", "℘ Ps 119,81"] },
      { number: 28, text: "Wenn ihr sagt: Wie wollen wir ihm nachjagen! — und dass die Wurzel der Sache* in mir zu finden sei,", footnotes: ["d. h. der Leiden Hiobs"] },
      { number: 29, text: "so fürchtet euch selbst vor dem Schwert! Denn das Schwert ist der Grimm, <der über> die Sünden <kommt>, damit ihr erkennt: Es gibt einen Richter*.", footnotes: ["℘ Ps 58,12"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Und Zofar von Naama antwortete und sagte*:", heading: "Zweite Rede des Zofar: Kurze Freude der Gottlosen vor ihrem Untergang", footnotes: ["℘ Kap. 11,1"] },
      { number: 2, text: "Darum geben meine beunruhigenden Gedanken mir Antwort, und deswegen bin ich innerlich erregt*:", footnotes: ["T.; Mas. T.: und deswegen ist mein Drängen in mir"] },
      { number: 3, text: "Eine Mahnung, mir zur Schande, höre ich, aber der Geist aus meiner Einsicht antwortet mir*.", footnotes: ["Andere üs., teilweise mit LXX: und Wind ohne Einsicht gibst du mir zur Antwort"] },
      { number: 4, text: "Hast du nicht von jeher das erkannt, seitdem <Gott> Menschen auf die Erde gesetzt hat," },
      { number: 5, text: "dass der Jubel der Gottlosen von kurzer Dauer und die Freude des Ruchlosen für einen Augenblick war*?", footnotes: ["℘ Kap. 18,5; 27,19; 2Sam 18,14.15; Ps 94,4"] },
      { number: 6, text: "Stiege auch seine Hoheit bis zum Himmel hinauf, und rührte sein Haupt an die Wolken*,", footnotes: ["℘ Jes 14,13; Ob 4"] },
      { number: 7, text: "gleich seinem Kot vergeht er auf ewig. Die ihn gesehen haben, sagen: Wo ist er*?", footnotes: ["℘ Kap. 14,10; 21,28; Ps 112,10"] },
      { number: 8, text: "Wie ein Traum verfliegt er, und man findet ihn nicht, und er wird weggescheucht wie eine Vision in der Nacht*.", footnotes: ["℘ Est 7,10; Ps 73,20; 90,5; Spr 10,25; Jes 29,7"] },
      { number: 9, text: "Das Auge hat ihn erblickt, doch nun nicht mehr, und seine Stätte gewahrt ihn nicht mehr*.", footnotes: ["℘ Kap. 7,8.10.21; Ps 37,10"] },
      { number: 10, text: "Seine Söhne müssen die Geringen gütig stimmen* und seine Hände sein Vermögen zurückgeben.", footnotes: ["o. müssen bei Geringen betteln"] },
      { number: 11, text: "Waren seine Glieder <auch> voll seiner Jugendkraft, so liegt sie <nun> mit ihm im Staub*.", footnotes: ["℘ Kap. 17,16"] },
      { number: 12, text: "Wenn das Böse auch in seinem Mund süß schmeckte*, er es verbarg unter seiner Zunge,", footnotes: ["℘ Spr 20,17; Offb 10,9"] },
      { number: 13, text: "es aufsparte und nicht fahren ließ und es zurückhielt unter seinem Gaumen," },
      { number: 14, text: "so hat sich seine Speise <doch> in seinen Eingeweiden verwandelt*. Viperngalle* ist in seinem Innern.", footnotes: ["℘ Spr 20,17; Offb 10,9", "Bitteres und Giftiges sind im Altertum Synonyme."] },
      { number: 15, text: "Reichtum hat er verschlungen, doch erbricht er ihn <wieder>: Aus seinem Bauch treibt Gott ihn heraus*.", footnotes: ["℘ Jer 51,44"] },
      { number: 16, text: "Viperngift sog er ein; die Zunge der Giftschlange bringt ihn um*.", footnotes: ["℘ Spr 11,17"] },
      { number: 17, text: "Nicht sehen darf er die Bäche, die flutenden Ströme von Honig und Milch*.", footnotes: ["w. dicke Milch, o. Sahne, o. Butter"] },
      { number: 18, text: "Den Ertrag gibt er zurück und darf ihn nicht verschlingen. An dem Reichtum, den er erwarb*, darf er sich nicht freuen*.", footnotes: ["w. Gemäß dem Reichtum, seinem Eintausch", "℘ 5Mo 28,30-33"] },
      { number: 19, text: "Denn die Geringen hat er misshandelt, verlassen*. Häuser* hat er an sich gerissen und wird sie* nicht ausbauen*.", footnotes: ["℘ Ps 12,6", "w. Ein Haus", "w. es", "Andere üs. mit Vulg.: Das Haus, das er nicht gebaut, hat er an sich gerissen\n℘ Am 5,11.12"] },
      { number: 20, text: "Denn er kannte keine Ruhe in seinem Innern; mit seinem Kostbarsten wird er nicht entrinnen." },
      { number: 21, text: "Vor seiner Fressgier gab es kein Entrinnen*; darum wird sein Wohlstand keinen Bestand haben*.", footnotes: ["w. keinen Entronnenen", "℘ Jes 5,8.9; Am 3,10.11"] },
      { number: 22, text: "In der Fülle seines Überflusses wird er in Bedrängnis geraten; die Hand jedes Notleidenden wird über ihn kommen*.", footnotes: ["Mit LXX, Vulg. und 4 griech. Handschr. üs. andere: die ganze Gewalt des Unheils wird über ihn kommen"] },
      { number: 23, text: "Es wird geschehen: Um seinen Bauch zu füllen, wird Gott* die Glut seines Zorns gegen ihn senden und <sie> auf ihn regnen lassen, auf seinen Körper*.", footnotes: ["w. er", "o. als seine Speise. — Wortbedeutung unsicher; LXX: und Verderben lässt er auf ihn regnen"] },
      { number: 24, text: "Flieht er vor eisernen Waffen, durchbohrt ihn der Bogen aus Bronze*.", footnotes: ["℘ Jes 24,18"] },
      { number: 25, text: "Er* zückt <den Pfeil>, da tritt er <schon> aus dem Rücken hervor* und das blitzende Eisen* aus seiner Galle! Er geht dahin, Schrecken über ihm!*", footnotes: ["d. i. der Bogenschütze", "d. h. aus dem Rücken des Getroffenen", "w. der Blitz", "Andere üs. mit LXX und Vulg.: Schrecken gehen über ihn hin.\n℘ Kap. 18,11"] },
      { number: 26, text: "Alle Finsternis ist aufgespart für seine aufgesparten <Schätze>*. Ein Feuer, das nicht angefacht ist, wird ihn fressen. Übel wird es dem ergehen, der* in seinem Zelt übrig geblieben ist.", footnotes: ["LXX: ist aufgespart für ihn", "o. was"] },
      { number: 27, text: "Der Himmel wird seine Schuld enthüllen, und die Erde wird sich gegen ihn erheben." },
      { number: 28, text: "Der Ertrag seines Hauses muss fortgehen, wird zerrinnen* am Tag seines* Zorns*.", footnotes: ["w. ist ein Sturzbach", "d. i. Gottes", "℘ Spr 11,4"] },
      { number: 29, text: "Das ist das Teil des gottlosen Menschen von Gott und das ihm von Gott zugesprochene Erbe*.", footnotes: ["℘ Kap. 18,21; 22,20; 27,13; Jer 13,25"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "Und Hiob antwortete und sagte*:", heading: "Hiobs Antwort: Wohlergehen der Gottlosen — Gottes Willkür im Austeilen von Glück und Unglück — Kein Gericht über die Gottlosen", footnotes: ["℘ Kap. 3,2"] },
      { number: 2, text: "Höret, hört meine Rede!* Das wäre <wahrer> Trost von euch!", footnotes: ["℘ Kap. 13,6.17"] },
      { number: 3, text: "Ertragt mich, dann will ich reden, und nachdem ich geredet habe, magst du spotten*.", footnotes: ["Eine griech., die syr. Üs. und Vulg. lesen: mögt ihr spotten; LXX: werdet ihr nicht spotten\n℘ Kap. 12,4"] },
      { number: 4, text: "<Trage> ich mein Anliegen* etwa einem Menschen vor*? Oder warum sollte ich nicht ungeduldig sein?", footnotes: ["o. was mich umtreibt; o. meine Klage", "℘ Kap. 10,1.2"] },
      { number: 5, text: "Wendet euch zu mir und schaudert und legt die Hand auf den Mund*!", footnotes: ["℘ Kap. 40,4; Spr 30,32; Mi 7,16"] },
      { number: 6, text: "Ja, wenn ich daran denke, so bin ich bestürzt, und Erbeben packt mein Fleisch*.", footnotes: ["℘ Kap. 9,28; Kla 3,20"] },
      { number: 7, text: "Warum leben die Gottlosen, werden alt, nehmen gar noch zu an Macht*?", footnotes: ["℘ Kap. 12,6; Pred 7,15"] },
      { number: 8, text: "Ihre Nachkommen stehen fest vor ihnen so gut wie sie, und ihre Sprösslinge* sind vor ihren Augen*.", footnotes: ["o. deren Sprösslinge; d. h. die Enkel der Gottlosen", "℘ Jes 65,23"] },
      { number: 9, text: "Ihre Häuser haben Frieden ohne Furcht, und Gottes Rute* ist nicht über ihnen.", footnotes: ["o. Gottes Herrscherstab"] },
      { number: 10, text: "Sein Stier bespringt und verfehlt nicht, seine Kuh kalbt ohne Fehlgeburt." },
      { number: 11, text: "Ihre Buben schicken sie aus wie eine Schafherde, und ihre Kinder hüpfen umher." },
      { number: 12, text: "Sie* erheben <ihre Stimme> bei* Tamburin und Zither und sind fröhlich beim Klang der Flöte*.", footnotes: ["d. h. die Gottlosen", "so mit den alten Üs. und vielen hebr. Handschr.; Mas. T.: wie", "℘ Ps 150,4"] },
      { number: 13, text: "Im Glück genießen sie ihre Tage, und in Ruhe sinken sie in den Scheol hinab*.", footnotes: ["so mit den alten Üs.; Mas. T.: und in Ruhe sind sie erschrocken <vor dem> Scheol, o. <nur> eine Zeit lang . . .\n℘ Kap. 24,24; Ps 73,4.18.19; Lk 16,19.22.23"] },
      { number: 14, text: "Und doch sagen sie zu Gott: Weiche von uns*! Und an der Erkenntnis deiner Wege haben wir kein Gefallen*.", footnotes: ["℘ Kap. 22,17; Jes 30,11; Jer 2,31; Mt 8,34", "℘ Ps 95,10; Spr 1,29"] },
      { number: 15, text: "Was ist der Allmächtige, dass wir ihm dienen sollten*, und was hilft es uns, dass wir <mit Bitten> in ihn dringen*?", footnotes: ["℘ 2Mo 5,2", "℘ Kap. 22,3; 34,9; 35,3; Ps 73,13; Mal 3,14"] },
      { number: 16, text: "Siehe, steht nicht ihr Glück in ihrer Hand?* Der Rat der Gottlosen sei fern von mir*!", footnotes: ["o. Siehe, ihr Glück steht nicht in ihrer Hand. — LXX: steht in ihrer Hand", "LXX: von ihm; d. h. von Gott\n℘ Kap. 22,18; Ps 1,1"] },
      { number: 17, text: "Wie oft erlischt <denn> die Leuchte der Gottlosen* und kommt über sie ihr Verderben, <wie oft> teilt er Vernichtung zu in seinem Zorn?", footnotes: ["℘ Kap. 18,5.6"] },
      { number: 18, text: "<Wie oft denn> werden sie wie Stroh vor dem Wind und wie Spreu, die der Sturmwind entführt*?", footnotes: ["℘ Kap. 27,21; Ps 1,4; 83,14; Jes 17,13; Hos 13,3"] },
      { number: 19, text: "Bewahrt Gott sein Unheil auf für seine Kinder*? Er vergelte ihm selbst*, dass er es fühle*!", footnotes: ["d. h. für die Kinder des Gottlosen\n℘ 2Mo 20,5", "d. h. dem Gottlosen", "w. dass er es erkenne"] },
      { number: 20, text: "Seine <eigenen> Augen sollen seinen Verfall sehen, und vom Zorn des Allmächtigen trinke er*!", footnotes: ["℘ Ps 75,9"] },
      { number: 21, text: "Denn was liegt ihm an seinem Haus nach ihm, wenn die Zahl seiner Monate zu Ende ist*?", footnotes: ["o. weggewischt ist; o. <ohnehin> knapp bemessen ist\n℘ Kap. 14,21"] },
      { number: 22, text: "Kann man Gott Erkenntnis lehren*, ihn, der <selbst> die Erhabenen* richtet?", footnotes: ["℘ Kap. 36,23; 38,3; Jes 40,13; Jer 23,18; Röm 11,34", "d. h. die himmlischen Wesen"] },
      { number: 23, text: "Dieser stirbt in seiner Vollkraft, ganz ungestört und ruhig." },
      { number: 24, text: "Seine Schenkel* sind voll Fett*, und das Mark seiner Gebeine ist <wohl>getränkt.", footnotes: ["T.; die Bedeutung des Wortes im Mas. T. ist umstritten; LXX und Vulg.: Seine Eingeweide; andere vermuten: Seine Tröge", "So verstehen LXX, Vulg. und die syr. Üs. das hebr. Wort. Die Masoreten deuten es als Milch."] },
      { number: 25, text: "Und jener stirbt mit bitterer Seele und hat nichts vom Glück genossen." },
      { number: 26, text: "Zusammen liegen sie im Staub*, und Gewürm deckt sie zu*.", footnotes: ["℘ Kap. 3,19; Pred 9,2.3", "℘ Kap. 24,20; Jes 14,11"] },
      { number: 27, text: "Siehe, ich erkenne eure Gedanken, und die Anschläge, die ihr gegen mich ersinnt." },
      { number: 28, text: "Denn ihr sagt: Wo ist das Haus des Edlen* und wo das Zelt, die Wohnung der Gottlosen*?", footnotes: ["Wegen des Parallelismus ist das Wort »Edler« hier negativ aufzufassen, etwa im Sinne von »Tyrann« wie z. B. Kap. 12,21.", "℘ Kap. 20,5-7"] },
      { number: 29, text: "Habt ihr die nicht befragt, die des Weges vorüberziehen? Und habt ihr ihre Zeichen nicht genau betrachtet:" },
      { number: 30, text: "dass der Böse am Tag des Verderbens verschont wird, dass sie am Tag des Grimms* <in Sicherheit> geleitet werden*?", footnotes: ["w. der Zornesfluten", "℘ Ps 73,5"] },
      { number: 31, text: "Wer wird ihm ins Gesicht seinen Weg vorhalten? Und hat er gehandelt, wer wird ihm vergelten?" },
      { number: 32, text: "Er aber, er wird zu den Gräbern geleitet, und auf dem Grabhügel hält man Wache." },
      { number: 33, text: "Süß sind ihm die Schollen des Tales. Und alle Welt zieht hinter ihm her, auch vor ihm ohne Zahl." },
      { number: 34, text: "Wie tröstet ihr mich nun mit Dunst? Und von euren Einwänden bleibt <nur> Trug übrig*.", footnotes: ["℘ Kap. 13,12; 16,2"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "Und Elifas von Teman antwortete und sagte*:", heading: "Dritte Rede des Elifas: Hiobs selbstverschuldetes Elend — Aufruf zur Buße", footnotes: ["℘ Kap. 4,1"] },
      { number: 2, text: "Kann denn ein Mann Gott Nutzen bringen*? Vielmehr sich selbst* bringt der Einsichtige Nutzen*.", footnotes: ["℘ Kap. 35,7", "so mit der syr. Üs.; Mas. T.: ihnen", "℘ Spr 9,12"] },
      { number: 3, text: "Ist es dem Allmächtigen von Wert*, wenn du gerecht bist, oder ist es ihm ein Gewinn, wenn du deine Wege vollkommen machst*?", footnotes: ["w. Ist es dem Allmächtigen ein Kleinod", "℘ Kap. 21,15; 34,9"] },
      { number: 4, text: "Für deine <Gottes>furcht sollte er dich strafen, mit dir vor Gericht gehen?" },
      { number: 5, text: "Ist nicht deine Bosheit vielfältig und ohne Ende deine Schuld*?", footnotes: ["℘ Kap. 15,5; 32,3"] },
      { number: 6, text: "Denn du pflegtest deinen Bruder ohne Grund zu pfänden*, und die Kleider zogest du den Nackten aus*.", footnotes: ["℘ 5Mo 24,10.12", "℘ Kap. 24,3.9; 31,19.20"] },
      { number: 7, text: "Nicht <einmal> Wasser gabst du dem Durstigen* zu trinken, und dem Hungrigen verweigertest du Brot.", footnotes: ["w. dem <vor Durst> Erschöpften"] },
      { number: 8, text: "Und dem Mann der Faust* gehört das Land, und der Angesehene* darf darin wohnen.", footnotes: ["o. dem Mächtigen; w. dem Mann des Arms; d. i. Hiob", "w. der, dessen Gesicht erhoben wurde"] },
      { number: 9, text: "Die Witwen hast du mit leeren Händen weggeschickt, und die Arme der Waisen sind zerschlagen*.", footnotes: ["Jemandem »den Arm zerschlagen« heißt, ihm die Kraft nehmen; LXX und Vulg.: die Arme der Waisen hast du zerschlagen\n℘ Kap. 29,12"] },
      { number: 10, text: "Darum sind rings um dich her Fallen*, und in Bestürzung versetzt dich plötzlicher Schrecken*", footnotes: ["w. Klappnetze", "℘ Kap. 18,11"] },
      { number: 11, text: "oder Finsternis, <in der> du nichts sehen kannst*, und Wasserflut, die dich bedeckt*.", footnotes: ["LXX: das Licht wurde Finsternis, du kannst nichts sehen", "℘ Ps 69,2.3; Kla 3,54"] },
      { number: 12, text: "Ist Gott nicht so hoch wie die Himmel?* Schau an die höchsten Sterne*, wie hoch sie sind!", footnotes: ["℘ Kap. 35,5; Pred 5,1", "w. die Spitze der Sterne"] },
      { number: 13, text: "Und du sagst: Was weiß denn Gott?* Kann er durch das Wolkendunkel hindurch richten*?", footnotes: ["℘ Ps 73,11", "℘ Kap. 34,22; Ps 10,11; 139,7; Jer 23,24; Am 9,2.3; Hebr 4,13"] },
      { number: 14, text: "Die Wolken sind ihm ein Versteck, dass er nichts sieht, und am Kreis des Himmels wandelt er. —" },
      { number: 15, text: "Willst du dem Pfad der Vorzeit folgen, den die Männer des Unheils betraten*,", footnotes: ["℘ 1Mo 6,5.12"] },
      { number: 16, text: "die gepackt wurden* vor der Zeit* — ein Strom hat ihr Fundament weggerissen* —,", footnotes: ["d. h. von Gottes Gericht", "℘ Kap. 36,14", "w. ein Strom hat sich über ihr Fundament ergossen"] },
      { number: 17, text: "die zu Gott sagten: Weiche von uns*!, und: Was kann der Allmächtige uns* schon tun*?", footnotes: ["℘ Kap. 21,14.15; 2Mo 5,23", "so mit LXX und der syr. Üs.; Mas. T.: ihnen", "℘ Kap. 13,12; 16,2"] },
      { number: 18, text: "Und er hatte ihre Häuser <doch> mit Gutem erfüllt*! — Aber von mir bleibe fern der Rat der Gottlosen*! —", footnotes: ["℘ Apg 14,17", "℘ Kap. 21,16"] },
      { number: 19, text: "Die Gerechten sehen es und freuen sich*, und der Schuldlose verspottet sie:", footnotes: ["℘ Ps 107,42"] },
      { number: 20, text: "Fürwahr, unsere Gegner sind* vernichtet, und ihren Rest hat das Feuer gefressen*!*", footnotes: ["Eine griech., die syr., aram. Üs. und Vulg. lesen: ihr Bestand <an Menschen> ist", "℘ Kap. 20,29", "w. Wenn nicht unsere Gegner vernichtet sind und das Feuer ihren Rest gefressen hat<, dann . . .!> — Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde."] },
      { number: 21, text: "Söhne dich doch aus mit ihm* und halte Frieden! Dadurch kommt zu dir <dann> wieder Gutes.", footnotes: ["w. Sei <wieder> vertraut mit ihm"] },
      { number: 22, text: "Nimm aus seinem Mund doch Weisung an und lege seine Worte dir ins Herz*!", footnotes: ["℘ Kap. 23,12"] },
      { number: 23, text: "Wenn du umkehrst zum Allmächtigen, *wirst du wieder aufgebaut*, hältst du Unrecht fern von deinem Zelt*.", footnotes: ["LXX: und <wenn> du dich demütigst", "LXX: und <wenn> du dich demütigst\n℘ 2Chr 33,13; Ps 130,4; Jes 55,7; Hos 6,1", "℘ Kap. 8,6; 2Tim 2,19"] },
      { number: 24, text: "Wirf in den Staub das Golderz und in den Kies der Bäche <dein Gold aus> Ofir*,", footnotes: ["℘ 1Kö 9,28"] },
      { number: 25, text: "so wird der Allmächtige dir dein Golderz und erlesenes Silber sein*.", footnotes: ["℘ Kla 3,24; Mt 6,19-21"] },
      { number: 26, text: "Denn dann wirst du am Allmächtigen deine Lust haben* und zu Gott dein Gesicht erheben*.", footnotes: ["℘ Kap. 27,10; Jes 58,14", "℘ Kap. 11,15; Ps 37,4"] },
      { number: 27, text: "Du wirst zu ihm beten, und er wird dich erhören*; und deine Gelübde wirst du erfüllen*.", footnotes: ["℘ 2Kö 13,4; 1Chr 4,10; 2Chr 33,13; Jes 58,9; Jer 29,12", "℘ Ps 50,14; 66,13"] },
      { number: 28, text: "Beschließt du eine Sache, wird sie zustande kommen*, und über deinen Wegen leuchtet Licht auf*.", footnotes: ["℘ Ps 1,3", "℘ Kap. 29,3; Ps 97,11"] },
      { number: 29, text: "Denn er erniedrigt hochmütiges Reden*, aber dem mit niedergeschlagenen Augen hilft er*.", footnotes: ["T.; Mas. T.: Denn sie erniedrigen, und du sprichst hochmütig", "℘ Jes 57,15; 1Petr 5,6"] },
      { number: 30, text: "<Selbst> den nicht Schuldlosen* wird er retten; ja, er wird gerettet durch die Reinheit deiner Hände*.", footnotes: ["Andere üs. mit Textänderung: Und den schuldlosen Mann", "℘ Kap. 42,8.9"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "Und Hiob antwortete und sagte*:", heading: "Hiobs Antwort: Klage über Gott wegen mangelnder Möglichkeit zur Rechtfertigung", footnotes: ["℘ Kap. 3,2"] },
      { number: 2, text: "Auch heute ist Widerspruch mein Anliegen*. Seine Hand* lastet schwer auf meinem Seufzen*.", footnotes: ["o. das, was mich plagt\n℘ Kap. 7,11", "so mit LXX und der syr. Üs.; Mas. T.: Meine Hand", "℘ Kla 3,28"] },
      { number: 3, text: "Ach, dass ich wüsste, wie ich ihn finden und zu seiner Stätte kommen könnte*!", footnotes: ["℘ Kap. 16,20"] },
      { number: 4, text: "Ich wollte vor ihm den Rechtsfall darlegen und meinen Mund mit Beweisgründen* füllen*.", footnotes: ["w. mit Entgegnungen, o. Vorhaltungen", "℘ Kap. 13,3.18"] },
      { number: 5, text: "Ich möchte <gern> die Worte wissen, die er mir <dann> antwortet, und erfahren, was er zu mir sagt." },
      { number: 6, text: "Ob er in der Fülle <seiner> Kraft wohl den Rechtsstreit mit mir führen würde? Nein, gerade er wird auf mich achten." },
      { number: 7, text: "Dort würde sich ein Redlicher mit ihm auseinandersetzen, und entkommen werde ich für immer meinem Richter*.", footnotes: ["die alten Üs. und viele hebr. Handschr.: und ich werde für immer mein Recht durchsetzen"] },
      { number: 8, text: "Siehe, gehe ich nach vorn, so ist er nicht da, nach hinten, so bemerke ich ihn nicht," },
      { number: 9, text: "nach links, sein Tun schaue ich nicht*, biege ich ab* nach rechts*, so sehe ich ihn nicht*.", footnotes: ["T.; Mas. T.: nach links — bei seinem Tun —, so schaue ich ihn nicht", "so mit der syr. Üs. und Vulg.; Mas. T.: biegt er ab", "o. Siehe, gehe ich nach Osten . . . nach Westen . . . 9 nach Norden . . . nach Süden", "℘ Kap. 9,11; 34,29; Jes 45,15"] },
      { number: 10, text: "Denn er kennt den Weg, der bei mir ist*. Prüfte er mich*, wie Gold ginge ich hervor*.", footnotes: ["℘ Kap. 31,4; Ps 1,6; 139,3", "℘ Jer 12,3", "℘ Kap. 31,6; Ps 17,3; Spr 17,3"] },
      { number: 11, text: "An seinem Schritt hat mein Fuß festgehalten, seinen Weg habe ich bewahrt und bin nicht abgewichen*.", footnotes: ["℘ Kap. 10,7; 31,7; Ps 18,22; 44,19; Spr 4,5"] },
      { number: 12, text: "Vom Gebot seiner Lippen ließ ich nicht ab*; mehr als es meine Pflicht gewesen wäre, wahrte ich* die Worte seines Mundes*.", footnotes: ["so mit LXX, Vulg. und vielen hebr. Handschr.; Mas. T.: Vom Gebot seiner Lippen — und ich ließ nicht ab <davon>", "LXX und Vulg.: in meinem Busen wahrte ich", "℘ Kap. 22,22; 33,9"] },
      { number: 13, text: "Doch er, der Eine — wer kann <ihm> wehren*? —, er tut, was seine Seele begehrt*.", footnotes: ["o. wer kann es rückgängig machen", "℘ Ps 115,3; Jes 46,10.11"] },
      { number: 14, text: "Ja, er wird vollenden, was für mich bestimmt ist; und dergleichen hat er vieles <noch> im Sinn*.", footnotes: ["℘ Kap. 10,13"] },
      { number: 15, text: "Bestürzt bin ich darum vor seinem Angesicht*; erwäge ich es, so bebe ich vor ihm*.", footnotes: ["o. Darum schrecke ich vor ihm zurück", "℘ Ps 119,120"] },
      { number: 16, text: "Gott hat mein Herz verzagt gemacht, und der Allmächtige hat mich in Bestürzung versetzt*.", footnotes: ["℘ Kap. 16,12-14"] },
      { number: 17, text: "Doch werde ich nicht zum Schweigen gebracht vor Finsternis, noch von mir selbst, den Dunkelheit bedeckt." },
    ]},
    { number: 24, verses: [
      { number: 1, text: "Warum sind dem Allmächtigen die Zeiten nicht unbekannt*, aber die, die ihn kennen, schauen seine Tage nicht?", heading: "Unbegreifliche Nachsicht Gottes mit den Gottlosen", footnotes: ["w. nicht verborgen"] },
      { number: 2, text: "Die Grenzen verrückt man*, raubt eine Herde und bringt sie auf die Weide.", footnotes: ["℘ 5Mo 27,17"] },
      { number: 3, text: "Den Esel der Waisen treibt man weg, pfändet der Witwe den Stier*.", footnotes: ["℘ Kap. 22,6; 5Mo 24,7.17"] },
      { number: 4, text: "Man stößt die Armen vom Weg*; miteinander müssen sich die Elenden des Landes verkriechen*.", footnotes: ["℘ Am 4,1", "℘ Spr 28,28"] },
      { number: 5, text: "Siehe, <scheu wie> Wildesel* in der Wüste ziehen sie hinaus an ihr Werk, suchen nach Nahrung <in> der Steppe als Brot* für die Kinder.", footnotes: ["℘ Kap. 39,5", "T.; Mas. T.: suchen Nahrung; die Steppe <liefert> ihm Brot"] },
      { number: 6, text: "Auf dem Feld ernten sie sein Futter ab* und halten im Weinberg des Gottlosen Nachlese.", footnotes: ["d. h. das Futter, das auf dem Feld wächst; o. das Futter, das dem Gottlosen gehört. — Andere üs. mit Textänderung: Auf dem Feld ernten sie bei Nacht"] },
      { number: 7, text: "Nackt übernachten sie, ohne Gewand und ohne Decke in der Kälte*,", footnotes: ["℘ 5Mo 24,12.13; Mt 25,43"] },
      { number: 8, text: "werden vom Regenguss der Berge durchnässt, und ohne Zufluchtsort klammern sie sich an den Fels." },
      { number: 9, text: "Man reißt das Waisenkind <der Mutter> von der Brust, und den Säugling des Elenden* nimmt man als Pfand*.", footnotes: ["so mit anderer Vokalisierung; Mas. T.: und was auf dem Elenden ist", "℘ Kap. 22,6; 5Mo 24,7.17"] },
      { number: 10, text: "Nackt müssen sie einhergehen, ohne Gewand*, und hungrig die Garben schleppen.", footnotes: ["℘ 5Mo 24,12.13; Mt 25,43"] },
      { number: 11, text: "Zwischen ihren Mauern* pressen sie Öl, treten die Kelter und leiden Durst*.", footnotes: ["d. i. zwischen den Mauern der Gottlosen; d. h. gleich in deren Olivenhainen", "℘ Jak 5,4"] },
      { number: 12, text: "Von der Stadt her ächzen Sterbende*, und die Seele der Durchbohrten schreit auf*. Doch Gott nimmt keinen Anstoß daran*.", footnotes: ["so mit einer hebr. Handschr.; Mas. T.: die Leute", "o. die Seele der Durchbohrten ruft um Hilfe o. schreit nach Rache\n℘ 1Mo 4,10; Pred 4,1", "2 hebr. Handschr. und die syr. Üs.: Doch Gott achtet nicht auf <ihr> Flehen\n℘ Ps 10,13; Jer 12,1.2"] },
      { number: 13, text: "Jene gehören zu den Feinden des Lichtes*, nichts wollen sie von seinen Wegen wissen und bleiben nicht auf seinen Pfaden.", footnotes: ["℘ Kap. 38,13.15; 1Kö 3,20; Joh 3,20"] },
      { number: 14, text: "Vor dem Tageslicht steht der Mörder auf, um den Elenden und Armen zu töten*, und in der Nacht geht der Dieb um*.", footnotes: ["℘ Ps 10,8.9", "T.; Mas. T.: und in der Nacht gleicht er dem Dieb"] },
      { number: 15, text: "Auch des Ehebrechers Auge lauert auf die Abenddämmerung*, indem er sagt: Kein Auge kann mich dann erspähen*. Und eine Hülle legt er aufs Gesicht.", footnotes: ["℘ Spr 7,7-10", "℘ Hes 8,12"] },
      { number: 16, text: "Man bricht im Dunkeln in die Häuser ein. Bei Tage schließen sie sich ein, Licht kennen sie nicht." },
      { number: 17, text: "Denn ihnen allen miteinander <gilt> als Morgen die Finsternis*; ja, <jeder von ihnen> kennt die Schrecken der Finsternis.", footnotes: ["℘ Kap. 38,13.15; 1Kö 3,20; Joh 3,20"] },
      { number: 18, text: "Leicht <treibt> er <dahin wie> auf der Oberfläche des Wassers, verflucht wird ihr <Feld>stück auf Erden*; nicht <mehr> schlägt er den Weg zu den Weinbergen ein.", footnotes: ["℘ 5Mo 28,16-20; Spr 3,33"] },
      { number: 19, text: "Dürre und Hitze raffen Schneewasser weg; <so> der Scheol <alle>, die gesündigt haben." },
      { number: 20, text: "Ihn vergisst der Mutterleib. Gewürm labt sich an ihm*, nie mehr wird seiner gedacht* — so muss das Unrecht wie Holz zerbrechen —,", footnotes: ["℘ Kap. 21,26", "℘ Jes 26,14"] },
      { number: 21, text: "er, der sich mit der Unfruchtbaren eingelassen hatte, die nicht gebiert, und der Witwe nichts Gutes erwies*.", footnotes: ["℘ Spr 15,25"] },
      { number: 22, text: "<Gott> erhält durch seine Kraft den Mächtigen* am Leben; der steht auf, auch <wenn> er <schon> des Lebens nicht mehr sicher war*.", footnotes: ["w. die Mächtigen", "o. <Gott> rafft durch seine Kraft den Mächtigen dahin; erhebt er sich, so ist der <seines> Lebens nicht mehr sicher"] },
      { number: 23, text: "Er* gibt ihm Sicherheit, und der weiß sich gestützt*. Und seine* Augen <wachen> über ihren Wegen.", footnotes: ["d. i. Gott", "℘ Ps 10,5", "d. i. Gottes"] },
      { number: 24, text: "Sie kommen hoch — ein wenig, dann ist es aus. Sie werden erniedrigt, wie alle <andern> zusammengerafft und wie der Kopf der Ähre abgeschnitten*.", footnotes: ["o. und verdorren wie der Kopf der Ähre\n℘ Kap. 21,13"] },
      { number: 25, text: "Ist es denn nicht so? Wer will mich Lügen strafen und meine Rede zunichte machen*?", footnotes: ["℘ Kap. 27,4"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "Und Bildad von Schuach antwortete und sagte*:", heading: "Dritte Rede des Bildad: Keine Gerechtigkeit der Menschen vor Gott", footnotes: ["℘ Kap. 8,1"] },
      { number: 2, text: "Herrschaft und Schrecken sind bei ihm*, der Frieden schafft in seinen Höhen.", footnotes: ["℘ Ps 66,3.5; 76,8"] },
      { number: 3, text: "Gibt es eine Zahl für seine Scharen*? Und über wem erhebt sich nicht sein Licht*?", footnotes: ["℘ Dan 7,10", "℘ Joh 1,9"] },
      { number: 4, text: "Wie könnte ein Mensch gerecht sein* vor Gott, und wie könnte rein dastehen ein von der Frau Geborener?*", footnotes: ["o. im Recht sein", "℘ Kap. 4,18; 9,2; 14,1.4"] },
      { number: 5, text: "Siehe, selbst der Mond scheint nicht hell, und die Sterne sind nicht rein in seinen Augen*,", footnotes: ["℘ Kap. 4,18; 9,2; 14,1.4"] },
      { number: 6, text: "geschweige denn der Mensch, die Made, und das Menschenkind, der Wurm!*", footnotes: ["℘ Kap. 4,19; Jes 41,14"] },
    ]},
    { number: 26, verses: [
      { number: 1, text: "Und Hiob antwortete und sagte*:", heading: "Hiobs Antwort: Anerkenntnis der unfassbaren Majestät Gottes", footnotes: ["℘ Kap. 3,2"] },
      { number: 2, text: "Wie hast du doch dem beigestanden, der keine Kraft hat, hast dem Arm geholfen, der nicht stark ist!" },
      { number: 3, text: "Wie hast du den beraten, der keine Weisheit hat, und Gelingen in Fülle offenbart*!", footnotes: ["℘ Kap. 12,2.3"] },
      { number: 4, text: "Wem hast du <denn deine> Worte mitgeteilt*, und wessen Geist ist von dir ausgegangen?", footnotes: ["o. Mit wessen Hilfe hast du <deine> Worte verkündet"] },
      { number: 5, text: "<Vor Gott> beben die Schatten unter dem Wasser und seinen Bewohnern." },
      { number: 6, text: "Nackt <liegt> der Scheol vor ihm, und keine Hülle hat der Abgrund*.", footnotes: ["o. der Ort des Verlorenseins; d. i. die Welt der Toten; hebr. Abaddon\n℘ Spr 15,11"] },
      { number: 7, text: "Er spannt den Norden* aus über der Leere*, hängt die Erde auf über dem Nichts*.", footnotes: ["d. h. den nördlichen Himmel", "℘ Kap. 9,8; Ps 89,13", "℘ Jes 40,21.22"] },
      { number: 8, text: "In seine Wolken bindet er das Wasser ein, dass unter ihm das Gewölk nicht reißt*.", footnotes: ["℘ Kap. 37,11; 1Mo 1,6.7; Spr 8,28; 30,4"] },
      { number: 9, text: "Er versperrt den Anblick <seines> Thrones*, indem er sein Gewölk darüber ausbreitet*.", footnotes: ["Andere üs. mit anderer Vokalisierung: Er überzieht das Gesicht des Vollmonds", "℘ Ps 97,2"] },
      { number: 10, text: "Eine Schranke* hat er als Kreis über der Fläche des Wassers* gezogen bis zum äußersten Ende von Licht und Finsternis*.", footnotes: ["o. Ordnung", "℘ Kap. 38,10.11", "w. bis zum Äußersten des Lichtes mit der Finsternis"] },
      { number: 11, text: "Die Säulen des Himmels wanken* und erstarren vor seinem Drohen*.", footnotes: ["℘ 2Sam 22,8", "℘ Nah 1,5.6"] },
      { number: 12, text: "Durch seine Kraft hat er das Meer erregt* und durch seine Einsicht Rahab* zerschmettert*.", footnotes: ["℘ Jes 51,15; Jer 31,35; Lk 21,25", "Wahrscheinlich ein urzeitliches Seeungeheuer; hier als Bild gottfeindlicher Mächte", "℘ Kap. 9,13"] },
      { number: 13, text: "Durch seinen Hauch wird der Himmel heiter, seine Hand hat die schnelle Schlange durchbohrt*.", footnotes: ["℘ Jes 27,1"] },
      { number: 14, text: "Siehe, das sind die Säume seiner Wege; und wie wenig* hören wir von ihm*! Doch den Donner seiner Machttaten*, wer versteht ihn?", footnotes: ["o. welch <leises> Flüsterwort", "℘ Kap. 11,7; 37,5; Pred 11,5", "LXX, Vulg., die syr. und aram. Üs.: seiner Macht"] },
    ]},
    { number: 27, verses: [
      { number: 1, text: "Und Hiob fuhr fort, seinen Spruch zu erheben, und sagte*:", heading: "Hiobs Schlussrede: Beteuerung seiner Unschuld — Vergängliches Glück der Gottlosen", footnotes: ["℘ Kap. 29,1"] },
      { number: 2, text: "So wahr Gott lebt, der mir mein Recht entzogen*, und der Allmächtige, der meine Seele bitter gemacht hat* —", footnotes: ["℘ Kap. 34,5", "℘ Kap. 9,17.18"] },
      { number: 3, text: "ja, solange noch irgendetwas von meinem Atem in mir ist* und Gottes Hauch in meiner Nase —:", footnotes: ["o. denn mein Atem ist noch ganz in mir"] },
      { number: 4, text: "Wenn meine Lippen Unrecht reden und wenn meine Zunge Trug ausspricht*!*", footnotes: ["℘ Kap. 6,28; 24,25", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde."] },
      { number: 5, text: "Fern sei es von mir, euch recht zu geben*. Bis ich verscheide, lasse ich meine Rechtschaffenheit* nicht von mir weichen*.", footnotes: ["w. Verwerfliches sei es mir! Wenn ich euch recht gebe<, dann . . .!>; s. vorige Anm.", "o. Unschuld; o. Lauterkeit", "℘ Kap. 17,9; 31,7"] },
      { number: 6, text: "An meiner Gerechtigkeit halte ich fest und werde sie nicht fahren lassen*; mein Herz schmäht nicht einen von meinen Tagen*.", footnotes: ["℘ Kap. 17,9; 31,7", "℘ 1Kor 4,4"] },
      { number: 7, text: "Meinem Feind ergehe es wie dem Gottlosen und <dem>, der gegen mich auftritt, wie dem Übeltäter." },
      { number: 8, text: "Denn was ist des Ruchlosen Hoffnung*, wenn sein Leben ein Ende findet*, wenn Gott seine Seele nimmt*?", footnotes: ["℘ Kap. 8,13", "w. <Gott den Lebensfaden> abschneidet", "o. herauszieht"] },
      { number: 9, text: "Wird Gott sein Hilfegeschrei* hören, wenn die Not über ihn kommt*?", footnotes: ["o. Klagegeschrei", "℘ Ps 18,42; Mi 3,4; Joh 9,31"] },
      { number: 10, text: "Oder wird er an dem Allmächtigen seine Lust haben, Gott anrufen zu jeder Zeit*?", footnotes: ["℘ Kap. 22,26.27; Ps 14,4"] },
      { number: 11, text: "Ich will euch belehren über Gottes Tun*, was der Allmächtige im Sinn hat*, nicht verhehlen*.", footnotes: ["o. Gottes Macht; w. Gottes Hand", "w. was bei dem Allmächtigen ist", "℘ Kap. 11,7"] },
      { number: 12, text: "Siehe, ihr selbst habt es alle geschaut, warum denn schwatzt ihr so nichtiges Zeug?*", footnotes: ["℘ Kap. 16,3"] },
      { number: 13, text: "Dies ist das Los des gottlosen Menschen bei Gott und das Erbe der Gewalttätigen, das sie vom Allmächtigen empfangen*:", footnotes: ["℘ Kap. 20,29; 31,2"] },
      { number: 14, text: "Wenn seine Söhne zahlreich werden, dann für das Schwert*, und seine Sprösslinge können sich nicht satt essen an Brot*.", footnotes: ["℘ Est 9,6-10; Hos 9,13", "℘ Ps 109,10"] },
      { number: 15, text: "Seine Übriggebliebenen werden vom Tod begraben*, und seine Witwen weinen nicht*.", footnotes: ["d. h. von niemandem", "d. h. halten keine Totenklage\n℘ Ps 78,64"] },
      { number: 16, text: "Wenn er <auch> Silber aufschüttet wie Staub und Kleider aufstapelt wie Lehm —" },
      { number: 17, text: "er stapelt sie <zwar> auf, aber der Gerechte bekleidet sich <damit>, und das Silber teilt der Schuldlose auf*.", footnotes: ["℘ Est 8,1; Spr 13,22; Pred 2,26"] },
      { number: 18, text: "Er hat sein Haus gebaut wie die Motte* und der Laubhütte gleich, die ein Wächter <sich> macht.", footnotes: ["LXX und die syr. Üs.: wie die Spinne"] },
      { number: 19, text: "Reich legt er sich hin, und nichts ist ihm genommen*. Er schlägt die Augen auf, da ist es nicht mehr*.", footnotes: ["w. und nicht wird <ihm etwas> weggenommen. — Andere üs. mit LXX und der syr. Üs.: und er tut es nicht wieder", "℘ Kap. 20,5; Spr 23,4.5"] },
      { number: 20, text: "Wie Wasser erreichen ihn jähe Schrecken*, des Nachts entführt ihn ein Sturmwind*.", footnotes: ["℘ Kap. 18,11", "℘ Ps 83,16"] },
      { number: 21, text: "Der Ostwind hebt ihn empor, dass er dahinfährt, und reißt ihn weg von seiner Stätte*.", footnotes: ["℘ Kap. 21,18"] },
      { number: 22, text: "Er stürzt sich auf ihn* ohne Schonung*; vor seiner Gewalt will er flüchtend entfliehen.", footnotes: ["w. schleudert <Steine> auf ihn", "℘ 1Sam 25,29; Ps 11,6"] },
      { number: 23, text: "Man klatscht über ihn in die Hände* und pfeift seinetwegen von seiner Stätte aus.", footnotes: ["T.; Mas. T.: in ihre Hände\n℘ Nah 3,19"] },
    ]},
    { number: 28, verses: [
      { number: 1, text: "Ja, für Silber gibt es einen Fundort und eine Stelle für Gold, wo man es auswäscht.", heading: "Natürlicher Zugang zu den Schätzen der Erde, aber kein Zugang zur Weisheit als nur durch Gottesfurcht" },
      { number: 2, text: "Eisen wird aus dem Erdreich hervorgeholt, und Gestein schmilzt man zu Kupfer." },
      { number: 3, text: "Man setzt der Finsternis ein Ende und durchforscht bis zur äußersten Grenze das Gestein der Dunkelheit und Finsternis*.", footnotes: ["℘ Kap. 3,5"] },
      { number: 4, text: "Man bricht einen Schacht fern von dem <droben> Wohnenden*. Vergessen von dem Fuß<, der oben geht,> baumeln sie*, fern von den Menschen schweben sie.", footnotes: ["Manche lesen mit anderer Wortabtrennung: Es bricht Schächte ein fremdes Volk", "o. Vergessen, ohne <Halt durch den> Fuß, baumeln sie"] },
      { number: 5, text: "Die Erde, aus der das Brot hervorkommt*, ihr Unteres wird umgewühlt wie vom Feuer.", footnotes: ["℘ Ps 104,14"] },
      { number: 6, text: "Ihr Gestein ist die Fundstätte des Saphirs, und Goldstaub <findet sich> darin." },
      { number: 7, text: "Ein Pfad, den der Raubvogel nicht kennt und den das Auge der Königsweihe nicht erblickt hat —" },
      { number: 8, text: "nie hat das stolze Wild* ihn je betreten, der Löwe ist auf ihm nicht geschritten.", footnotes: ["w. nie haben die Söhne des Stolzen"] },
      { number: 9, text: "Nach dem harten Gestein* streckt man seine Hand aus, wühlt die Berge um von Grund auf.", footnotes: ["w. Nach dem Kiesel"] },
      { number: 10, text: "In die Felsen treibt man Stollen*, und allerlei Kostbares sieht das* Auge.", footnotes: ["o. <wasserführende> Gänge", "w. sein"] },
      { number: 11, text: "Die Sickerstellen von Wasseradern* dämmt man ein*, und Verborgenes* zieht man hervor ans Licht.", footnotes: ["w. von Strömen", "so mit anderer Vokalisierung; Mas. T.: Wasseradern dämmt man ein — weg vom Weinen", "T.; Mas. T.: ihr Verborgenes; d. h. wohl das der Erde"] },
      { number: 12, text: "Aber die Weisheit, wo kann man sie finden*, und wo ist denn die Fundstätte der Einsicht?", footnotes: ["℘ Pred 7,24; Kol 2,3; Jak 1,5"] },
      { number: 13, text: "Kein Mensch erkennt ihren Wert*, und im Land der Lebendigen wird sie nicht gefunden.", footnotes: ["Üs. unsicher; w. ihre Schicht; vielleicht ist an die verschiedenen Gesteinsschichten im Bergwerk gedacht; LXX: den Weg zu ihr, o. ihren Weg"] },
      { number: 14, text: "Die Tiefe sagt: In mir ist sie nicht! — und das Meer sagt: Nicht bei mir!" },
      { number: 15, text: "Geläutertes <Gold>* kann für sie nicht gegeben und Silber nicht abgewogen werden als Kaufpreis für sie.", footnotes: ["so mit anderer Vokalisierung; Mas. T.: Ein Verschluss"] },
      { number: 16, text: "Sie wird nicht aufgewogen mit Gold aus Ofir, mit kostbarem Schoham-Stein* oder Saphir.", footnotes: ["d. i. Onyx, o. Karneol"] },
      { number: 17, text: "Gold und Glas sind ihr nicht vergleichbar, noch lässt sie sich eintauschen gegen ein goldenes Gerät." },
      { number: 18, text: "Korallen und Bergkristall brauchen gar nicht erwähnt zu werden; und ein Beutel <voller> Weisheit ist mehr <wert> als <ein Beutel voller> Perlen*.", footnotes: ["℘ Spr 3,13-15; 20,15"] },
      { number: 19, text: "Nicht vergleichbar mit ihr ist Topas aus Kusch; mit dem reinsten Gold wird sie nicht aufgewogen*.", footnotes: ["℘ Spr 3,13-15; 20,15"] },
      { number: 20, text: "Die Weisheit nun, woher kommt sie, und wo denn ist die Fundstätte der Einsicht?" },
      { number: 21, text: "Verhüllt ist sie vor den Augen alles Lebendigen, und vor den Vögeln des Himmels ist sie verborgen." },
      { number: 22, text: "Der Abgrund* und der Tod sagen: <Nur> vom Hörensagen* haben wir mit unsern Ohren von ihr gehört.", footnotes: ["hebr. Abaddon; vgl. Anm. zu Kap. 26,6", "w. eine Kunde"] },
      { number: 23, text: "Gott ist es, der Einsicht hat in ihren Weg, und er kennt ihre Stätte*.", footnotes: ["℘ Pred 7,24; Kol 2,3; Jak 1,5"] },
      { number: 24, text: "Denn nur er blickt bis zu den Enden der Erde. Unter dem ganzen Himmel schaut er aus*,", footnotes: ["℘ 2Chr 16,9; Ps 113,6"] },
      { number: 25, text: "um dem Wind ein Gewicht zu bestimmen*; und das Wasser begrenzte er mit einem Maß.", footnotes: ["℘ Kap. 38,4.5; Jes 40,12"] },
      { number: 26, text: "Als er dem Regen eine Ordnung bestimmte und einen Weg der donnernden Gewitterwolke*,", footnotes: ["℘ Kap. 36,27-33; 37,2-5.15; 38,25-27; Ps 135,7; Jer 14,22"] },
      { number: 27, text: "da sah er sie und verkündigte sie*, er stellte sie hin* und erforschte sie auch.", footnotes: ["o. zählte sie", "o. setzte sie ein\n℘ Spr 8,22"] },
      { number: 28, text: "Und zu dem Menschen sprach er: Siehe, die Furcht des Herrn, sie ist Weisheit*, und vom Bösen weichen, <das> ist Einsicht*.", footnotes: ["℘ Ps 94,10; 111,10; Spr 1,7; 8,13", "℘ 5Mo 4,6; Spr 16,6"] },
    ]},
    { number: 29, verses: [
      { number: 1, text: "Und Hiob fuhr fort, seinen Spruch zu erheben, und sagte*:", heading: "Hiobs früheres Glück, Gottes Segen und Anerkennung seitens der Menschen", footnotes: ["℘ Kap. 27,1"] },
      { number: 2, text: "Dass ich wäre wie in den früheren Monaten, wie in den Tagen, da Gott mich behütete! —" },
      { number: 3, text: "als seine Leuchte über meinem Haupt schien, als ich bei seinem Licht durch die Finsternis ging*;", footnotes: ["℘ Kap. 22,28; Ps 18,29; 112,4"] },
      { number: 4, text: "wie ich war in den Tagen meiner Jugend, als über meinem Zelt Gottes Rat* <waltete>,", footnotes: ["o. traute Gemeinschaft"] },
      { number: 5, text: "als der Allmächtige noch mit mir war, meine Söhne* mich umgaben;", footnotes: ["o. meine Knechte"] },
      { number: 6, text: "als meine Schritte sich in Dickmilch badeten, und der Fels neben mir Bäche von Öl ausgoss*!", footnotes: ["℘ 5Mo 32,13; Ps 81,17; Hes 16,13"] },
      { number: 7, text: "Ging ich durch das Tor in die Stadt hinauf, stellte ich meinen Sitz auf dem <öffentlichen> Platz auf*.", footnotes: ["℘ 1Mo 34,20; Spr 31,23"] },
      { number: 8, text: "Sahen mich <dann> die jungen Männer, so verbargen sie sich, und die Greise erhoben sich, blieben stehen*.", footnotes: ["o. traten zur Seite (um Platz zu machen)"] },
      { number: 9, text: "Die Obersten hielten die Worte zurück und legten die Hand auf ihren Mund." },
      { number: 10, text: "Die Stimme der führenden Männer* verstummte*, und ihre Zunge klebte an ihrem Gaumen.", footnotes: ["w. Fürsten", "w. verbarg sich"] },
      { number: 11, text: "Hörte <mich> ein Ohr, so pries es mich glücklich, und sah <mich> ein Auge, so legte es Zeugnis für mich ab." },
      { number: 12, text: "Denn ich befreite den Elenden, der um Hilfe rief, und die Waise, die* keinen Helfer hatte*.", footnotes: ["o. die Waise und den, der", "℘ Kap. 22,6.9; 31,18; Ps 82,3.4; Spr 31,8; Jak 1,27"] },
      { number: 13, text: "Der Segenswunsch des Mutlosen* kam auf mich*, und das Herz der Witwe ließ ich jauchzen.", footnotes: ["o. des Verlorenen", "℘ Kap. 31,19.20; 5Mo 24,13; Rt 2,20; Spr 11,26"] },
      { number: 14, text: "Ich kleidete mich in Gerechtigkeit*, mich bekleidete wie ein Oberkleid und Kopfbund mein Recht.", footnotes: ["℘ Ps 132,9"] },
      { number: 15, text: "Auge* wurde ich dem Blinden, und Fuß* dem Lahmen war ich!", footnotes: ["w. Beide Augen", "w. beide Füße"] },
      { number: 16, text: "Ein Vater war ich für die Armen*, und den Rechtsstreit dessen, den ich nicht kannte, untersuchte ich*.", footnotes: ["℘ Kap. 30,25; 31,31.32", "℘ Spr 29,7"] },
      { number: 17, text: "Und ich zerschmetterte die Kinnladen des Übeltäters*, und seinen Zähnen entriss ich* die Beute.", footnotes: ["℘ Spr 30,14", "T.; Mas. T.: aus seinen Zähnen warf ich"] },
      { number: 18, text: "Und ich sagte <mir>: Mit meinem Nest werde ich verscheiden und wie der Phönix* meine Tage zahlreich machen.", footnotes: ["Der Phönix war ein sagenhafter Vogel, der mehrere hundert Jahre lebte, dann samt seinem Nest verbrannte und aus der Asche wieder zu neuem Leben erstand. Andere üs.: und wie Sand"] },
      { number: 19, text: "Meine Wurzel wird geöffnet sein zum Wasser hin, und der Tau wird auf meinem Gezweig übernachten." },
      { number: 20, text: "Meine Ehre wird frisch bei mir bleiben, und mein Bogen in meiner Hand wird sich verjüngen*.", footnotes: ["w. mein Bogen . . . wird <Kraft> folgen lassen. — Andere üs.: mein Bogen . . . wird <Pfeil auf Pfeil> folgen lassen\n℘ 1Mo 49,24"] },
      { number: 21, text: "Man hörte mir zu und wartete und verhielt sich still gegenüber meinem Rat." },
      { number: 22, text: "Hatte ich geredet, so* sagte man nichts mehr <dagegen>, und auf sie träufelte meine Rede*.", footnotes: ["w. Nach meinem Wort", "℘ 5Mo 32,2; Mi 5,6"] },
      { number: 23, text: "Und sie warteten auf mich wie auf Regen und sperrten ihren Mund auf <wie> nach Spätregen*.", footnotes: ["℘ Jer 5,24; Sach 10,1"] },
      { number: 24, text: "Lächelte ich denen zu, die kein Vertrauen hatten, dann nahmen sie das Leuchten meines Gesichts auf*.", footnotes: ["w. so ließen sie das Leuchten meines Gesichts nicht fallen"] },
      { number: 25, text: "Ich wählte für sie den Weg aus und saß als Haupt und thronte wie ein König unter der Kriegsschar wie einer, der Trauernde tröstet." },
    ]},
    { number: 30, verses: [
      { number: 1, text: "Jetzt aber lachen sie über mich, die jünger sind als ich an Jahren*, bei denen ich es abgelehnt hätte, ihre Väter den Hunden meiner Herde beizugesellen.", heading: "Sein jetziges Elend, Verachtung durch die Menschen, Gottes feindliche Gesinnung — Berechtigung zur Klage", footnotes: ["w. an Tagen\n℘ Kap. 19,18"] },
      { number: 2, text: "Wozu sollte mir auch die Kraft ihrer Hände <dienen>? Die Rüstigkeit ist bei ihnen <jedoch> verloren." },
      { number: 3, text: "Durch Mangel und Hunger unfruchtbar* — sie, die die <Wurzeln der> Wüste abnagen — sind sie Menschen der Öde und Verödung <geworden>*,", footnotes: ["o. Verschwunden ist ihre Rüstigkeit 3 durch Mangel und unfruchtbaren Hunger", "so mit einer hebr. Handschr.; andere üs. mit Textänderung: sie, die die Wüste abnagen, das <trockene> Gras der Öde und Verödung; Mas. T.: sie, die die <Wurzeln der> Wüste abnagen, die vergangene Nacht der Öde und Verödung"] },
      { number: 4, text: "sie, die Salzkraut pflücken am Gesträuch und deren Brot die Ginsterwurzel ist." },
      { number: 5, text: "Aus der Gemeinschaft werden sie vertrieben. Man schreit über sie wie über den Dieb." },
      { number: 6, text: "Am Abhang der Bachtäler müssen sie wohnen, in Erdlöchern und Felsen<höhlen>*.", footnotes: ["℘ Ri 6,2"] },
      { number: 7, text: "Zwischen Sträuchern schreien* sie, unter Unkraut* finden sie sich zusammen.", footnotes: ["Das Wort bezeichnet sonst das Schreien des Esels; vgl. Kap. 6,5.", "o. Dorngestrüpp; o. Disteln"] },
      { number: 8, text: "Gottloses Volk, ja, Gesindel ohne Namen, sind sie aus dem Land hinausgepeitscht worden." },
      { number: 9, text: "Und nun bin ich ihr Spottlied geworden, ich wurde für sie zum Gerede*.", footnotes: ["℘ Kap. 17,6; Jer 20,7.8; Kla 3,14"] },
      { number: 10, text: "Sie verabscheuen mich, haben sich von mir entfernt, und nicht mit Speichel für mein Gesicht gespart*.", footnotes: ["℘ Jes 50,6; Kla 3,30"] },
      { number: 11, text: "Denn er hat meine Bogensehne gelöst* und mich gedemütigt, so dass sie vor mir den Zügel schießen lassen*.", footnotes: ["d. h. Hiob ist entwaffnet, seine Kraft gebrochen", "o. sie werfen vor mir den Zaum ab; d. h. verlieren alle Hemmungen"] },
      { number: 12, text: "Zu meiner Rechten erhebt sich die Brut. Sie stoßen meine Füße weg und schütten gegen mich ihre Unheilsdämme auf*.", footnotes: ["℘ Kap. 19,12"] },
      { number: 13, text: "Sie reißen meinen Pfad auf, helfen zu meinem Untergang, und niemand hält sie dabei auf*.", footnotes: ["T.; Mas. T.: und niemand hilft ihnen, o. und niemand muss ihnen dabei helfen"] },
      { number: 14, text: "Wie durch eine breite Bresche kommen sie, unter Krachen* wälzen sie sich heran. —", footnotes: ["o. unter Verwüstung"] },
      { number: 15, text: "Plötzlicher Schrecken hat sich gegen mich gewandt*, er jagt wie der Wind meiner Würde nach; und wie eine Wolke ist meine Rettung vorübergezogen.", footnotes: ["℘ Kap. 6,4; Ps 88,16.17"] },
      { number: 16, text: "Und nun zerfließt in mir meine Seele*, die Tage des Elends packen mich.", footnotes: ["℘ Ps 22,15"] },
      { number: 17, text: "Nachts bohrt es mir meine Knochen aus, und die an mir nagenden <Schmerzen> ruhen nicht*.", footnotes: ["℘ Kap. 33,19"] },
      { number: 18, text: "Mit gewaltiger Kraft packt er* mein Gewand, wie der Kragen meines Leibrocks schnürt er mich ein.", footnotes: ["so mit LXX; Mas. T.: entstellt sich"] },
      { number: 19, text: "Er hat mich in den Dreck geworfen, so dass ich dem Staub und der Asche gleich geworden bin." },
      { number: 20, text: "Ich schreie zu dir, und du antwortest mir nicht*. Ich stehe da, doch du achtest nicht auf mich*.", footnotes: ["℘ Kap. 19,7; Ps 22,3; 88,15", "so mit einer hebr. Handschr. und Vulg.; Mas. T.: und du achtest auf mich"] },
      { number: 21, text: "In einen Grausamen verwandelst du dich mir, mit der Stärke deiner Hand feindest du mich an*.", footnotes: ["℘ Kap. 13,24"] },
      { number: 22, text: "Du hebst mich auf den Wind, du lässt mich <auf ihm> reiten und mich zergehen im Krachen <des Gewitters>." },
      { number: 23, text: "Denn ich habe es erkannt, zum Tod führst du mich zurück und in das Versammlungshaus aller* Lebendigen*.", footnotes: ["w. in das Haus des Versammlungsplatzes/Treffpunktes für alle", "℘ Jos 23,14; Pred 9,5"] },
      { number: 24, text: "Doch streckt man unter Trümmern nicht die Hand <nach Rettung> aus, oder <erhebt man> bei seinem Untergang <nicht> ein Hilfegeschrei* deswegen?", footnotes: ["Andere üs. mit Textänderung: Doch streckt ein Ertrinkender nicht die Hand aus, oder schreit er nicht beim Untergehen um Hilfe"] },
      { number: 25, text: "Oder weinte ich nicht über den, der harte Tage hatte, hatte meine Seele mit dem Armen <denn kein> Mitgefühl*?", footnotes: ["℘ Kap. 29,12-17; 31,31; Ps 35,13"] },
      { number: 26, text: "Ja, Gutes erwartete ich, und es kam Böses*. Und ich harrte auf Licht, und es kam Dunkelheit*.", footnotes: ["℘ Jer 8,15", "℘ Jes 59,9; Kla 3,2"] },
      { number: 27, text: "Meine Eingeweide sind zum Sieden gebracht und haben keine Ruhe*. Tage des Elends sind mir entgegengetreten.", footnotes: ["℘ Ps 38,8"] },
      { number: 28, text: "Trauernd gehe ich einher ohne Sonne*. Ich stehe auf in der Versammlung <und> schreie um Hilfe.", footnotes: ["Andere lesen mit Textänderung: ohne Trost"] },
      { number: 29, text: "Ich bin ein Bruder geworden den Schakalen und ein Gefährte den Straußenhennen*.", footnotes: ["℘ Ps 102,7.8; Mi 1,8"] },
      { number: 30, text: "Meine Haut ist schwarz geworden <und löst sich> von mir ab*, und mein Gebein brennt vor <Fieber>hitze*.", footnotes: ["℘ Kla 4,8", "℘ Ps 102,4; 119,83; Kla 3,4"] },
      { number: 31, text: "Und so ist meine Zither zur Trauerklage geworden und meine Flöte zur Stimme der Weinenden*.", footnotes: ["℘ Kla 5,15; Am 8,10"] },
    ]},
    { number: 31, verses: [
      { number: 1, text: "Einen Bund habe ich mit meinen Augen geschlossen. Wie hätte ich da auf eine Jungfrau <lüstern> blicken sollen*?*", heading: "Sein unsträfliches Verhalten gegen Gott und Menschen — Bereitschaft mit Gott zu rechten", footnotes: ["℘ Spr 4,25; 6,25; Mt 5,28", "Andere lesen mit Textänderung: geschlossen, nie . . . <lüstern> zu blicken."] },
      { number: 2, text: "Denn was wäre <dafür> die Zuteilung von Gott droben gewesen und das Erbteil vom Allmächtigen in den Höhen*?", footnotes: ["℘ Kap. 27,13"] },
      { number: 3, text: "Ist nicht Verderben für den Übeltäter <bestimmt> und Missgeschick für die, die Unrecht tun*?", footnotes: ["℘ 2Sam 18,10; Ri 9,53; Ps 55,24"] },
      { number: 4, text: "Sieht er nicht meine Wege* und zählt alle meine Schritte*?", footnotes: ["℘ Kap. 23,10; Spr 5,21", "℘ Kap. 14,16; Ps 139,3; Jer 16,17"] },
      { number: 5, text: "Wenn ich mit Gehaltlosem umgegangen bin und mein Fuß zum Betrug geeilt ist* —", footnotes: ["℘ Ps 26,4"] },
      { number: 6, text: "er soll mich auf der Waage der Gerechtigkeit wiegen*, so wird Gott meine Rechtschaffenheit* erkennen*!", footnotes: ["℘ Spr 21,2", "o. Unschuld; o. Lauterkeit", "℘ Kap. 23,10"] },
      { number: 7, text: "Wenn mein Schritt vom Weg abgebogen und mein Herz meinen Augen gefolgt ist* und an meinen Händen ein Makel klebt*,", footnotes: ["℘ 4Mo 15,39", "o. wenn irgendetwas an meinen Händen kleben geblieben ist\n℘ Kap. 16,17; 17,9; 23,11; 27,5.6; Ps 7,4; Jes 33,15"] },
      { number: 8, text: "dann möge ich säen und ein anderer essen*, und meine Sprösslinge mögen entwurzelt werden*!", footnotes: ["℘ 3Mo 26,16", "℘ 5Mo 28,32; Jos 22,22"] },
      { number: 9, text: "Wenn mein Herz sich wegen einer Frau hat betören lassen* und ich an der Tür meines Nächsten gelauert habe,", footnotes: ["℘ 5Mo 5,21; Jer 5,8"] },
      { number: 10, text: "<dann> soll meine Frau für einen anderen mahlen, und andere mögen über ihr niederknien*!", footnotes: ["℘ 5Mo 28,30; 2Sam 12,11"] },
      { number: 11, text: "Denn das wäre eine Schandtat und das eine Schuld, die vor die Richter gehört*.", footnotes: ["o. Und das wäre eine Schandtat, und diese ist eine Schuld für die Richter\n℘ 3Mo 20,10"] },
      { number: 12, text: "Ja, ein Feuer wäre es, das bis zum Untergang* fräße und meinen ganzen Ertrag entwurzeln* würde*.", footnotes: ["o. bis zum Ort des Verlorenseins; d. i. die Welt der Toten; hebr. Abaddon", "Andere lesen mit Textänderung: verbrennen", "℘ Spr 6,27-29"] },
      { number: 13, text: "Wenn ich missachtet habe das Recht meines Knechtes und meiner Magd in ihrem Rechtsstreit mit mir*,", footnotes: ["℘ Kol 4,1"] },
      { number: 14, text: "was wollte ich dann tun, wenn Gott sich erhöbe; und wenn er untersuchte, was ihm erwidern*?", footnotes: ["℘ 3Mo 25,43; Kol 3,25"] },
      { number: 15, text: "Hat nicht er, der mich im Mutterleib gemacht hat, <auch> ihn gemacht, und hat nicht einer im Mutterschoß uns* bereitet*?", footnotes: ["T.; Mas. T.: ihn", "℘ Kap. 34,19; Spr 22,2; Mal 2,10"] },
      { number: 16, text: "Wenn ich Geringen einen Wunsch verweigert habe*, die Augen der Witwe erlöschen ließ", footnotes: ["℘ Spr 22,22; Jes 10,2"] },
      { number: 17, text: "und meinen Bissen alleine aß, so dass die Waise nichts <mehr> davon essen konnte —" },
      { number: 18, text: "ist sie doch von meiner Jugend an bei mir aufgewachsen wie <bei> einem Vater*, und wie eine Schwester* habe ich sie* geleitet* —,", footnotes: ["℘ Kap. 29,12; Est 2,7", "w. als eine, die aus dem Leib meiner Mutter ist,", "d. i. die Witwe", "℘ Jak 1,27"] },
      { number: 19, text: "wenn ich <ruhig> zusah, wie einer ohne Kleidung umherirrte* und der Arme keine Decke hatte*,", footnotes: ["o. umkam", "℘ Jes 58,7; Mt 25,36; Jak 2,16"] },
      { number: 20, text: "wenn seine Lenden mich nicht segneten* und er sich von der Wolle* meiner Lämmer nicht wärmen durfte*,", footnotes: ["℘ Kap. 29,13", "w. von der Schur", "℘ Kap. 22,6; Sach 7,9"] },
      { number: 21, text: "wenn ich <drohend> meine Hand gegen eine Waise geschwungen habe, weil ich im Tor meinen Beistand sah*,", footnotes: ["d. h. vor Gericht durch einen Verwandten mit Beistand rechnen konnte\n℘ Ps 82,3"] },
      { number: 22, text: "dann soll mir meine Schulter vom Nacken fallen, und mein Arm soll vom Gelenk abbrechen!" },
      { number: 23, text: "Denn schrecklich wäre mir das Verderben Gottes, und seiner Hoheit könnte ich nicht standhalten*.", footnotes: ["℘ Ps 119,120"] },
      { number: 24, text: "Wenn* ich das Gold zu meiner Zuversicht gemacht und zum feinen Gold gesagt habe: Du meine Hoffnung*!", footnotes: ["Das »wenn« leitet einen Schwursatz ein, dessen zweite Hälfte, der Hauptsatz, meist nicht ausgesprochen wurde. Zum ausgeführten Hauptsatz nach dem Schwursatz vgl. V. 8.10.22.40.", "℘ Spr 11,28; 1Tim 6,17"] },
      { number: 25, text: "Wenn* ich mich freute, dass mein Vermögen so umfangreich war* und dass meine Hand Gewaltiges erreicht hatte*!", footnotes: ["Das »wenn« leitet einen Schwursatz ein, dessen zweite Hälfte, der Hauptsatz, meist nicht ausgesprochen wurde. Zum ausgeführten Hauptsatz nach dem Schwursatz vgl. V. 8.10.22.40.", "o. dass meine Kraft so groß war", "o. gefunden hatte\n℘ 5Mo 8,17; 1Sam 10,7; Jes 39,2; Lk 12,19"] },
      { number: 26, text: "Wenn* ich das Licht <der Sonne> sah, wie sie es leuchten ließ, und den Mond, wie er prächtig daherzog,", footnotes: ["Das »wenn« leitet einen Schwursatz ein, dessen zweite Hälfte, der Hauptsatz, meist nicht ausgesprochen wurde. Zum ausgeführten Hauptsatz nach dem Schwursatz vgl. V. 8.10.22.40."] },
      { number: 27, text: "und mein Herz sich <dann> im Geheimen betören ließ* und ich Kusshände warf*!", footnotes: ["℘ 5Mo 4,19; Hes 8,16", "w. und meine Hand meinen Mund küsste; d. i. eine rituelle Geste im Gestirnskult zur Huldigung der Gottheiten\n℘ 1Kö 19,18"] },
      { number: 28, text: "Auch das ist Schuld*, die vor den Richter gehört! Ich hätte ja Gott droben verleugnet.", footnotes: ["℘ 5Mo 17,2-5"] },
      { number: 29, text: "Wenn* ich mich freute über den Untergang meines Hassers und aufjauchzte*, als Unglück ihn traf*!", footnotes: ["Das »wenn« leitet einen Schwursatz ein, dessen zweite Hälfte, der Hauptsatz, meist nicht ausgesprochen wurde. Zum ausgeführten Hauptsatz nach dem Schwursatz vgl. V. 8.10.22.40.", "T.; Mas. T.: und mich aufraffte", "℘ Spr 17,5; Ob 13; Mt 5,44"] },
      { number: 30, text: "Nie habe ich ja meinem Gaumen erlaubt zu sündigen, mit einem Fluch dessen Seele zu fordern*.", footnotes: ["℘ Röm 12,14"] },
      { number: 31, text: "Wenn* die Männer in meinem Zelt nicht bezeugt* haben: Wer wäre wohl nicht von seinem Fleisch satt geworden*!", footnotes: ["Das »wenn« leitet einen Schwursatz ein, dessen zweite Hälfte, der Hauptsatz, meist nicht ausgesprochen wurde. Zum ausgeführten Hauptsatz nach dem Schwursatz vgl. V. 8.10.22.40.", "w. gesagt", "℘ Kap. 30,25; Jes 58,10"] },
      { number: 32, text: "Der Fremde musste nicht im Freien übernachten, ich öffnete dem Wanderer* meine Tür*.", footnotes: ["T.; Mas. T.: zum Weg hin", "℘ Kap. 29,16; 1Mo 19,2.3; Mt 25,35"] },
      { number: 33, text: "Wenn* ich wie Adam* meine Vergehen zugedeckt habe*, um meine Schuld in meiner Brust* zu verbergen,", footnotes: ["Das »wenn« leitet einen Schwursatz ein, dessen zweite Hälfte, der Hauptsatz, meist nicht ausgesprochen wurde. Zum ausgeführten Hauptsatz nach dem Schwursatz vgl. V. 8.10.22.40.", "o. wie Menschen <es tun>", "℘ 1Mo 3,8; Spr 28,13", "w. Brusttasche; gemeint ist die Innentasche am Brustschlitz des Beduinenhemdes"] },
      { number: 34, text: "weil ich etwa erschrocken gewesen wäre <vor> der großen Menge und die Verachtung der Sippen mich niedergeschmettert hätte, so dass ich mich still verhalten hätte, nicht zur Türe hinausgegangen wäre!" },
      { number: 35, text: "Ach hätte ich doch einen, der auf mich hörte — hier ist meine Unterschrift*! Der Allmächtige antworte mir*! <Wo ist> die <Klage>schrift, die mein Rechtsgegner geschrieben hat?", footnotes: ["w. mein taw; taw ist der letzte Buchstabe des hebr. Alphabets und galt, unter eine Urkunde gesetzt, als Unterschrift und Beglaubigungszeichen", "℘ Kap. 13,17-22"] },
      { number: 36, text: "Wahrlich, ich würde sie auf meine Schulter heben, sie mir um <den Kopf> winden als Kranz.*", footnotes: ["w. Wenn ich sie nicht auf meine Schulter höbe, sie mir als Kränze umbinden würde! — Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde."] },
      { number: 37, text: "Ich würde ihm über die Zahl meiner Schritte Auskunft geben, wie ein Fürst würde ich ihm nahen." },
      { number: 38, text: "Wenn gegen mich mein Ackerboden Anklage erhob* und seine Furchen miteinander weinten,", footnotes: ["o. um Hilfe rief\n℘ Hab 2,11"] },
      { number: 39, text: "wenn ich seinen Ertrag, ohne zu bezahlen*, verzehrt habe* und die Seele seiner Besitzer* zum Keuchen brachte*,", footnotes: ["w. seine Kraft ohne Geld", "℘ Jer 22,13", "Andere üs.: die Seele seiner Arbeiter", "℘ 1Kö 21,13"] },
      { number: 40, text: "<dann> soll statt Weizen Dorngestrüpp hervorkommen* und anstelle von Gerste Unkraut!* Zu Ende sind die Worte Hiobs.", footnotes: ["℘ 1Mo 3,18", "Die Verse 38—40 standen ursprünglich wohl hinter V. 34, so dass die Rede Hiobs mit den Versen 35—37 endete."] },
    ]},
    { number: 32, verses: [
      { number: 1, text: "Und jene drei Männer hörten auf, dem Hiob zu antworten, weil er in seinen Augen gerecht war*.", heading: "Erste Rede des Elihu: Bisherige Zurückhaltung und Unparteilichkeit — Aufforderung an Hiob zur Stellungnahme", footnotes: ["℘ Kap. 15,5; 22,5; 33,8.9; 40,8"] },
      { number: 2, text: "Da entbrannte der Zorn Elihus, des Sohnes Barachels, des Busiters, von der Sippe Ram. Gegen Hiob entbrannte sein Zorn, weil er sich Gott gegenüber im Recht betrachtete*.", footnotes: ["℘ Kap. 15,5; 22,5; 33,8.9; 40,8"] },
      { number: 3, text: "Und gegen seine drei Freunde* entbrannte sein Zorn, weil sie keine Antwort gefunden und Hiob <doch> für schuldig erklärt hatten*.", footnotes: ["℘ Kap. 42,7", "o. keine Antwort gefunden hatten, Hiob schuldig zu erklären. — Die alten Abschreiber merken hier an, dass sie den Text geändert haben. Der Text lautete ursprünglich: und <so> Gott für schuldig erklärt hatten\n℘ Kap. 22,5"] },
      { number: 4, text: "Elihu aber hatte sich Hiob gegenüber zurückgehalten mit Reden*, weil jene die Älteren an Jahren* waren als er*.", footnotes: ["w. hatte gewartet . . . mit Worten. — Andere üs. mit Textänderung: hatte gewartet, während jene mit Hiob redeten", "w. an Tagen", "℘ 3Mo 19,32; Pred 3,7"] },
      { number: 5, text: "Und als Elihu sah, dass keine Antwort <mehr> in dem Mund der drei Männer war, da entbrannte sein Zorn*.", footnotes: ["℘ Jak 1,19"] },
      { number: 6, text: "Und Elihu, der Sohn des Barachel, der Busiter, hob an und sagte: Ich bin der Jüngste an Jahren*, und ihr seid Greise. Darum hatte ich Angst und fürchtete mich, euch mein Wissen zu verkünden*.", footnotes: ["w. an Tagen", "℘ Kap. 12,12-14"] },
      { number: 7, text: "Ich sagte <mir>: Mag <erst> das Alter* reden, soll die Menge der Jahre Weisheit erkennen lassen!", footnotes: ["w. Mögen <erst> die Tage"] },
      { number: 8, text: "Jedoch — es ist der Geist im Menschen und der Atem des Allmächtigen, der sie verständig werden lässt*.", footnotes: ["℘ 1Mo 41,38; 1Kö 5,9; Spr 2,6; 20,27; Jes 28,26; 2Tim 1,7"] },
      { number: 9, text: "Nicht <nur> die Betagten* sind die Weisen, noch verstehen <stets> die Alten, was recht ist*.", footnotes: ["w. die Großen <an Tagen>", "℘ Kap. 4,21; 12,20; Ps 119,100"] },
      { number: 10, text: "Darum sage ich: Hört* mir zu! Auch ich will mein Wissen verkünden.", footnotes: ["so mit 2 hebr. Handschr., LXX, Vulg. und der syr. Üs.; Mas. T.: Höre"] },
      { number: 11, text: "Siehe, ich wartete auf eure Worte, horchte auf eure einsichtigen <Reden>, bis ihr <die rechten> Worte ausfindig gemacht hättet*.", footnotes: ["o. während ihr <den rechten> Worten nachspürtet"] },
      { number: 12, text: "Und ich wandte euch meine Aufmerksamkeit zu, doch siehe, keiner war da, der Hiob widerlegt hätte*, <keiner> von euch, der seine Worte erwidert hätte.", footnotes: ["o. zurechtgewiesen hätte"] },
      { number: 13, text: "Dass ihr <aber ja> nicht sagt: Wir haben Weisheit gefunden; Gott kann ihn aus dem Felde schlagen*, nicht ein Mensch!", footnotes: ["w. kann ihn verwehen <wie der Wind die Spreu>"] },
      { number: 14, text: "Er hat ja nicht an mich <seine> Worte gerichtet, und mit euren Worten werde ich ihm nicht erwidern. —" },
      { number: 15, text: "Sie sind bestürzt, sie antworten nicht mehr, die Worte lassen sie im Stich." },
      { number: 16, text: "Soll ich da warten, weil sie nicht reden, weil sie dastehen <und> nicht mehr antworten?" },
      { number: 17, text: "Auch ich will meinerseits mein Teil erwidern*, auch ich will mein Wissen verkünden.", footnotes: ["T.; Mas. T.: So will ich meinerseits mich an mein Teil kehren"] },
      { number: 18, text: "Denn erfüllt bin ich mit Worten; der Geist in meinem Innern bedrängt mich." },
      { number: 19, text: "Siehe, mein Inneres ist wie <junger> Wein, der nicht geöffnet ist; gleich neu <gefüllten> Schläuchen will es bersten*.", footnotes: ["℘ Jer 20,9; Am 3,8"] },
      { number: 20, text: "Ich muss reden, damit ich Luft bekomme, ich will meine Lippen auftun und antworten*.", footnotes: ["℘ Kap. 4,2"] },
      { number: 21, text: "Für keinen werde ich Partei ergreifen*, und keinem Menschen werde ich schmeicheln!*", footnotes: ["℘ 3Mo 19,15; Ps 82,2; Mal 2,9; Joh 7,24", "w. Niemals will ich jemandes Gesicht erheben, und einem Menschen werde ich keinen Ehrennamen geben."] },
      { number: 22, text: "Denn ich verstehe mich nicht aufs Schmeicheln* *; sonst würde mein Schöpfer mich <wohl> bald dahinraffen*.", footnotes: ["o. ich kenne es nicht zu schmeicheln", "℘ Kap. 33,3; Spr 28,23; Gal 1,10; 1Thes 2,5; Jud 16", "℘ Ps 12,3.4"] },
    ]},
    { number: 33, verses: [
      { number: 1, text: "Du aber, Hiob, höre doch meine Reden, und all meine Worte nimm zu Ohren!" },
      { number: 2, text: "Sieh doch, ich habe meinen Mund aufgetan, meine Zunge redet in meinem Gaumen." },
      { number: 3, text: "Geradheit meines Herzens — <das> sind meine Worte, und lauter künden meine Lippen Erkenntnis*.", footnotes: ["℘ Kap. 32,21.22; Spr 4,2; Eph 4,25"] },
      { number: 4, text: "Der Geist Gottes hat mich gemacht, und der Atem des Allmächtigen belebt mich*.", footnotes: ["℘ 1Mo 2,7; Ps 104,30"] },
      { number: 5, text: "Wenn du kannst, gib mir Antwort, bring <sie> vor, stelle dich vor mich hin!" },
      { number: 6, text: "Siehe, ich bin vor Gott so viel wie du*, vom Lehm <nur> abgekniffen bin auch ich*.", footnotes: ["o. ich stehe zu Gott so gut wie du", "℘ Kap. 10,9; Apg 14,15"] },
      { number: 7, text: "Siehe, Angst vor mir* braucht dich nicht zu erschrecken, und mein Drängen* wird nicht schwer auf dir lasten*.", footnotes: ["Manche lesen mit anderer Vokalisierung: Siehe, mein Arm", "o. meine Hand", "℘ Kap. 9,32-34"] },
      { number: 8, text: "Du sagtest doch vor meinen Ohren — und den Laut <deiner> Worte höre ich <noch> —:", heading: "Abwehr der Anklagen Hiobs gegen Gott — Gottes Zucht zum Heil der Seele — Aufforderung zur Stellungnahme oder zum Zuhören" },
      { number: 9, text: "Lauter bin ich, ohne ein Vergehen*. Rein bin ich und habe keine Schuld*.", footnotes: ["o. ohne <Treue>bruch", "℘ Kap. 13,18.23; 16,17; 17,9; 23,10-12; 27,5.6; 32,1; 34,5.6; 35,2"] },
      { number: 10, text: "Siehe, er erfindet Anlässe zum Widerstand gegen mich, er hält mich für seinen Feind*.", footnotes: ["℘ Kap. 9,17.28.29; 13,24"] },
      { number: 11, text: "Er legt meine Füße in den Block, überwacht alle meine Pfade*. —", footnotes: ["℘ Kap. 14,16"] },
      { number: 12, text: "Siehe, darin bist du nicht im Recht*, antworte ich dir; denn Gott ist größer als ein Mensch*.", footnotes: ["o. bist du nicht gerecht", "℘ Kap. 11,6-9; 36,22.26"] },
      { number: 13, text: "Warum rechtest du mit ihm*, weil er auf all seine Worte* keine Antwort gibt*?", footnotes: ["℘ Kap. 10,2", "d. h. auf die Worte des Menschen; andere üs. mit Textänderung: auf deine Worte", "℘ Kap. 9,12"] },
      { number: 14, text: "Doch auf eine Weise redet Gott und auf eine zweite*, und man wird es nicht gewahr*.", footnotes: ["o. Einmal redet Gott und ein zweites Mal\n℘ Ps 62,12; Hebr 1,1", "℘ Spr 1,24"] },
      { number: 15, text: "Im Traum, in der nächtlichen Vision, wenn tiefer Schlaf auf die Menschen fällt, im Schlummer auf dem Lager*,", footnotes: ["℘ Kap. 4,13"] },
      { number: 16, text: "dann öffnet er das Ohr der Menschen* und bestätigt* die Warnung für sie*,", footnotes: ["℘ Kap. 36,10.15", "w. versiegelt", "Andere üs. mit Textänderung: und schreckt sie durch Warnung auf"] },
      { number: 17, text: "um den Menschen von <seinem> Tun abzuwenden* und den Hochmut vom Mann abzuhauen*,", footnotes: ["℘ 1Mo 20,3-6", "T.; Mas. T.: um den Hochmut vor dem Mann zu bedecken"] },
      { number: 18, text: "um seine Seele zurückzuhalten von der Grube und sein Leben davon, in den Spieß zu rennen*.", footnotes: ["℘ Kap. 36,12"] },
      { number: 19, text: "Auch wird er gezüchtigt durch Schmerzen auf seinem Lager, und ununterbrochen <währt> der Streit in seinen Gebeinen*.", footnotes: ["℘ Kap. 29,17; Ps 38,4-8; Pred 8,6"] },
      { number: 20, text: "Und sein Leben verabscheut das Brot und seine Seele die Lieblingsspeise*.", footnotes: ["℘ Ps 107,18"] },
      { number: 21, text: "Sein Fleisch vergeht, ist unansehnlich, und fleischlos sind seine Knochen, die <sonst> nicht zu sehen waren*.", footnotes: ["℘ Kap. 19,20"] },
      { number: 22, text: "Und seine Seele nähert sich der Grube* und sein Leben den Todesboten*.", footnotes: ["℘ Ps 107,18", "w. den Tötenden"] },
      { number: 23, text: "Wenn er da einen Engel bei sich hat, einen Mittler*, einen von den Tausend, der dem Menschen seine Pflicht mitteilen soll*,", footnotes: ["o. Fürsprecher\n℘ Kap. 9,33; 1Tim 2,5.6", "o. einen von den Tausend, die dem Menschen das für ihn Rechte mitteilen sollen"] },
      { number: 24, text: "so wird der sich über ihn erbarmen und sprechen: Befreie ihn, damit er nicht in die Grube hinabfährt*! Ich habe Lösegeld <für ihn> gefunden*.", footnotes: ["℘ Ps 107,20", "℘ Jes 53,5"] },
      { number: 25, text: "Sein Fleisch wird frischer sein als in der Jugendkraft*; er wird zurückkehren zu den Tagen seiner Jugend*.", footnotes: ["Die Üs. ist unsicher; deshalb lesen andere: Sein Fleisch wird fett sein vor Jugend\n℘ 2Kö 5,14", "℘ Ps 103,5"] },
      { number: 26, text: "Er wird zu Gott flehen, und der wird ihn gnädig annehmen*, und er darf sein Angesicht schauen* mit Jubel; und Gott* wird dem Menschen seine Gerechtigkeit zurückgeben.", footnotes: ["o. wird an ihm Gefallen haben", "℘ Kap. 19,27", "w. er"] },
      { number: 27, text: "Er wird vor den Menschen singen und sagen: Ich hatte gesündigt und das Rechte verkehrt, und er hat mir nicht vergolten*.", footnotes: ["T.; Mas. T.: und es genügte mir nicht\n℘ Ps 103,10; Hes 14,23; Lk 15,21"] },
      { number: 28, text: "Er hat meine Seele erlöst vor dem Abstieg in die Grube*, und mein Leben darf das Licht schauen*.", footnotes: ["℘ Ps 103,4", "℘ Ps 56,14"] },
      { number: 29, text: "Siehe, das alles tut Gott zweimal, dreimal mit dem Mann," },
      { number: 30, text: "um seine Seele von der Grube zurückzuholen, damit er vom Licht des Lebens erleuchtet werde*.", footnotes: ["℘ Ps 56,14"] },
      { number: 31, text: "Merke auf, Hiob, höre mir zu! Schweige, und ich will reden!" },
      { number: 32, text: "Wenn du Worte hast, erwidere mir <etwas>! Rede nur, denn ich wollte dir gern recht geben*!", footnotes: ["o. dich gern für gerecht erklären"] },
      { number: 33, text: "Wenn <aber> nicht, höre du mir zu! Schweige, und ich werde dich Weisheit lehren*!", footnotes: ["℘ Ps 34,12"] },
    ]},
    { number: 34, verses: [
      { number: 1, text: "Und Elihu erhob <seine Stimme> und sagte*:", heading: "Zweite Rede des Elihu: Gegen Hiobs Reden über die Ungerechtigkeit Gottes — Keine Rechtsbeugung durch den Allmächtigen", footnotes: ["℘ Kap. 32,6; 35,1; 36,1"] },
      { number: 2, text: "Hört, ihr Weisen, meine Worte und ihr Kundigen, gebt mir Gehör*!", footnotes: ["℘ Spr 1,5"] },
      { number: 3, text: "Denn das Ohr prüft die Worte, und der Gaumen kostet die Speise*.", footnotes: ["℘ Kap. 6,30"] },
      { number: 4, text: "Lasst uns nun prüfen, was recht ist, lasst uns untereinander erkennen, was gut ist*!", footnotes: ["℘ 1Thes 5,21"] },
      { number: 5, text: "Denn Hiob hat gesagt: Ich bin gerecht*, und Gott hat mir mein Recht entzogen*.", footnotes: ["℘ Kap. 33,9", "℘ Kap. 19,7; 27,2"] },
      { number: 6, text: "Obwohl ich im Recht bin*, soll ich ein Lügner sein. Mein Geschick* ist unheilbar, ohne dass ich irgendetwas verbrochen hätte*. —", footnotes: ["w. Gegen mein Recht", "o. Mein Pfeil; das hieße dann: die mir vom Pfeil Gottes verursachte Wunde", "w. ohne Verbrechen\n℘ Kap. 33,9"] },
      { number: 7, text: "Wer ist ein Mann wie Hiob, der Spott<worte> wie Wasser trinkt*", footnotes: ["℘ Kap. 11,3; 15,16; 36,17"] },
      { number: 8, text: "und in Gemeinschaft mit denen unterwegs ist, die Unrecht tun, und mit gottlosen Menschen umgeht?" },
      { number: 9, text: "Denn er hat <selbst> gesagt: Keinen Nutzen hat ein Mann davon, dass er sich mit Gott befreundet*!", footnotes: ["℘ Kap. 9,22; 21,15; 22,3; Jes 58,3; Mal 3,14"] },
      { number: 10, text: "Darum, ihr Männer mit Verstand, hört mir zu! Fern sei es von Gott, gottlos zu handeln, und vom Allmächtigen, Unrecht zu tun*!", footnotes: ["T.; Mas. T.: Fern sei es von Gott, weg von Schuld, und der Allmächtige <sei fern> von Unrecht\n℘ 5Mo 32,4; Ps 92,16; 145,17; Zef 3,5; Offb 16,5"] },
      { number: 11, text: "Sondern des Menschen Tun vergilt er ihm, und nach eines jeden Weg lässt er es ihn finden*.", footnotes: ["℘ 1Sam 26,23; Spr 24,12; Jer 17,10; Hes 18,13; Röm 2,6; Offb 22,12"] },
      { number: 12, text: "Ja, wahrlich, Gott handelt nicht gottlos, und der Allmächtige beugt das Recht nicht*.", footnotes: ["℘ Kap. 8,3; 36,23; 1Mo 18,25; Ps 145,17"] },
      { number: 13, text: "Wer hat ihm die Erde* anvertraut? Und wer hat den ganzen Erdkreis hingestellt*?", footnotes: ["Eine hebr. Handschr. überliefert, den Sinn verdeutlichend: seine Erde", "℘ Ps 24,1.2"] },
      { number: 14, text: "Wenn er sein Herz <nur> auf sich selbst richtete, seinen Geist und seinen Atem zu sich zurückzöge," },
      { number: 15, text: "so würde alles Fleisch insgesamt verscheiden, und der Mensch zum Staub zurückkehren*.", footnotes: ["℘ Kap. 10,9; Pred 12,7; Jak 2,26"] },
      { number: 16, text: "Und wenn du einsichtig bist*, höre dies, schenke der Stimme meiner Worte Gehör!", footnotes: ["so mit LXX, Vulg., der syr. und aram. Üs.; Mas. T.: wenn Einsicht <da ist>"] },
      { number: 17, text: "Kann denn einer, der das Recht hasst, die Zügel führen*? Oder willst du den Gerechten, den Gewaltigen für schuldig erklären*, ihn,", footnotes: ["℘ Röm 3,6", "℘ Kap. 40,8"] },
      { number: 18, text: "der zu einem König sagt* »du Ruchloser«, und »du Gottloser« zu den Edlen?", footnotes: ["so mit LXX, Vulg., der syr. Üs. und einer hebr. Handschr.; Mas. T.: etwa, um zum König zu sagen"] },
      { number: 19, text: "Der für die Obersten nicht Partei ergreift* und den Vornehmen nicht vor dem Geringen berücksichtigt*? Denn das Werk seiner Hände sind sie alle*.", footnotes: ["w. Der die Gesichter der Obersten nicht erhebt", "℘ 5Mo 10,17; Röm 2,11; Jak 2,1\nw. genau betrachtet", "℘ Kap. 31,15"] },
      { number: 20, text: "In einem Augenblick sterben sie und mitten in der Nacht. Ein Volk wird in Aufruhr versetzt, und sie vergehen*. Und er beseitigt* den Gewalthaber ohne menschliches Zutun*.", footnotes: ["℘ Kap. 36,20; 2Mo 12,29; Jes 37,36", "so mit einer hebr. Handschr.; Mas. T.: sie beseitigen", "w. und nicht durch eine Hand\n℘ Jes 40,23; Dan 8,25"] },
      { number: 21, text: "Denn seine Augen <wachen> über den Wegen des Menschen, und all seine Schritte sieht er*.", footnotes: ["℘ Kap. 14,16; Spr 15,3"] },
      { number: 22, text: "Da ist keine Dunkelheit und keine Finsternis*, worin sich die Übeltäter verbergen könnten*.", footnotes: ["℘ Kap. 3,5; 12,22", "℘ Kap. 10,14; 22,13; 2Sam 12,12; Ps 139,11.12; Jer 16,17"] },
      { number: 23, text: "Denn er setzt dem Menschen keine Frist fest*, zu Gott vor Gericht zu kommen*.", footnotes: ["T.; Mas. T.: er richtet auf den Menschen nicht lange <sein Herz>", "℘ Kap. 9,3"] },
      { number: 24, text: "Er zerschmettert Gewaltige ohne Untersuchung und setzt andere an ihre Stelle*.", footnotes: ["℘ 1Sam 15,28; Dan 11,19"] },
      { number: 25, text: "Daher achtet er auf ihre Taten* und stürzt sie um* über Nacht, dass sie zermalmt daliegen.", footnotes: ["℘ Offb 2,2.19", "so mit der syr. Üs.; Mas. T.: er stürzt um"] },
      { number: 26, text: "Wie Gottlose schlägt er sie da, wo alle es sehen*,", footnotes: ["w. An Stelle von Gottlosen schlägt er sie an der Stätte der Sehenden"] },
      { number: 27, text: "deshalb, weil sie* von seiner Nachfolge* abgewichen sind* und all seine Wege nicht bedacht haben,", footnotes: ["w. sie, die darüber hinaus", "w. von hinter ihm her", "℘ 2Chr 28,6.23; Jes 1,28; Jer 2,17.19; Spr 15,10"] },
      { number: 28, text: "so dass sie das Hilfegeschrei des Geringen zu ihm hinaufdringen ließen und er das Hilfegeschrei der Elenden hörte*.", footnotes: ["℘ 2Mo 22,22; Ps 5,3; Jak 5,4"] },
      { number: 29, text: "Verhält er sich ruhig*, wer darf ihn für schuldig erklären? Verbirgt er das Angesicht, wer kann ihn wahrnehmen*? Sowohl über einer <ganzen> Nation als auch zugleich über dem Einzelnen* <wacht er>*,", footnotes: ["o. Schafft er Ruhe", "℘ Kap. 23,8.9", "o. Sowohl über einer <einzelnen> Nation als auch über der Menschheit insgesamt", "℘ Ps 94,10.12"] },
      { number: 30, text: "damit nicht ruchlose Menschen Könige seien, dem Volk zu Fallstricken." },
      { number: 31, text: "Soll Gott dir etwa sagen: Ich habe mich geirrt, <doch>* ich will nicht <mehr> böse handeln*;", footnotes: ["T.; Mas. T.: Denn zu Gott — hat er <etwa> gesagt: Ich habe es getragen; d. h. vielleicht: Ich habe gebüßt", "℘ Spr 28,13"] },
      { number: 32, text: "was ich nicht sehe, lehre du mich*; wenn ich Unrecht verübt habe, will ich es nicht wieder tun*? —", footnotes: ["℘ Ps 19,13", "℘ 1Mo 38,26; 4Mo 22,34; Jer 8,6"] },
      { number: 33, text: "Soll nach deinem Sinn er es vergelten*, da du <sein Urteil> ja verwirfst? So musst du ja wählen, und nicht ich. Was du erkannt hast, sprich aus!", footnotes: ["℘ Ps 50,21"] },
      { number: 34, text: "Männer mit Verstand werden zu mir sagen und ein weiser Mann, der mir zuhört:" },
      { number: 35, text: "Hiob redet nicht mit Erkenntnis, und seine Worte sind ohne Einsicht*.", footnotes: ["℘ Kap. 35,16; 38,2"] },
      { number: 36, text: "Ach, dass Hiob doch fort und fort geprüft würde wegen seiner Einwände nach <der Art von> Männern des Unheils!" },
      { number: 37, text: "Denn er fügt seiner Sünde <Treue>bruch* hinzu, in unserer Gegenwart klatscht er <sich Beifall>* und macht seine Worte gegen Gott zahlreich.", footnotes: ["o. Verbrechen", "o. erhebt er unter uns Zweifel"] },
    ]},
    { number: 35, verses: [
      { number: 1, text: "Und Elihu erhob <seine Stimme> und sagte*:", heading: "Dritte Rede des Elihu: Bedeutung des Tuns des Menschen — Keine Erhörung bei Gott bei Mangel an Gottesfurcht", footnotes: ["℘ Kap. 32,6; 34,1"] },
      { number: 2, text: "Hältst du dies für Recht, nennst du <das> »meine Gerechtigkeit vor Gott«," },
      { number: 3, text: "wenn du fragst, was sie dir nützt: »Was* hilft es mir, dass ich nicht sündige*?« —", footnotes: ["Andere üs. mit Textänderung: dass du sagst: Was nützt es mir, was", "℘ Kap. 21,15"] },
      { number: 4, text: "Ich will mit Worten dir erwidern und deinen Gefährten bei dir." },
      { number: 5, text: "Blicke zum Himmel und sieh und schaue die Wolken an! Sie sind höher als du*.", footnotes: ["o. zu hoch für dich\n℘ Kap. 11,7-9; 22,12; Jes 55,8.9; Mt 16,23"] },
      { number: 6, text: "Wenn du sündigst, was kannst du ihm <damit> antun? Werden zahlreich deine Verbrechen, was kannst du ihm zufügen*?", footnotes: ["℘ Kap. 7,20"] },
      { number: 7, text: "Wenn du gerecht bist, was gibst du ihm, oder was empfängt er aus deiner Hand*?", footnotes: ["℘ Kap. 22,2; Röm 11,35"] },
      { number: 8, text: "Den Mann, dir gleich, <trifft> deine Gottlosigkeit und das Menschenkind deine Gerechtigkeit." },
      { number: 9, text: "Wegen der Menge der Unterdrückung* erhebt man Klagegeschrei. Man ruft um Hilfe wegen der Gewalttätigkeit* der Großen*.", footnotes: ["2 griech. Üs., Vulg., die aram. und syr. Üs. sowie eine hebr. Handschr. überliefern: Unterdrücker", "w. wegen des Arms", "℘ Pred 4,1"] },
      { number: 10, text: "Aber man sagt nicht: Wo ist Gott, mein Schöpfer*, der Lobgesänge gibt in der Nacht*,", footnotes: ["℘ Jer 2,6.8", "℘ Ps 149,5; Apg 16,25; Röm 1,21"] },
      { number: 11, text: "der uns mehr als die Tiere der Erde belehrt und uns weiser macht als die Vögel des Himmels?" },
      { number: 12, text: "Dort schreien sie — doch er antwortet nicht — wegen des Übermutes der Bösen." },
      { number: 13, text: "Ja, vergebens! Gott hört nicht, und der Allmächtige sieht es nicht an*.", footnotes: ["℘ Ps 66,18"] },
      { number: 14, text: "Nun gar, wenn du sagst: du kannst ihn nicht sehen*! Der Rechtsfall <liegt> ihm vor, so warte auf ihn*!", footnotes: ["℘ Kap. 9,11", "o. Nun gar, wenn du sagst, du sähest ihn nicht; der Rechtsfall <läge> ihm vor und du wartetest auf ihn\n℘ Ps 37,7; Jes 8,17; Kla 3,58; Mi 7,9"] },
      { number: 15, text: "Und nun, weil sein Zorn <noch> nicht heimgesucht hat und er sich nicht so sehr um Albernheiten* kümmert*,", footnotes: ["o. Arroganz; o. Übermaß <an Worten>; zwei griech. Üs. und Vulg. lesen: um Verbrechen", "o. und er nicht so sehr Albernheiten kennt"] },
      { number: 16, text: "reißt Hiob für Nichtiges* seinen Mund auf, macht ohne Erkenntnis viele Worte*.", footnotes: ["w. <für> Wind", "℘ Kap. 34,35.37"] },
    ]},
    { number: 36, verses: [
      { number: 1, text: "Und Elihu fuhr fort und sagte*:", heading: "Vierte Rede des Elihu: Durch Leiden zu Selbsterkenntnis und Gehorsam — Mahnung an Hiob zur Anerkennung von Gottes Tun", footnotes: ["℘ Kap. 32,6; 34,1"] },
      { number: 2, text: "Hab ein wenig Geduld mit mir, und ich will es dir künden! Denn mehr noch habe ich für Gott zu sagen*.", footnotes: ["o. Denn noch stehen Gott Worte zu Gebote; w. Denn noch gibt es für Gott Worte"] },
      { number: 3, text: "Ich will mein Wissen von weither holen* und meinem Schöpfer Gerechtigkeit geben.", footnotes: ["o. fernhin tragen"] },
      { number: 4, text: "Ja wahrlich, meine Worte sind keine Lüge*; ein <Mann> mit vollkommenem Wissen <steht> vor dir.", footnotes: ["℘ Spr 8,7"] },
      { number: 5, text: "Siehe, Gott ist gewaltig, doch verwirft er niemanden*; er ist gewaltig an Kraft des Herzens*.", footnotes: ["w. verwirft er nicht", "o. gewaltig an Kraft <und> Verstand\n℘ Kap. 37,23; Ps 147,5"] },
      { number: 6, text: "Er erhält den Gottlosen nicht am Leben*, und das Recht der Elenden stellt er <wieder> her*.", footnotes: ["℘ Ps 55,24", "℘ Ps 140,13"] },
      { number: 7, text: "Nicht wendet er seine Augen von dem Gerechten*, und mit Königen auf dem Thron, da lässt er sie immerdar sitzen, so dass sie erhaben sind*.", footnotes: ["℘ Ps 33,16", "℘ 1Sam 2,8; 2Sam 7,16; Offb 3,21"] },
      { number: 8, text: "Und wenn sie in Fesseln geschlagen, in Stricken des Elends gefangen sind*,", footnotes: ["℘ Ps 107,10"] },
      { number: 9, text: "dann zeigt er ihnen ihr Tun und ihre Vergehen*, dass sie sich überheblich gebärdeten,", footnotes: ["o. <Treue>brüche; o. Verbrechen"] },
      { number: 10, text: "und er öffnet ihr Ohr für Zucht und sagt <ihnen>, dass sie umkehren sollen vom Unrecht*.", footnotes: ["℘ Kap. 33,16"] },
      { number: 11, text: "Wenn sie hören und sich unterwerfen, vollenden sie ihre Tage im Glück und ihre Jahre in Annehmlichkeiten*.", footnotes: ["℘ 2Chr 33,13; Ps 119,3; Spr 1,33; Jer 7,23"] },
      { number: 12, text: "Wenn sie aber nicht hören, rennen sie in den Spieß* und verscheiden ohne Erkenntnis*.", footnotes: ["℘ Kap. 33,18; 1Sam 12,25; Jes 1,20", "℘ Kap. 4,21"] },
      { number: 13, text: "Aber die ein ruchloses Herz haben, hegen Zorn. Sie rufen nicht um Hilfe, wenn er sie fesselt." },
      { number: 14, text: "Ihre Seele stirbt dahin in der Jugend* und ihr Leben unter den Geweihten*.", footnotes: ["℘ Kap. 22,16", "Das sind männliche Kultprostituierte. — Die aram. Üs. liest: und ihr Leben gleicht den Geweihten"] },
      { number: 15, text: "Den Elenden rettet er in seinem* Elend* und öffnet durch Bedrängnis sein* Ohr.", footnotes: ["o. durch sein", "℘ Ps 72,12; 107,41", "w. ihr (Mehrzahl)"] },
      { number: 16, text: "Auch dich lockt er fort aus dem Rachen der Not, unbeengte Weite ist dein* Platz*, und was auf deinen Tisch kommt, ist reich an Fett*.", footnotes: ["T.; Mas. T.: ihr", "℘ Ps 18,20", "℘ Ps 63,6\nw. und die Niederlassung (o. die Ruhe) deines Tisches ist voll Fett"] },
      { number: 17, text: "Bist du aber mit dem Urteil über den Gottlosen erfüllt*, werden Urteil und Rechtsspruch <dich> ergreifen*.", footnotes: ["℘ Kap. 34,7-9", "℘ Spr 11,21"] },
      { number: 18, text: "Ja, dass <deine> Erregung dich nur nicht zum Höhnen anstiftet und die Größe des Lösegeldes dich nicht verleitet!" },
      { number: 19, text: "Soll dich dein Hilferuf aus der Not herausbringen* und alle Kraftanstrengungen?", footnotes: ["T.; andere üs. mit Textänderung: Könnte <denn> gegen ihn antreten dein Hilferuf in der Not; Mas. T.: Könnte <denn> antreten dein Hilferuf nicht in der Not"] },
      { number: 20, text: "Lechze nicht nach der Nacht, <danach,> dass <ganze> Völker auffahren an ihrer Stelle*!", footnotes: ["o. der Nacht, die Völker von ihrer Stelle auffahren lässt\n℘ Kap. 34,20"] },
      { number: 21, text: "Hüte dich, wende dich nicht dem Unrecht zu! Denn Bosheit hast du dem Elend <bereits> vorgezogen*.", footnotes: ["T.; andere üs. mit Textänderung: Denn deswegen bist du vom Elend geprüft worden; Mas. T.: Denn deswegen hast du vor dem Elend geprüft, o. Denn deswegen hast du dem Elend vorgezogen\n℘ Kap. 7,11"] },
      { number: 22, text: "Siehe, Gott handelt erhaben in seiner Macht*. Wer ist ein Lehrer wie er*?", footnotes: ["℘ Kap. 33,12", "℘ Ps 119,102; Joh 3,2"] },
      { number: 23, text: "Wer könnte ihm seinen Weg vorschreiben*, und wer dürfte sagen: Du hast unrecht getan*?", footnotes: ["o. Wer könnte ihn für seinen Weg zur Rechenschaft ziehen\n℘ Kap. 21,22; Jes 40,13", "℘ Kap. 34,10.12; Röm 9,14.20"] },
      { number: 24, text: "Denke daran, dass du sein Werk preist, das Menschen besingen*!", footnotes: ["℘ Offb 15,3"] },
      { number: 25, text: "Alle Menschen schauen es <staunend> an*, der Sterbliche erblickt es aus der Ferne.", footnotes: ["℘ Röm 1,20"] },
      { number: 26, text: "Siehe, Gott ist erhaben, wir aber erkennen es nicht*; die Zahl seiner Jahre, sie ist unerforschlich*.", heading: "Offenbarung von Gottes Majestät in der Natur — Mahnung zur Demütigung vor Gott", footnotes: ["o. ist <so> erhaben, dass wir <ihn> nicht erkennen\n℘ Ps 145,3", "℘ Ps 90,2"] },
      { number: 27, text: "Wenn er die Wassertropfen heraufzieht, sickern sie durch seinen Nebel <wieder herab> als Regen*,", footnotes: ["o. Denn er nimmt die Wassertropfen weg, dass sie für seinen Quellstrom (o. für seine Flut) als Regen <durch die Wolken> hindurchsickern\n℘ Kap. 5,10; Spr 3,20; Sach 10,1"] },
      { number: 28, text: "den die Wolken niederrieseln <und> träufeln auf die vielen Menschen*.", footnotes: ["℘ Mt 5,45"] },
      { number: 29, text: "Ja, wenn man gar das Ausbreiten des Gewölks verstünde, das Donnerkrachen seines Zeltes*!", footnotes: ["℘ Kap. 28,26; Ps 77,19"] },
      { number: 30, text: "Siehe, er breitet darüber* sein Licht aus*, und die Wurzeln des Meeres bedeckt er.", footnotes: ["o. um sich", "℘ Ps 104,2"] },
      { number: 31, text: "Ja, in den Wolken* richtet er* die Völker*, gibt Nahrung im Überfluss*.", footnotes: ["w. in ihnen", "Andere üs. mit Textänderung: nährt er", "℘ Kap. 37,13", "℘ Ps 65,13.14; Apg 14,17"] },
      { number: 32, text: "Seine Hände umhüllt er mit dem Blitzstrahl* und entbietet ihn* gegen <den>, auf den er <ihn> treffen lassen will*.", footnotes: ["w. mit Licht", "so mit vielen hebr. Handschr.; Mas. T.: entbietet sie (weiblich)", "o. und entbietet ihn gegen den Angreifer. — Andere üs. mit Textänderung: entbietet ihn ins Ziel\n℘ Kap. 38,35; Ps 18,15"] },
      { number: 33, text: "Es kündigt ihn sein Rollen* an*, wenn er seinen Zorn gegen Bosheit eifern lässt*.", footnotes: ["w. sein Geschrei", "℘ Ps 29,3.4", "so mit anderer Vokalisierung; Mas. T.: sein Rollen an, Viehbesitz, Zorn (o. sogar) über den Heraufkommenden"] },
    ]},
    { number: 37, verses: [
      { number: 1, text: "Ja, darüber erbebt mein Herz und fährt auf von seiner Stelle." },
      { number: 2, text: "Hört, hört das Toben seiner Stimme und das Grollen, das aus seinem Mund hervorgeht*!", footnotes: ["℘ Kap. 28,26; 40,9"] },
      { number: 3, text: "Unter dem ganzen Himmel lässt er es los und seinen Blitz* bis zu den Enden* der Erde*.", footnotes: ["w. sein Licht", "w. Flügelspitzen", "℘ Kap. 38,35; Ps 97,4; Mt 24,27"] },
      { number: 4, text: "Nach ihm brüllt der Donner, er lässt es mit seiner erhabenen Stimme donnern. Und er hält die Blitze* nicht zurück, wenn seine Stimme sich hören lässt*.", footnotes: ["w. sie", "℘ Kap. 28,26; 40,9"] },
      { number: 5, text: "Gott donnert mit seiner Stimme wunderbar*. Er tut <so> große Dinge, und wir erkennen* es nicht*.", footnotes: ["℘ Ps 18,14", "o. begreifen", "℘ Kap. 9,10; 26,14"] },
      { number: 6, text: "Denn zum Schnee spricht er: Fall zur Erde*! — und <so auch> zum Regenguss und zu seinen gewaltigen Regengüssen*.", footnotes: ["℘ Ps 147,16", "℘ Kap. 5,10"] },
      { number: 7, text: "Auf die Hand eines jeden Menschen setzt er <sein> Siegel, damit alle Menschen sein Werk erkennen." },
      { number: 8, text: "Und das Wild geht in sein Versteck und legt sich auf seinen Lagern nieder*.", footnotes: ["℘ Ps 104,22"] },
      { number: 9, text: "Aus der Kammer kommt Sturm hervor* und aus den Nordwinden* Kälte*.", footnotes: ["℘ Jes 21,1; Sach 9,14", "w. den <die Wolken> Zerstreuenden", "℘ Spr 25,23"] },
      { number: 10, text: "Durch den Atem Gottes gibt es Eis*, und die Weite des Wassers <liegt> in Enge.", footnotes: ["℘ Kap. 38,29; Ps 147,17"] },
      { number: 11, text: "Auch mit Nass belastet er die Wolke, streut <weit> umher sein lichtes Gewölk*.", footnotes: ["℘ Kap. 26,8"] },
      { number: 12, text: "Und das <zieht> ringsumher, sich hin und her wendend nach seiner klugen Steuerung, um auszuführen alles, was* er ihnen gebietet, über der Fläche des Erdkreises*.", footnotes: ["w. zu ihrem (der Wolken) Werk, <zu> all <dem>, was, o. . . . zu deren (der Menschen) Werk", "℘ Ps 148,8"] },
      { number: 13, text: "Sei es zur Züchtigung*, sei es für seine Erde, sei es zur Gnade, er lässt sie es finden*.", footnotes: ["w. zum Stab, o. zur Rute\n℘ Kap. 36,31", "℘ Kap. 38,27; 1Kö 18,45; Ps 65,10; Joe 2,23.24"] },
      { number: 14, text: "Nimm dieses zu Ohren, Hiob! Steh still und achte auf die Wundertaten Gottes*!", footnotes: ["℘ Ps 111,2; Pred 7,13"] },
      { number: 15, text: "Erkennst du es, wenn Gott ihnen Auftrag gibt und leuchten lässt das Licht seines Gewölks*?", footnotes: ["o. Auftrag gibt, dass sein leuchtendes Gewölk strahlend aufgeht\n℘ Kap. 28,25.26"] },
      { number: 16, text: "Erkennst du das Schweben der Wolke, die Wunderwerke dessen, der an Erkenntnis vollkommen ist?" },
      { number: 17, text: "Du, dessen Kleider heiß werden, wenn das Land wegen des Südwindes <träge> ruht," },
      { number: 18, text: "kannst du gleich ihm* die Wolkendecke ausbreiten*, die fest ist wie ein gegossener Spiegel?", footnotes: ["o. mit ihm", "℘ Jes 40,22"] },
      { number: 19, text: "Lass uns wissen, was wir ihm sagen sollen! Nichts können wir vorbringen vor Finsternis*.", footnotes: ["mit anderer Vokalisierung: vor Sprachlosigkeit\n℘ Kap. 40,4.5"] },
      { number: 20, text: "Soll ihm gemeldet werden, dass ich rede? Oder muss man es <ihm erst> sagen, dass <etwas> mitgeteilt wird*?", footnotes: ["o. Oder hat <je> einer gesagt, dass er verschlungen werden wolle\n℘ Hab 2,20"] },
      { number: 21, text: "Und jetzt sieht man das Licht nicht, das durch die Wolken verdunkelt ist*; aber ein Wind fährt daher und fegt den Himmel* rein.", footnotes: ["Andere üs.: das hinter den Wolken hell glänzt", "w. ihn, o. sie (die Wolken)"] },
      { number: 22, text: "Aus dem Norden kommt ein goldener Schein*, um Gott ist furchtbare Hoheit*.", footnotes: ["w. kommt Gold", "℘ Ps 68,35.36; 89,8"] },
      { number: 23, text: "Den Allmächtigen — ihn erreichen wir nicht, den Erhabenen an Kraft*. Und das Recht und die Fülle der Gerechtigkeit beugt er nicht*.*", footnotes: ["℘ Kap. 9,4; 11,7.8; 36,5; Ps 62,12; 145,3", "℘ Kap. 8,3; Ps 36,7; 99,4", "Andere üs. mit der syr. Üs. und bei veränderter Zeichensetzung: ihn, der erhaben ist an Kraft und reich an Gerechtigkeit, er beugt das Recht nicht."] },
      { number: 24, text: "Darum fürchten ihn die Menschen*; er sieht all die Weisheitskundigen nicht an*.", footnotes: ["℘ Ps 33,8; Jer 5,22; Jon 1,16", "o. er sieht keinen an, der sich weise dünkt; w. er sieht nicht an all die Weisen des Herzens\n℘ Mt 11,25; 1Kor 3,19"] },
    ]},
    { number: 38, verses: [
      { number: 1, text: "Da antwortete der HERR dem Hiob aus dem Sturm und sprach*:", heading: "Erste Rede Gottes: Fragen nach dem Urheber der Schöpfung, der leblosen und belebten Natur", footnotes: ["℘ Kap. 11,5; 40,1.6; Hes 1,4; Nah 1,3"] },
      { number: 2, text: "Wer ist es, der den Ratschluss verdunkelt mit Worten ohne Erkenntnis*?", footnotes: ["℘ Kap. 34,35; 42,3"] },
      { number: 3, text: "Gürte doch wie ein Mann deine Lenden*! Dann will ich dich fragen, und du sollst mich belehren*!", footnotes: ["℘ Lk 12,35", "w. und du lass es mich wissen\n℘ Kap. 21,22; 40,2.7; 42,4"] },
      { number: 4, text: "Wo warst du, als ich die Erde gründete*? Teile es mit, wenn du Einsicht kennst!", footnotes: ["℘ Kap. 15,7; Ps 102,26; Spr 3,19"] },
      { number: 5, text: "Wer hat ihre Maße bestimmt, wenn du es kennst? Oder wer hat über ihr die Messschnur ausgespannt*?", footnotes: ["℘ Kap. 28,25"] },
      { number: 6, text: "Worauf sind ihre Sockel eingesenkt? Oder wer hat ihren Eckstein gelegt*,", footnotes: ["℘ 1Sam 2,8"] },
      { number: 7, text: "als die Morgensterne miteinander jubelten und alle Söhne Gottes* jauchzten?", footnotes: ["℘ Kap. 2,1"] },
      { number: 8, text: "Wer hat* das Meer mit Türen verschlossen, als es hervorbrach, dem Mutterschoß entquoll*,", footnotes: ["so. mit Vulg.; Mas. T.: Und er hat", "℘ 1Mo 1,9.10"] },
      { number: 9, text: "als ich Gewölk zu seinem Gewand machte und Wolkendunkel zu seinen Windeln" },
      { number: 10, text: "und ich ihm meine Grenze zog* und Riegel und Türen einsetzte", footnotes: ["w. brach; nämlich aus dem Gestein"] },
      { number: 11, text: "und sprach: Bis hierher kommst du und nicht weiter, und hier soll aufhören der Stolz* deiner Wellen*?", footnotes: ["T.; Mas. T.: hier setzt er <eine Schranke> gegen den Stolz", "℘ Kap. 26,10; Ps 104,9; Spr 8,29; Jer 5,22"] },
      { number: 12, text: "Hast du einmal in deinem Leben* dem Morgen geboten? Hast du die Morgenröte ihre Stätte wissen lassen,", footnotes: ["w. <an einem> von deinen Tagen"] },
      { number: 13, text: "damit sie die Enden* der Erde erfasse*, so dass die Gottlosen von ihr abgeschüttelt werden*?", footnotes: ["w. Flügelspitzen", "℘ Ps 19,5-7", "℘ Kap. 24,13-17"] },
      { number: 14, text: "Sie* verwandelt sich wie Siegelton*, und alles steht da* wie ein Kleid;", footnotes: ["d. h. die Erde", "d. h. wie Ton, auf den ein Siegel eingedrückt wird", "w. und sie stellen sich hin. — Andere üs. mit Textänderung: und sie färbt sich"] },
      { number: 15, text: "und den Gottlosen wird ihr Licht entzogen*, und der erhobene Arm wird zerbrochen*.", footnotes: ["℘ Kap. 24,13-17", "℘ Ps 10,15"] },
      { number: 16, text: "Bist du gekommen bis zu den Quellen des Meeres, und hast du den Urgrund der Tiefe durchwandelt?" },
      { number: 17, text: "Sind dir die Tore des Todes aufgedeckt worden, und hast du die Tore der Finsternis gesehen?" },
      { number: 18, text: "Hast du auf die Breiten der Erde geachtet? Teile es <mir> mit, wenn du das alles erkannt hast!" },
      { number: 19, text: "Wo ist denn der Weg dahin, wo das Licht wohnt? Und die Finsternis — wo ist denn ihre Stätte," },
      { number: 20, text: "so dass du sie in ihr Gebiet bringen könntest und dass dir die Pfade zu ihrem Haus bekannt wären*?", footnotes: ["Andere lesen mit Textänderung: und dass du sie auf die Pfade zu ihrem Haus führtest"] },
      { number: 21, text: "Du hast es <ja> erkannt, denn damals warst du <schon> geboren, und die Zahl deiner Tage ist groß!" },
      { number: 22, text: "Bist du bis zu den Vorräten* des Schnees gekommen, und hast du die Vorräte* des Hagels gesehen*,", footnotes: ["o. Schatzkammern", "o. Schatzkammern", "℘ Ps 147,16.17"] },
      { number: 23, text: "die ich aufgespart habe für die Zeit der Not, für den Tag des Kampfes und der Schlacht*?", footnotes: ["℘ Jos 10,11; Hes 13,13"] },
      { number: 24, text: "Wo denn ist der Weg, auf dem das Licht sich verteilt, der Ostwind sich über die Erde zerstreut*?", footnotes: ["℘ 2Mo 14,21"] },
      { number: 25, text: "Wer furchte der Regenflut einen Wassergraben und einen Weg der donnernden Gewitterwolke*,", footnotes: ["℘ Kap. 28,26"] },
      { number: 26, text: "um regnen zu lassen* auf ein Land ohne Menschen, auf die Wüste, in der kein Mensch ist,", footnotes: ["℘ Jer 10,13"] },
      { number: 27, text: "um zu sättigen die Öde und Verödung und um hervorsprießen zu lassen die Triebe des frischen Grases*?", footnotes: ["℘ Kap. 37,13; Ps 107,35; 147,8"] },
      { number: 28, text: "Hat der Regen einen Vater, oder wer hat die Tautropfen gezeugt?" },
      { number: 29, text: "Aus wessen Schoß kam das Eis hervor*, und des Himmels Reif, wer hat ihn geboren*,", footnotes: ["℘ Kap. 37,10", "℘ Ps 147,16.17"] },
      { number: 30, text: "wenn sich das Wasser wie in einem Stein versteckt hält und die Fläche der Tiefe fest gefügt ist*?", footnotes: ["℘ Kap. 37,10"] },
      { number: 31, text: "Knüpfst du die Bänder des Siebengestirns, oder löst du die Fesseln des Orion?" },
      { number: 32, text: "Kannst du die Tierkreisbilder hervortreten lassen zu ihrer Zeit und den Großen Bären* leiten samt seinen Jungen*?", footnotes: ["℘ Kap. 9,9", "o. den Löwen mit seinen Kindern; mit »Kinder« könnten die bei den Arabern zum Sternbild des »Löwen« gehörenden »Hunde« gemeint sein"] },
      { number: 33, text: "Hast du die Ordnungen des Himmels erkannt, oder bestimmst du seine Herrschaft auf der Erde*?", footnotes: ["o. oder erlegst du seine Himmelsschrift der Erde auf"] },
      { number: 34, text: "Erhebst du deine Stimme zum Gewölk, so dass der Schwall des Wassers dich bedeckt?" },
      { number: 35, text: "Entsendest du Blitze, so dass sie hinfahren und zu dir sagen: Hier sind wir*?", footnotes: ["℘ Kap. 36,32; 37,3"] },
      { number: 36, text: "Wer hat Weisheit in den Ibis* gelegt, oder wer hat dem Hahn Verstand gegeben?", footnotes: ["Andere üs.: ins Innere <des Menschen>"] },
      { number: 37, text: "Wer kann in Weisheit die Wolken zählen, und die Krüge des Himmels — wer kippt sie um*,", footnotes: ["d. h. damit der Inhalt ausfließt\n℘ 1Mo 7,11"] },
      { number: 38, text: "wenn das Erdreich hart wird wie gegossenes Metall* und die Schollen aneinander kleben?", footnotes: ["w. wenn der Staub sich ergießt zu Metallguss"] },
      { number: 39, text: "Erjagst du für die Löwin die Beute, und stillst du die Gier der jungen Löwen*,", footnotes: ["℘ Ps 104,21"] },
      { number: 40, text: "wenn sie sich auf <ihren> Lagern ducken, im Dickicht auf der Lauer sitzen*?", footnotes: ["℘ Ps 10,9"] },
      { number: 41, text: "Wer stellt dem Raben sein Futter bereit, wenn seine Jungen zu Gott schreien, umherirren ohne Nahrung*?", footnotes: ["℘ Ps 147,9; Lk 12,24"] },
    ]},
    { number: 39, verses: [
      { number: 1, text: "Kennst du die Wurfzeit der Steinböcke*? Beobachtest du das Kreißen der Hirschkühe*?", footnotes: ["℘ Ps 104,18", "℘ Ps 29,9"] },
      { number: 2, text: "Zählst du die Monate, die sie erfüllen müssen, und kennst du die Zeit ihres Werfens?" },
      { number: 3, text: "Sie kauern sich, lassen ihre Jungen durchbrechen, entledigen sich ihrer Wehen*.", footnotes: ["o. setzen ihre Kitze <ins Freie>"] },
      { number: 4, text: "Ihre Kinder werden stark, wachsen auf im Freien; sie ziehen hinaus und kehren nicht <mehr> zu ihnen zurück." },
      { number: 5, text: "Wer hat den Wildesel* frei laufen lassen, und wer hat die Fesseln des Wildlings* gelöst*,", footnotes: ["o. das Zebra", "d. i. ein anderer Name für den Wildesel", "℘ Kap. 24,5; 1Mo 16,12; Hos 8,9"] },
      { number: 6, text: "dem ich die Steppe zur Behausung machte und zu seiner Wohnung das salzige Land*?", footnotes: ["℘ Jer 2,24"] },
      { number: 7, text: "Er lacht über das Getümmel der Stadt, das Geschrei des Treibers hört er nicht." },
      { number: 8, text: "Was er auf den Bergen erspäht, ist seine Weide*, und allem Grünen spürt er nach*.", footnotes: ["o. Der Umkreis der Berge ist seine Weide. — Andere üs. mit mehreren alten Üs.: Er erkundet die Berge, seine Weide", "℘ Kap. 6,5"] },
      { number: 9, text: "Wird der Büffel dir dienen wollen, oder wird er an deiner Krippe übernachten?" },
      { number: 10, text: "Hältst du den Büffel in der Furche an seinem Seil, oder wird er die Talgründe hinter dir her eggen?" },
      { number: 11, text: "Traust du ihm, weil seine Kraft so groß ist*, und überlässt du ihm deine Arbeit*?", footnotes: ["℘ 4Mo 23,22", "o. deinen Arbeitsertrag"] },
      { number: 12, text: "Kannst du dich auf ihn verlassen, dass er dein Korn heimbringt und <das Getreide für> deine Tenne einsammelt*?", footnotes: ["so mit der Leseform des Mas. T.; andere üs. mit der Schreibform: Kannst du dich auf ihn verlassen, dass er zurückkehrt und das Korn deiner Tenne einsammelt"] },
      { number: 13, text: "Munter schwingt sich der Flügel der Straußenhenne — ist es die Schwinge des Storches* oder des Falken*?", footnotes: ["o. des Reihers; T.; Mas. T.: die Schwinge, der Storch, o. die fromme Schwinge", "Wortbedeutung unsicher; andere üs.: ist es die Schwinge des Storches und <sein> Gefieder"] },
      { number: 14, text: "Denn sie überlässt ihre Eier der Erde und lässt sie auf dem Staub warm werden." },
      { number: 15, text: "Und sie vergisst, dass ein Fuß sie zerdrücken und das Wild des Feldes sie zertreten kann." },
      { number: 16, text: "Sie behandelt ihre Jungen hart*, als gehörten sie ihr nicht. War ihre Mühe umsonst, es erschüttert sie nicht*.", footnotes: ["so mit hebr. Handschr.; Mas. T.: Er hat ihre Jungen hart behandelt", "℘ Kla 4,3"] },
      { number: 17, text: "Denn Gott ließ sie die Weisheit vergessen und gab ihr keinen Anteil an der Einsicht." },
      { number: 18, text: "Wenn sie dann aber* in die Höhe schnellt, lacht sie über das Ross und seinen Reiter.", footnotes: ["w. Zu dem Zeitpunkt, da sie"] },
      { number: 19, text: "Gibst du dem Ross die Kraft*, bekleidest du seinen Hals mit einer Mähne?", footnotes: ["℘ Ps 33,17; 147,10"] },
      { number: 20, text: "Bringst du es zum Springen wie die Heuschrecke? Schrecklich ist sein hoheitsvolles Schnauben." },
      { number: 21, text: "Es scharrt* in der Ebene und freut sich an <seiner> Kraft; es zieht aus*, den Waffen entgegen.", footnotes: ["so mit LXX, Vulg. und der syr. Üs.; Mas. T.: Sie scharren", "Andere ordnen die Satzteile anders zu als die Masoreten und üs.: und freut sich; mit Kraft zieht es aus"] },
      { number: 22, text: "Es lacht über die Furcht und erschrickt nicht und kehrt vor dem Schwert nicht um." },
      { number: 23, text: "Über ihm klirrt der Köcher, die Klinge von Speer und Kurzschwert." },
      { number: 24, text: "Mit Ungestüm und Erregung schlürft es den Boden* und lässt sich nicht halten, wenn das Horn ertönt*.", footnotes: ["d. h. bringt es schnell eine große Entfernung hinter sich", "℘ Jer 8,6"] },
      { number: 25, text: "Sooft das Horn erklingt, ruft es: Hui! Und <schon> von weitem wittert es die Schlacht, das Lärmen der Obersten und das Kriegsgeschrei*.", footnotes: ["℘ Sach 10,3"] },
      { number: 26, text: "Schwingt sich kraft deiner Einsicht der Falke empor, breitet seine Flügel aus für den Südwind?" },
      { number: 27, text: "Oder erhebt sich auf deinen Befehl der Geier so hoch und baut in der Höhe sein Nest*?", footnotes: ["℘ Jer 49,16; Ob 4"] },
      { number: 28, text: "Den Fels bewohnt er und horstet* <dort> auf der Felsenzacke und der Bergfeste.", footnotes: ["w. bleibt über Nacht"] },
      { number: 29, text: "Von dort aus erspäht er Nahrung, in die Ferne blicken seine Augen." },
      { number: 30, text: "Seine Jungen gieren nach Blut, und wo Erschlagene sind, da ist er*.", footnotes: ["℘ Mt 24,28; Lk 17,36"] },
    ]},
    { number: 40, verses: [
      { number: 1, text: "Und der HERR antwortete dem Hiob und sprach*:", heading: "Hiobs Antwort: Einsichtige Zurücknahme der Anklagen gegen Gott", footnotes: ["℘ Kap. 38,1"] },
      { number: 2, text: "Mit dem Allmächtigen will der Tadler rechten? Der da Gott zurechtweist, er antworte darauf*!", footnotes: ["o. der muss es verantworten\n℘ Kap. 38,3; Jes 45,9; Röm 9,20"] },
      { number: 3, text: "Da antwortete Hiob dem HERRN und sagte*:", footnotes: ["℘ Kap. 3,2; 42,1"] },
      { number: 4, text: "Siehe, zu gering bin ich*! Was kann ich dir erwidern? Ich lege meine Hand auf meinen Mund*.", footnotes: ["℘ Kap. 42,6", "℘ Kap. 21,5; 37,19; Hes 16,63"] },
      { number: 5, text: "Einmal habe ich geredet, und ich will nicht <mehr> antworten*; und zweimal, und ich will es nicht wieder tun.", footnotes: ["o. und will nicht <mehr meine Stimme> erheben"] },
      { number: 6, text: "Und der HERR antwortete Hiob aus dem Sturm und sprach*:", heading: "Zweite Rede Gottes: Beweis der Macht Gottes durch Bestrafung der Hochmütigen — Seine Gewalt über den Behemot und den Leviatan", footnotes: ["℘ Kap. 38,1"] },
      { number: 7, text: "Gürte doch wie ein Mann deine Lenden! Ich will dich fragen, und du sollst mich belehren*!", footnotes: ["o. und du lass es mich wissen\n℘ Kap. 38,3"] },
      { number: 8, text: "Willst du etwa mein Recht zerbrechen*, mich für schuldig erklären*, damit du gerecht dastehst*?", footnotes: ["o. Willst du wirklich mein Urteil anfechten", "℘ Kap. 34,17", "℘ Kap. 32,2; Jes 43,26; Röm 3,4"] },
      { number: 9, text: "Oder hast du einen Arm wie Gott*, und donnerst du mit einer Stimme wie er*?", footnotes: ["℘ Jos 4,24; Ps 98,1; Jes 52,10", "℘ Kap. 37,4.5; Ps 29,3-5"] },
      { number: 10, text: "Schmücke dich doch mit Erhabenheit und Hoheit, in Majestät und Pracht kleide dich*!", footnotes: ["℘ Ps 93,1"] },
      { number: 11, text: "Streue die Ausbrüche deines Zornes umher* und schau alles Hochmütige an und erniedrige es*!", footnotes: ["℘ Kap. 9,5", "℘ Ps 94,2"] },
      { number: 12, text: "Schau alles Hochmütige an, beuge es und tritt die Gottlosen nieder auf ihrer Stelle*!", footnotes: ["℘ Ps 94,2"] },
      { number: 13, text: "Verbirg sie allesamt im Staub, banne sie selbst an einen verborgenen Ort*!", footnotes: ["w. binde ihre Gesichter im Verborgenen\n℘ 1Sam 2,9.10; Jud 6"] },
      { number: 14, text: "Dann werde auch ich dich preisen, weil deine Rechte dir zur Hilfe kommt." },
      { number: 15, text: "Sieh doch den Behemot*, den ich mit dir gemacht habe! Gras frisst er wie das Rind.", footnotes: ["d. i. wahrscheinlich das Nilpferd; nach anderen: das Krokodil; w. gewaltiges Tier"] },
      { number: 16, text: "Sieh doch seine Kraft in seinen Lenden und seine Stärke in den Muskeln seines Bauches!" },
      { number: 17, text: "Er lässt seinen Schwanz gleich einer Zeder hängen*, die Sehnen seiner Schenkel sind <dicht> geflochten.", footnotes: ["die alten Üs.: Er hält seinen Schwanz steif gleich einer Zeder"] },
      { number: 18, text: "Röhren aus Bronze sind seine Knochen und seine Gebeine wie Stangen aus Eisen." },
      { number: 19, text: "Er ist der Anfang* der Wege Gottes. Der ihn gemacht, hat <ihm> sein Schwert beschafft*.", footnotes: ["o. der Erste", "Andere üs. mit Textänderung in Anlehnung an LXX: Er ist gemacht zum Gewalthaber seiner Gefährten"] },
      { number: 20, text: "Denn die Berge bringen ihm Tribut, und alle Tiere des Feldes, die dort spielen." },
      { number: 21, text: "Unter Lotosbüschen* lagert er im Versteck von Rohr und Sumpf.", footnotes: ["o. Unter Zweigen"] },
      { number: 22, text: "Die Lotosbüsche, sein Schatten, bedecken ihn; es umgeben ihn die Bachpappeln." },
      { number: 23, text: "Siehe, der Strom schwillt mächtig an — er hastet nicht davon. Er fühlt sich sicher, <selbst> wenn ein Jordan* gegen sein Maul hervorbricht.", footnotes: ["Andere üs. mit Textänderung: wenn die Flut"] },
      { number: 24, text: "<Wer> kann ihm in seine Augen greifen, ihm in der Falle* die Nase durchbohren?", footnotes: ["o. mit dem Stellholz"] },
      { number: 25, text: "Ziehst du den Leviatan* mit der Angel herbei, und hältst du mit dem Seil seine Zunge nieder?", footnotes: ["d. i. ein Meeresungeheuer; nach anderen das Krokodil\n℘ Kap. 3,8; 26,13; Ps 104,26; Hes 32,2"] },
      { number: 26, text: "Kannst du einen Binsenstrick durch seine Nase ziehen und mit einem Dorn seine Kinnlade durchbohren*?", footnotes: ["℘ Jes 37,29"] },
      { number: 27, text: "Wird er dich lange anflehen oder dir schmeichelnde Worte geben?" },
      { number: 28, text: "Wird er einen Bund mit dir schließen, dass du ihn zum Knecht nimmst für ewig?" },
      { number: 29, text: "Willst du mit ihm spielen wie mit einem Vogel und ihn für deine Mädchen anbinden?" },
      { number: 30, text: "Werden die Handelsgenossen um ihn feilschen*, ihn verteilen unter die Kaufleute?", footnotes: ["o. ein Festmahl über ihm veranstalten"] },
      { number: 31, text: "Kannst du seine Haut mit Spießen spicken* und seinen Kopf mit der Fischharpune?", footnotes: ["w. voll machen"] },
      { number: 32, text: "Lege nur deine Hand an ihn! Denk an den Kampf! Du wirst es nicht noch einmal tun!" },
    ]},
    { number: 41, verses: [
      { number: 1, text: "Siehe, die Hoffnung auf ihn* erweist sich als trügerisch. Wird man nicht schon bei seinem Anblick* niedergeworfen?", footnotes: ["d. h. darauf, den Leviatan zu fangen", "o. wegen seines Aussehens"] },
      { number: 2, text: "Niemand ist so tollkühn, dass er ihn aufreizte. — Und wer ist es, der vor mir bestehen könnte*?", footnotes: ["℘ Kap. 9,4; Spr 21,30; Apg 5,39"] },
      { number: 3, text: "Wer hat mir zuvor gegeben, dass ich ihm vergelten sollte?* <Was> unter dem ganzen Himmel <ist>, mir gehört es!*", footnotes: ["℘ Röm 11,35", "Andere üs. mit vielen hebr. Handschr., LXX und Textänderungen: Wer ist es, der vor ihm bestehen könnte? 3 Wer ist es, der ihm begegnet und unversehrt bliebe? Unter dem ganzen Himmel gibt es ihn nicht!\n℘ 2Mo 19,5; Ps 24,1; Hag 2,8"] },
      { number: 4, text: "Nicht schweigen will ich von seinen Gliedern und von seiner Kraftfülle* und von der Schönheit* seines Baues*.", footnotes: ["w. von der Sache mit seiner Kraftfülle o. mit seinen mächtigen Taten", "so mit anderer Vokalisierung; Wortbedeutung sonst unbekannt", "Andere üs. V. 4 mit Textänderung: Keiner lässt seine Macht verstummen noch seine Kraftfülle ohnegleichen"] },
      { number: 5, text: "Wer deckte die Oberseite seines Gewandes* auf? In sein Doppelgebiss*, wer dringt da hinein?", footnotes: ["d. h. die dem Betrachter zugekehrte harte Rückenpartie", "LXX: In seinen Doppelpanzer"] },
      { number: 6, text: "Wer öffnete die Türflügel seines Gesichts*? Rings um seine Zähne <lauert> Schrecken.", footnotes: ["syr. Üs.: seines Rachens"] },
      { number: 7, text: "Ein Stolz sind die* Schuppenreihen*, verschlossen und fest versiegelt*.", footnotes: ["LXX und Vulg.: Sein Rücken <besteht aus>", "w. Rinnen der Schilde", "w. geschlossen mit einem Siegel der Engigkeit. — LXX: verschlossen mit Siegeln aus Kiesel"] },
      { number: 8, text: "Eins fügt sich ans andere, und kein Hauch dringt dazwischen," },
      { number: 9, text: "eins haftet am andern*, sie greifen ineinander und trennen sich nicht.", footnotes: ["w. jedes mit seinem Bruder sind sie zusammengeklebt"] },
      { number: 10, text: "Sein Niesen strahlt Licht aus, und seine Augen sind wie die Wimpern* der Morgenröte*.", footnotes: ["o. Strahlen", "℘ Kap. 3,9"] },
      { number: 11, text: "Aus seinem Rachen schießen Fackeln, sprühen feurige Funken hervor." },
      { number: 12, text: "Aus seinen Nüstern fährt Rauch wie aus einem angefachten und glühenden Kochtopf*.", footnotes: ["T.; Mas. T.: wie aus einem angefachten Kochtopf und <von einer qualmenden> Binse"] },
      { number: 13, text: "Sein Atem* entzündet Kohlen, und eine Flamme fährt aus seinem Rachen.", footnotes: ["w. Seine Seele"] },
      { number: 14, text: "In seinem Hals wohnt Stärke, und vor ihm hüpft die Angst her." },
      { number: 15, text: "Die Wampen seines Fleisches haften zusammen, sind ihm fest angegossen, unbeweglich." },
      { number: 16, text: "Sein Herz ist fest wie Stein und fest wie der untere Mühlstein." },
      { number: 17, text: "Vor seinem Erheben fürchten sich Machthaber, vor Bestürzung ziehen sie sich zurück*.", footnotes: ["Manche üs. mit anderer Wortabtrennung: die Brandung des Meeres zieht sich zurück."] },
      { number: 18, text: "Trifft man ihn mit dem Schwert, es hält nicht stand, noch Speer, noch Wurfspieß oder Harpune*.", footnotes: ["w. Pfeilspitze"] },
      { number: 19, text: "Er hält Eisen für Stroh <und> Kupfer für faules Holz." },
      { number: 20, text: "Der Pfeil* kann ihn nicht vertreiben, Schleudersteine verwandeln sich für ihn in Stoppeln.", footnotes: ["w. Der Sohn des Bogens"] },
      { number: 21, text: "Wie Stoppeln gilt ihm die Keule, und er lacht über den Aufprall des Kurzschwertes." },
      { number: 22, text: "Unter ihm* sind <scharfe> Tonscherben, auf dem Schlamm breitet er einen Dreschschlitten aus.", footnotes: ["d. h. an seinem Bauch"] },
      { number: 23, text: "Er bringt die Meerestiefe zum Sieden wie einen Kochtopf, macht das Meer wie einen Salbentopf." },
      { number: 24, text: "Hinter sich lässt er den Pfad hell werden, man hält die Tiefe für graues Haar." },
      { number: 25, text: "Auf Erden ist keiner ihm gleich, ihm, der zur Unerschrockenheit geschaffen ist." },
      { number: 26, text: "Auf alles Hohe blickt er <herab>; er ist König über alles stolze Wild*.", footnotes: ["w. die Söhne des Stolzen"] },
    ]},
    { number: 42, verses: [
      { number: 1, text: "Und Hiob antwortete dem HERRN und sagte*:", heading: "Hiobs Antwort: Anerkenntnis der Größe Gottes und bußfertiger Widerruf seiner Anklagen", footnotes: ["℘ Kap. 3,2; 40,3"] },
      { number: 2, text: "Ich habe erkannt, dass du alles vermagst* und kein Plan für dich unausführbar ist*.", footnotes: ["℘ Jer 32,17; Mt 19,26", "o. kein Gedanke unmöglich ist\n℘ Ps 135,6; Jes 14,27; Dan 4,32"] },
      { number: 3, text: "»Wer ist es, der den Ratschluss verhüllt ohne Erkenntnis*?« *So habe ich denn <meine Meinung> mitgeteilt und verstand <doch> nichts, Dinge, die zu wunderbar für mich sind* und die ich nicht kannte*.", footnotes: ["℘ Kap. 38,2", "o. So sprach ich denn, ohne zu begreifen — unfassbar ist es mir, ich versteh es nicht <mehr> —: 4 »Höre doch, ich will reden, will dich fragen, und du sollst es mich wissen lassen!«", "℘ Kap. 11,7-9; Ps 139,6", "℘ 2Petr 2,12"] },
      { number: 4, text: "Höre doch, und ich will reden! Ich will dich fragen, und du sollst es mich wissen lassen*!*", footnotes: ["℘ Kap. 38,3", "o. So sprach ich denn, ohne zu begreifen — unfassbar ist es mir, ich versteh es nicht <mehr> —: 4 »Höre doch, ich will reden, will dich fragen, und du sollst es mich wissen lassen!«"] },
      { number: 5, text: "Vom Hörensagen* hatte ich von dir gehört, jetzt aber hat mein Auge dich gesehen*.", footnotes: ["w. Von der Nachricht für das Ohr", "℘ Jes 6,1.5"] },
      { number: 6, text: "Darum verwerfe ich <mein Geschwätz> und bereue in Staub und Asche*.", footnotes: ["℘ Kap. 40,4; Dan 9,3; Lk 5,8"] },
      { number: 7, text: "Und es geschah, nachdem der HERR jene Worte zu Hiob geredet hatte, da sprach der HERR zu Elifas von Teman*: Mein Zorn ist entbrannt gegen dich und gegen deine beiden Freunde*: Denn ihr habt über mich nicht Wahres* geredet wie mein Knecht Hiob.", heading: "Verurteilung und Begnadigung der Freunde Hiobs — Hiobs Rechtfertigung", footnotes: ["℘ Kap. 2,11", "℘ Kap. 32,3", "o. Zuverlässiges; w. etwas, das feststeht und Bestand hat"] },
      { number: 8, text: "Und nun nehmt euch sieben Stiere und sieben Widder* und geht zu meinem Knecht Hiob und opfert ein Brandopfer für euch! Und Hiob, mein Knecht, soll für euch Fürbitte tun*. Nur ihn will ich annehmen*, damit ich euch nicht Schimpfliches antue. Denn ihr habt über mich nicht Wahres* geredet, wie mein Knecht Hiob.", footnotes: ["℘ 4Mo 23,1", "℘ 1Jo 5,16", "w. Nur sein Gesicht will ich erheben", "o. Zuverlässiges; w. etwas, das feststeht und Bestand hat"] },
      { number: 9, text: "Da gingen Elifas von Teman und Bildad von Schuach <und> Zofar von Naama* hin und taten es, wie der HERR zu ihnen geredet hatte. Und der HERR nahm Hiob an*.", footnotes: ["℘ Kap. 2,11", "w. erhob Hiobs Gesicht\n℘ Kap. 22,30; 1Mo 20,17"] },
      { number: 10, text: "Und der HERR wendete das Geschick Hiobs, als der für seine Freunde Fürbitte tat. Und der HERR vermehrte alles, was Hiob gehabt hatte, auf das Doppelte*.", heading: "Gottes Segen über Hiob", footnotes: ["℘ Kap. 8,7; Jes 61,7"] },
      { number: 11, text: "Da kamen zu ihm all seine Brüder und all seine Schwestern und alle, die ihn früher gekannt hatten*. Und sie aßen mit ihm Brot in seinem Haus, und sie bekundeten ihm ihre Teilnahme und trösteten ihn* wegen all des Unglücks, das der HERR über ihn gebracht hatte. Und sie gaben ihm jeder eine Kesita* und jeder einen goldenen Ring.", footnotes: ["℘ Kap. 19,13.14; Spr 14,20", "℘ Kap. 2,11", "d. i. eine Gewichtseinheit; z. B. bei Gold als Zahlungsmittel"] },
      { number: 12, text: "Und der HERR segnete das Ende Hiobs mehr als seinen Anfang*. Und er bekam vierzehntausend Schafe und sechstausend Kamele und tausend Gespanne Rinder und tausend Eselinnen*.", footnotes: ["℘ 5Mo 8,16; Jak 5,11", "℘ Kap. 1,2.3"] },
      { number: 13, text: "Und es wurden ihm sieben* Söhne und drei Töchter <geboren>*.", footnotes: ["Im Hebr. steht eine Mischform aus »sieben« und »zwei mal sieben«.", "℘ Kap. 1,2.3"] },
      { number: 14, text: "Und er gab der ersten den Namen Jemima und der zweiten den Namen Kezia und der dritten den Namen Keren-Happuch*.", footnotes: ["Die Namen bedeuten: Turteltaube, Zimtblüte, Schminkhorn."] },
      { number: 15, text: "Und so schöne Frauen wie die Töchter Hiobs fand man im ganzen Land nicht. Und ihr Vater gab ihnen ein Erbteil mitten unter ihren Brüdern*.", footnotes: ["℘ 4Mo 27,7"] },
      { number: 16, text: "Und Hiob lebte nach diesen <Ereignissen noch> 140 Jahre. Und er sah seine Kinder und seine Kindeskinder, vier Generationen*.", footnotes: ["℘ 1Mo 50,23; Ps 128,6; Spr 17,6"] },
      { number: 17, text: "Und Hiob starb, alt und der Tage satt*.", footnotes: ["℘ Kap. 5,26; 1Mo 25,8; Jak 5,11"] },
    ]},
  ]
};
